void check(P p) {
    LL x, y;
    x = p.S, y = p.F;
    for(int i = max(x - 2, 1ll); i <= min(x, W); ++i) {
        for(int j = max(y - 2, 1ll); j <= min(y, H); ++j) {
            int cnt = 0;
            bool f = true;
            for(int k = i; k <= i + 2; ++k) {
                for(int l = j; l <= j + 2; ++l) {
                    if(k > W || l > H) {
                        cnt = 0;
                        f = false;
                        break;
                    }
                    if(!f) break;
                    if(mp[MP(l, k)]) ++cnt;
                }
            }
            if(cnt != 0)
                st[cnt].insert(MP(ch(i, j), ch(i + 2, j + 2)));
        }
    }

    return;
}

LL ch(LL x, LL y) {
    return W * (y - 1) + (x - 1);
}

