int compress(int n, vl &X, ll w) {
  vector<ll> xs;
  rep(i, 0, n) {
    for (int d = -1; d <= 1; d++) {
      int tx = X[i]+d;
      if (1 <= tx && tx <= w) xs.pb(tx);
    }
  }

  sort(All(xs));
  xs.erase(unique(All(xs)), xs.end());
  rep(i, 0, n) {
    X[i] = lbidx(xs, X[i]);
  }

  return xs.size();
};

int main() {
