  vl X(n), Y(n);
  rep(i, 0, n) {
    cin >> Y[i] >> X[i];
  }

  ll W = compress(n, X, w);
  ll H = compress(n, Y, h);

  vector<vector<bool>> grid(H, vector<bool> (W, false));
  map<PLL, int> mp;
  rep(i, 0, n) {
    grid[Y[i]][X[i]] = true;
    mp[make_pair(Y[i], X[i])] = i;
  }

  vl ans(10, 0ll);
  vector<vector<bool>> counted(n, vector<bool> (9, false));
  rep(i, 0, n) {
    ll xi = X[i];
    ll yi = Y[i];
    rep(j, 0, 9) { // 黒い点についてどの位置としてカウントされるか
      // カウントされる時3x3の原点
      ll ox = xi + dx[j];
      ll oy = yi + dy[j];
      if (0ll <= ox && ox < W-2 && 0ll <= oy && oy < H-2) {
        bool flag = true;
        rep(k, 0, 9) { // その位置がカウントされていない黒い点かどうか
          ll r = k / 3ll;
          ll c = k % 3ll;
          ll x = ox + c;
          ll y = oy + r;
          if (Find(mp, make_pair(y, x))) { // 黒い点である
            if (counted[mp[make_pair(y, x)]][k]) { // その位置としてカウントされた黒い点である
              flag = false;
              break;
            }
          }
        }
        if (flag) {
          int tmp = 0;
            rep(k, 0, 9) {
            ll r = k / 3ll;
            ll c = k % 3ll;
            ll x = ox + c;
            ll y = oy + r;
            if (Find(mp, make_pair(y, x))) { // 黒い点である
              counted[mp[make_pair(y, x)]][k] = true;
              tmp++;
            }
          }
          ans[tmp]++;
        }
      }
    }
  }

  ans[0] = (h-2ll) * (w-2ll);
  rep(i, 1, 10) {
    ans[0] -= ans[i];
  }

  rep(i, 0, 10) {
    cout << ans[i] << endl;
  }

  return 0;
};

