#include <bits/stdc++.h>

#define ll  long long

#define AREA_W  3
#define AREA_H  3

void solve(const ll H, const ll W, const std::vector<std::pair<ll, ll>>& P)
{
    if (!P.size())
    {
        std::cout << ((H - (AREA_H - 1)) * (W - (AREA_W - 1))) << std::endl;
        for (int i = 0; i < 9; i++)
        {
            std::cout << 0 << std::endl;
        }
        return;
    }

    std::vector<ll> p(10, 0);
    std::vector<std::string> m;
    for (int ow = 0; ow < AREA_W; ow++)
    {
        for (int oh = 0; oh < AREA_H; oh++)
        {
            for (auto p1 = P.begin(); p1 != P.end(); ++p1)
            {
                std::string s = std::to_string(p1->second - ow) + "," + std::to_string(p1->first - oh);
                if (m.end() != std::find(m.begin(), m.end(), s))
                {
                    continue;
                }
                else
                {
                    m.push_back(s);
                }
                if ((1 <= p1->second - ow && p1->second - ow <= W - (AREA_W - 1)) && (1 <= p1->first - oh && p1->first - oh <= H - (AREA_H - 1)))
                {
                    int b = 0;
                    for (ll h = p1->first - oh; h < p1->first - oh + AREA_H; h++)
                    {
                        for (ll w = p1->second - ow; w < p1->second - ow + AREA_W; w++)
                        {
                            for (auto p2 = P.begin(); p2 != P.end(); ++p2)
                            {
                                if (w == p2->second && h == p2->first)
                                {
                                    b++;
                                }
                            }
                        }
                    }
                    p[b]++;
                }
            }
        }
    }
    p[0] = (H - (AREA_H - 1)) * (W - (AREA_W - 1)) - std::accumulate(p.begin(), p.end(), 0LL);

    for (auto itr = p.begin(); itr != p.end(); ++itr)
    {
        std::cout << *itr << std::endl;
    }
}

int main(void)
{
    int H, W, N;
    std::cin >> H >> W >> N;

    std::vector<std::pair<ll, ll>> P(N);
    for (ll i = 0; i < N; i++)
    {
        std::cin >> P[i].first >> P[i].second;
    }
    solve(H, W, P);

    return 0;
}

