ll ans[9];

ll search_neighbor(ll x, ll y){
    ll cnt = 0;
    For(ix, -1, 2){
        ll x_target = x + ix;
        if (x_target > w || x_target <= 0) return -1;
        For(iy, -1, 2){
            ll y_target = y + iy;
            if (y_target > h || y_target <= 0) return -1;
            if (plane[mp(x_target, y_target)]) cnt++;
        }
    }
    return cnt;
}

void judge(ll x, ll y){
    For(ix, -1, 2){
        ll x_target = x + ix;
        if (x_target > w || x_target <= 0) continue;
        For(iy, -1, 2){
            ll y_target = y + iy;
            if (y_target > h || y_target <= 0) continue;
            if (visited[mp(x_target, y_target)]) continue;
            visited[mp(x_target, y_target)] = true;
            ll val = search_neighbor(x_target, y_target);
            if (val != -1) prl3(x_target, y_target, val);
            if (val != -1) ans[val - 1]++;
        }
    }
}

