int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  ll h, w, n;
  cin >> h >> w >> n;
  vector<ll> a(n), b(n);
  for (int i = 0; i < n; i++) {
    cin >> a[i] >> b[i];
  }
  set<pair<int, int>> board;
  for (int i = 0; i < n; i++) {
    board.insert(make_pair(a[i], b[i]));
  }
  set<pair<int, int>> already;
  vector<ll> answers(10, 0);
  answers[0] = (h - 2) * (w - 2);
  for (auto p: board) {
    int y = p.first, x = p.second;
    for (int i = -1; i <= 1; i++) {
      for (int j = -1; j <= 1; j++) {
        int dy = y + i, dx = x + j;
        if (dy <= 1 || dy >= h || dx <= 1 || dx >= w) {
          continue;
        }
        if (already.count(make_pair(dy, dx)) > 0) {
          continue;
        }
        already.insert(make_pair(dy, dx));
        int cnt = 0;
        for (int k = -1; k <= 1; k++) {
          for (int l = -1; l <= 1; l++) {
            int fy = dy + k, fx = dx + l;
            auto yx = make_pair(fy, fx);
            if (board.count(yx) > 0) {
              cnt++;
            }
          }
        }
        if (cnt > 0) {
          answers[0]--;
          answers[cnt]++;
        }
      }
    }
  }
  for (int i = 0; i < 10; i++) {
    cout << answers[i] << endl;
  }
  return 0;
}

