int count_area(map<tuple<int, int>, int> table, int a, int b){
    int count_n = 0;
    for(int j=-1; j<=1; ++j){
        for(int k=-1; k<=1; ++k){
            count_n += table[make_tuple(a+j,b+k)];
        }
    }
    return count_n;
}

int main()
{    
    int h, w, n;
    cin >> h >> w >> n;
    // h = 4, w = 5, n = 8;

    int a[n], b[n];
    for(int i=0; i<n; ++i){
        cin >> a[i] >> b[i];
    }
    // a[0] = 1, b[0] = 1;
    // a[1] = 1, b[1] = 4;
    // a[2] = 1, b[2] = 5;
    // a[3] = 2, b[3] = 3;
    // a[4] = 3, b[4] = 1;
    // a[5] = 3, b[5] = 2;
    // a[6] = 3, b[6] = 4;
    // a[7] = 4, b[7] = 4;

    // map : 2つのキーを持つ
    map<tuple<int, int>, int> table;
    map<tuple<int, int>, int> count_table;
    int ans[10];
    for(int i=0; i<10; ++i) ans[i] = 0;
    // mapに0, 1を塗る
    for(int i=0; i<n; ++i){
        for(int j=-2; j<=2; ++j){
            for(int k=-2; k<=2; ++k){
                table[make_tuple(a[i]+j, b[i]+k)] = 0;
            }
        }
    }
    for(int i=0; i<n; ++i){
        table[make_tuple(a[i], b[i])] = 1;
    }    
    // 探索
    for(int i=0; i<n; ++i){
        for(int j=-1; j<=1; ++j){
            for(int k=-1; k<=1; ++k){
                // 端の場合処理は不要
                if (a[i]+j > 1 && a[i]+j < h && b[i]+k > 1 && b[i]+k < w){
                    // 作り直し
                    int count_n = 0;
                    for(int l=-1; l<=1; ++l){
                        for(int m=-1; m<=1; ++m){
                            count_n += table[make_tuple(a[i]+j+l,b[i]+k+m)];
                        }
                    }
                    count_table[make_tuple(a[i]+j, b[i]+k)] = count_n;
                    // count_table[make_tuple(a[i]+j, b[i]+k)] = count_area(table, a[i]+j, b[i]+k);
                }
            }
        }
    }
    // map内の全探索
    for(auto itr = count_table.begin(); itr != count_table.end(); ++itr){
        // cout << itr->first << endl; // tupleの時これが使用できない?
        ans[itr->second]++;
    }

    // 0のカウントは全パターンから引けばいい
    unsigned long long ans_0 = (h-2)*(w-2);
    for(int i=1; i<10; ++i) ans_0 -= ans[i];
    cout << ans_0 << endl;
    for(int i=1; i<10; ++i){
        cout << ans[i] << endl;        
    }

    return 0;
}

