int main(){
    ll H, W, N;
    cin >> H >> W >> N;
    vector<ll> ans(10, 0);

    multiset<pair<ll, ll>> q;
    for (int i = 0; i < N; i++) {
        ll s, t;
        cin >> s >> t;
        for (int j = -1; j <= 1; j++) {
            for (int k = -1; k <= 1; k++) {
                if (s+j >=2 && s+j <= H-1 && t+k >= 2 && t+k <= W-1) {
                    q.insert({s+j, t+k});
                }
            }
        }
    }
    auto it = q.begin();
    auto u = *it;
    ll x = u.first, y = u.second;
    it++;
    int cnt = 1;
    while (true) {
        auto sq = *it;
        if (sq.first == x && sq.second == y) cnt++;
        else {
            ans[cnt]++;
            cnt = 1;
        }
        x = sq.first;
        y = sq.second;
        it++;
        if (it == q.end()) {
            ans[cnt]++;
            break;
        }
    }

    ans[0] = (H-2) * (W-2);
    for (int i = 1; i <= 9; i++) ans[0] -= ans[i];
    for (int i = 0; i <= 9; i++) {
        cout << ans[i] << endl;
    }
}

