/* ソート済みの配列について、
   オブジェクトとその個数を得る。
*/
template<typename Itr, typename Fn>
void counting(Itr b, Itr e, Fn f) {
    if (b == e) {
        // no element;
        return;
    }
    size_t count = 0;
    auto&& itr = b;
    for (; itr + 1 != e; ++itr) {
        count++;
        if (*itr != *(itr + 1)) {
            f(*itr, count);
            count = 0;
        }
    }

    f(*itr, ++count);
}

int main()
{
    int64_t H, W, N;
    std::cin >> H >> W >> N;

    struct Pos {
        int64_t x;
        int64_t y;

        bool operator<(const Pos& rhs) const
        {
            return x == rhs.x ? y < rhs.y : x < rhs.x;
        }

        bool operator!=(const Pos& rhs) const
        {
            return x != rhs.x ||  y != rhs.y;
        }
    };

    std::vector<Pos> V;

    for (decltype(N) i = 0; i < N; ++i) {
        Pos p;
        std::cin >> p.y >> p.x;
        p.y --;
        p.x --;
        for (int64_t y = -1; y <= 1; ++y) {
            for (int64_t x = -1; x <= 1; ++x) {
                auto xx = p.x + x;
                auto yy = p.y + y;
                if (1 <= xx && xx < W-1&& 1 <= yy && yy < H-1) {
                    V.push_back(Pos{xx, yy});
                }
            }
        }
    }

    std::sort(std::begin(V), std::end(V));

    std::vector<int64_t> ret;
    ret.resize(10);
    ret[0] = (H-2)*(W-2);

    counting(V.begin(), V.end(), [&ret](const auto& elem, size_t count) {
            ret[count] ++;
            ret[0] --;
        });

    for (size_t i = 0; i <= 9; ++i) {
        std::cout << ret[i] << std::endl;
    }

    return 0;
}

