#include <bits/stdc++.h>
using namespace std;

#define fir first
#define sec second

struct node {
  int fir;
  int sec;

  node(int fir=0, int sec=0):
    fir(fir), sec(sec) {}

  node(pair<int,int> p):
    fir(p.first), sec(p.second) {}

    bool operator==(const node& a) const {
      return fir==a.fir && sec==a.sec;
    }
};

struct MyHash {
  size_t operator()(const node& a) const {
        return 1LL*a.fir*100005+a.sec;
    }
};

typedef long long LL;
typedef node pii;
pii g[3][3];
pii dir[9][9];
int ID[3][3];
int h, w, n;

inline bool judge(int x, int y) {
  return x<=0 || x>h || y<=0 || y>w;
}

inline bool judge(const pii& p) {
  return p.fir<=0 || p.fir>h || p.sec<=0 || p.sec>w;
}

void init() {
  int c = 0;

  for (int i=0; i<3; ++i) {
    for (int j=0; j<3; ++j) {
      g[i][j].fir = i;
      g[i][j].sec = j;
      ID[i][j] = c++;
    }
  }

  for (int id=0; id<9; ++id) {
    int x = id / 3;
    int y = id % 3;
    int z = 0;
    for (int i=0; i<3; ++i) {
      for (int j=0; j<3; ++j) {
        dir[id][z] = make_pair(g[i][j].fir-x, g[i][j].sec-y);
        ++z;
      }
    }
  }
}

int main() {
  LL c[10];
  pii p;
  init();

  scanf("%d %d %d", &h, &w, &n);
  unordered_set<pii, MyHash> st;
  LL tot = 1LL * (h - 2) * (w - 2);
  for (int i=0; i<n; ++i) {
    scanf("%d %d", &p.fir, &p.sec);
    st.insert(p);
  }
  memset(c, 0, sizeof(c));

  int x, y, xx, yy, cnt;
  bool flag;

  for (auto iter=st.begin(); iter!=st.end(); ++iter) {
    x = iter->fir;
    y = iter->sec;
    for (int id=0; id<9; ++id) {
      flag = true;
      cnt = 0;
      for (int k=0; k<9; ++k) {
        p.fir = x + dir[id][k].fir;
        p.sec = y + dir[id][k].sec;
        if (judge(p)) {
          flag = false;
          break;
        }
        cnt += st.count(p)>0;
      }
      if (flag)
        c[cnt]++;
    }
  }

  c[0] = tot;
  for (int i=1; i<=9; ++i) {
    c[i] /= i;
    c[0] -= c[i];
  }

  for (int i=0; i<10; ++i) {
    cout << c[i] << endl;
  }

  return 0;
}

