#include <bits/stdc++.h>

int main(void)
{
  using number = long long;
  number height, width, n;
  std::cin >> height >> width >> n;
  auto counts = std::vector<std::pair<number, number>>{};
  for (number i = 0; i < n; i++) {
    number a, b;
    std::cin >> a >> b;
    a--;
    b--;
    for (number i = std::max(0ll, a - 2); i < std::min(height - 2, a + 1); i++) {
      for (number j = std::max(0ll, b - 2); j < std::min(width - 2, b + 1); j++) {
        counts.push_back({i, j});
      }
    }
  }
  sort(counts.begin(), counts.end());
  auto results = std::vector<number>(10, 0);
  number i = -1;
  auto prev = std::pair<number, number>{};
  for (auto &&current : counts) {
    if (i != -1 && prev != current) {
      results[i] = i;
      i = 0;
      prev = current;
    }
    i = i + (i == -1 ? 2 : 1);
  }
  results[0] = (width - 2) * (height - 2);
  std::for_each(results.begin() + 1, results.end(), [&](int i) { results[0] -= i; });
  for (auto &&result : results) {
    std::cout << result << std::endl;
  }
}

