unordered_map<ll, bool> M;
bool l[5][5];
ll s[10];
int h, w, n;

inline bool getv(ll x, ll y)
{
    ll v = (x << 32) | y;
    return M.find(v) != M.end();
}

inline void setv(ll x, ll y)
{
    ll v = ((ll)x << 32) | y;
    M[v] = true;
}

inline bool good(int x, int y)
{
    return x >= 0 && y >= 0 && x < h && y < w;
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> h >> w >> n;
    s[0] = (ll) (h - 2) * (w - 2);
    for (int k = 0; k < n; ++k)
    {
        int a, b;
        cin >> a >> b;
        a--; b--;
        setv(a, b);
        memset(l, 0, sizeof l);
        for (int i = a - 2; i <= a + 2; ++i)
            for (int j = b - 2; j <= b + 2; ++j)
                if (good(i, j))
                    l[i - (a - 2)][j - (b - 2)] = getv(i, j);

        for (int i = 0; i < 3; ++i)
        {
            for (int j = 0; j < 3; ++j)
            {
                if (!good(a - 2 + i, b - 2 + j) ||
                    !good(a + i, b + j))
                    continue;

                int cnt = 0;
                for (int p = i; p < i + 3; ++p)
                    for (int q = j; q < j + 3; ++q)
                        cnt += (bool)l[p][q];

                s[cnt - 1]--;
                s[cnt]++;
            }
        }
    }
    for (int k = 0; k < 10; ++k)
        cout << s[k] << '\n';
}

