    {
        for (size_t j = 0; j < 3; j++)
        {
            pair<int,int> a =make_pair (row-1+i,col-1+j) ;
            num += binary_search(panel.begin(),panel.end(),a) ;            
        }

    }
    return num ;
}

int main(){
