void solve(long long H, long long W, long long N, vector<long long> a, vector<long long> b){
	ll ans[10] = {};
	vector<ll> list[H];

	REP(i,N)
		list[a[i]].push_back(b[i]);

	REP(i,N)
		sort(ALL(list[i]));

	REP(y,H){
		int ny = y+2;
		if(ny >= H)continue;

		REP(x,W){
				int nx = x+2;
				if(nx >= x)continue;

				int count = 0;
				FOR(nny,y,ny+1){
					for(const ll& nnx:list[y]){
						if(nnx < x)continue;
						if(nnx > nx)break;
						count++;
					}
				}

				assert(count < 10);

				ans[count]+= count;
		}
	}

	REP(i,10)
		cout << ans[i] << endl;

	// REP(i,10)
