inline int get_num(){
	int num=0;ch=getchar();
	while(ch>'9'||ch<'0'){ch=getchar();	}
	while(ch<='9'&&ch>='0'){num=(num<<3)+(num<<1)+ch-'0';ch=getchar();	}
	return num;
}
int hash(int a,int b){
	long long ans=((a*p1)%maxn+(b*p2)%maxn)%maxn;
	return ans;
}
