pair<int,int> pa[9] = {{0,0},{0,1},{0,2},{1,0},{1,1},{1,2},{2,0},{2,1},{2,2}};
unsigned long long int ans[10] = {0};

map<pair<int,int>,bool> map_,tmp,black;

bool test_(int x, int y){
     if(x <= 0 || y <= 0 || x > W-2 || y > H-2){ 
         return false;
     }return true;
}

int check(int x,int y){
    int count = 0;
    if(x <= 0 || y <= 0 || x > W -2|| y > H -2) return 0;
    for(auto p : pa){
            if(black[ make_pair(x+p.first,y+p.second) ] == true){
                count++;
            }
    }
    return count;
}

int main(){
    cin >> H >> W >> N;
