    for(int n = 0; n < N; n++){
        cin >> Y[n] >> X[n];
        black[ make_pair(X[n],Y[n]) ] = true;
        for(auto p : pa){
            if(test_(X[n]-p.first,Y[n]-p.second)){
                map_[ make_pair(X[n]-p.first, Y[n]-p.second)] = true;//候補の座標を格納
            }
        }
    }

    tmp = map_;

    for(auto p : map_){
         //各々黒マスについて調べる
