using namespace std;

using i64=long long;
using vx=vector<i64>;
using pii=pair<int, int>;
using sp=set<pii>;

static const int dI[]={-1, -1, -1, 0, 0, 0, 1, 1, 1};
static const int dJ[]={-1, 0, 1, -1, 0, 1, -1, 0, 1};

void count_black(
    const pii &coord, sp &blacked, vx &num_black, sp &visited, int H, int W
) {
    for (int k=0; k<9; ++k) {
        int I=coord.first+dI[k], J=coord.second+dJ[k];

        if (!(1<=I && I<H-1 && 1<=J && J<W-1)) continue;
        if (visited.count(pii(I, J))) continue;

        int cur=0;
        for (int m=0; m<9; ++m)
            if (blacked.count(pii(I+dI[m], J+dJ[m])))
                ++cur;

        ++num_black[cur];
        visited.insert(pii(I, J));
    }
}

int main() {
    int H, W, N;
    scanf("%d %d %d", &H, &W, &N);

    sp blacked;
    for (int i=0; i<N; ++i) {
        int a, b;
        scanf("%d %d", &a, &b);
        blacked.insert(pii(--a, --b));
    }

    sp visited;
    vx num_black(11);

    for (pii coord: blacked)
        count_black(coord, blacked, num_black, visited, H, W);

    num_black[0] = (H-2LL)*(W-2LL);
    for (int i=1; i<=9; ++i)
        num_black[0] -= num_black[i];

    for (int i=0; i<=9; ++i)
        printf("%lld\n", num_black[i]);

    return 0;
}

