int DX[9] = {0, 1, 2, 0, 1, 2, 0, 1, 2}; 
int DY[9] = {0, 0, 0, 1, 1, 1, 2, 2, 2}; 

map<tuple<int, int>, bool> grid;

ull h, w, n;

bool invalid(int x, int y) {
  if (x < 0 || x >= w || y < 0 || y >= h) return true;
  return false;
}

int num_black(int x, int y) {
  int ret = 0;
  for (int i = 0; i < 9; ++i) { 
    int nx = x+DX[i];
    int ny = y+DY[i];
    if (invalid(nx, ny)) {
      return -2;
    }
    tuple<int, int> np = make_tuple(nx, ny);
    if (grid.find(np) == grid.end()) continue;
    bool used = grid[np];
    if (used) return -1;
    ++ret;
  }
  return ret;
}

int main() {
  cin >> h >> w >> n;
  for (int i = 0; i < n; ++i) {
    int a, b;
    cin >> a >> b;
    --a; --b;
    tuple<int, int> pos = make_tuple(b, a);
    grid[pos] = false;
  }
  vector<ull> ans(10);
  for (auto it : grid) {
    int x, y;
    tie(x, y) = it.first;
    int id = it.second;
    for (int dx = -2; dx <= 0; ++dx) { 
      for (int dy = -2; dy <= 0; ++dy) { 
        int nx = x+dx;
        int ny = y+dy;
        if (invalid(nx, ny)) continue;
        int nb = num_black(nx,ny);
        // cout << "(" << x << " " << y << ")(" << nx << " " << ny << ")" << nb << endl;
        if (nb < 0) continue;
        ++ans[nb];
      }
    }
    grid[make_tuple(x, y)] = true;
  }
  ull block = 0;
  for (int i = 1; i <= 9; ++i) {
    block += ans[i];
  }
  ans[0] = (h-2)*(w-2) - block;
  cout << ans << endl;
}

