#define LL long long
LL H,W,N;
LL ans[10];
LL dx[]={-2,-2,-2,-1,-1,-1,0,0,0};
LL dy[]={-2,-1,0,-2,-1,0,-2,-1,0};
map<LL,LL> m;
void slove(LL x,LL y)
{
    LL a,b;
    LL id;
    for(int i=0;i<9;i++){
        a=x+dx[i];
        b=y+dy[i];
        if(a<1 || b<1 || a>H-2 || b>W-2)   continue;
        id=(H-2)*(b-1)+a;//对每个小矩形进行编号
		//左上角的位置就只能在(h-2)*(w-2)的矩形区域内
		//每一行有w-2个元素 a-1
        m[id]++;
    }
}
int main(){
    LL x,y;
    scanf("%lld %lld %lld",&H,&W,&N);
    for(int i=1;i<=N;i++)
	{
        scanf("%lld %lld",&x,&y);
        slove(x,y);
    }
    ans[0]=(H-2)*(W-2);//总数
    LL temp;
	map<LL,LL>::iterator it=m.begin();
    for(it=m.begin();it!=m.end();it++){
        temp=it->second;
        ans[temp]++;
        ans[0]--;
    }
    for(int i=0;i<=9;i++)
        cout<<ans[i]<<endl;
    return 0;
}

