#include <bits/stdc++.h>

#define ll  long long

#define AREA_W  3
#define AREA_H  3

#define X   0
#define Y   1

int dir[9][2] = {
    {0, 0}, {1, 0}, {2, 0},
    {0, 1}, {1, 1}, {2, 1},
    {0, 2}, {1, 2}, {2, 2},
};

void solve(const ll H, const ll W, const std::vector<std::pair<ll, ll>>& P)
{
    if (!P.size())
    {
        std::cout << ((H - (AREA_H - 1)) * (W - (AREA_W - 1))) << std::endl;
        for (int i = 0; i < 9; i++)
        {
            std::cout << 0 << std::endl;
        }
        return;
    }

    std::vector<ll> p(10, 0);
    std::vector<std::string> m;
    for (int I = 0; I < 9; I++)
    {
        for (auto p1 = P.begin(); p1 != P.end(); ++p1)
        {
            std::string s = std::to_string(p1->second - dir[I][X]) + "," + std::to_string(p1->first - dir[I][Y]);
            if (m.end() != std::find(m.begin(), m.end(), s))
            {
                continue;
            }
            else
            {
                m.push_back(s);
            }
            if ((1 <= p1->second - dir[I][X] && p1->second - dir[I][X] <= W - (AREA_W - 1)) && (1 <= p1->first - dir[I][Y] && p1->first - dir[I][Y] <= H - (AREA_H - 1)))
            {
                int b = 0;
                for (ll h = p1->first - dir[I][Y]; h < p1->first - dir[I][Y] + AREA_H; h++)
                {
                    for (ll w = p1->second - dir[I][X]; w < p1->second - dir[I][X] + AREA_W; w++)
                    {
                        for (auto p2 = P.begin(); p2 != P.end(); ++p2)
                        {
                            if (w == p2->second && h == p2->first)
                            {
                                b++;
                            }
                        }
                    }
                }
                p[b]++;
            }
        }
    }
    p[0] = (H - (AREA_H - 1)) * (W - (AREA_W - 1)) - std::accumulate(p.begin(), p.end(), 0LL);

    for (auto itr = p.begin(); itr != p.end(); ++itr)
    {
        std::cout << *itr << std::endl;
    }
}

int main(void)
{
    int H, W, N;
    std::cin >> H >> W >> N;

    std::vector<std::pair<ll, ll>> P(N);
    for (ll i = 0; i < N; i++)
    {
        std::cin >> P[i].first >> P[i].second;
    }
    solve(H, W, P);

    return 0;
}

