ll H, W;
V ans(10, 0);
set<P> ab;
set<P> visited;

void bfs(P now) {
	P next, target;
	ll h, w;
	ll num;

	if (visited.find(now) != visited.end()) return;

	visited.insert(now);
	h = now.first;
	w = now.second;

	if (h > 1) {
		next = make_pair(now.first - 1, now.second);
		bfs(next);
		if (w > 1) {
			next = make_pair(now.first - 1, now.second - 1);
			bfs(next);
		}
		if (w < W) {
			next = make_pair(now.first - 1, now.second + 1);
			bfs(next);
		}
	}
	if (h < H) {
		next = make_pair(now.first + 1, now.second);
		bfs(next);
		if (w > 1) {
			next = make_pair(now.first + 1, now.second - 1);
			bfs(next);
		}
		if (w < W) {
			next = make_pair(now.first + 1, now.second + 1);
			bfs(next);
		}
	}
	if (w > 1) {
		next = make_pair(now.first, now.second - 1);
		bfs(next);
	}
	if (w < W) {
		next = make_pair(now.first, now.second + 1);
		bfs(next);
	}

	if (h > 1 && h < H && w > 1 && w < W) {
		num = 0;
		rep(i, 3) {
			rep(j, 3) {
				target = make_pair(h - 1 + i, w - 1 + j);
				if (ab.find(target) != ab.end()) {
					num++;
				}
			}
		}
		ans[num]++;
	}
}

void solve_abc_d() {
	ll n, m;
	ll a, b;
	//ll x, y;
	ll k;
	ll l_ans = 0;

	cin >> H >> W >> n;

	rep(i, n) {
		cin >> a >> b;
		ab.insert(make_pair(a, b));
	}

	P now;
	for (auto itr = ab.begin(); itr != ab.end(); itr++) {
		now = make_pair(itr->first, itr->second);
		bfs(now);
	}

	ll sum = 0;
	rep1(i, 9) {
		sum += ans[i];
	}
	ans[0] = (H - 2) * (W - 2) - sum;

	rep(i, 10) {
		cout << ans[i] << "\n";
	}

	return;
}

