using namespace std;


class Solution{

private:
    int H, W;

public:
    vector<long long> freq(int H, int W, const unordered_set<long long>& set){

        this->H = H, this->W = W;

        vector<unordered_set<long long>> res(10);
        for(long long black: set){
            long long x = black / W, y = black % W;
            for(int d1 = 0; d1 <= 2; d1 ++)
                for(int d2 = 0; d2 <= 2; d2 ++)
                    if(in_area(x + d1 - 2, y + d2 - 2) && in_area(x + d1, y + d2)){

                        int cnt = 0;
                        for(int i = x + d1 - 2; i <= x + d1; i ++)
                            for(int j = y + d2 - 2; j <= y + d2; j ++)
                                cnt += set.count((long long)i * W + j);
                        res[cnt].insert((long long)(x + d1 - 2) * W +(y + d2 - 2));
                    }
        }

        vector<long long> ret(10, 0ll);
        for(int i = 1; i < 10; i ++) ret[i] = res[i].size();
        ret[0] = (long long)(H - 2) * (W - 2) - accumulate(ret.begin() + 1, ret.end(), 0ll);
        return ret;
    }

private:
    bool in_area(int x, int y){
        return x >= 0 && x < H && y >= 0 && y < W;
    }
};

int main() {

    int H, W, N;
    scanf("%d%d%d", &H, &W, &N);

    unordered_set<long long> set;
    long long a, b;
    while(N --){
        scanf("%lld%lld", &a, &b);
        a --, b --;
        set.insert(a * W + b);
    }

    vector<long long> res = Solution().freq(H, W, set);
    for(long long e: res) printf("%lld\n", e);

    return 0;
}

