    if(is_valid({ij.first - 2, ij.second}) && is_valid({ij.first, ij.second + 2}))
    {
     result.push_back({{ij.first - 2, ij.second}, {ij.first, ij.second + 2}});
    }
    if(is_valid({ij.first - 2, ij.second - 1}) && is_valid({ij.first, ij.second + 1}))
    {
     result.push_back({{ij.first - 2, ij.second - 1}, {ij.first, ij.second + 1}});
    }
    if(is_valid({ij.first - 2, ij.second - 2}))
    {
     result.push_back({{ij.first - 2, ij.second - 2}, {ij.first, ij.second}});
    }
    return result;
  };

  ///塗られる区画
  vector<pair<pr, pr>> as;
  for (int i = 0; i < n; ++i) {
