int H,W,N;
int vm[] = {-1,-1,-1,0,0,0,1,1,1};//from top  to bottom
int vn[] = {-1,0,1,-1,0,1,-1,0,1};//from left to right
bool valid(point p){
  return (p.m>=2)&&(p.n>=2)&&(p.m<=H-1)&&(p.n<=W-1);
}

int main() {
  scanf("%d %d %d",&H,&W,&N);
  vector<point> black(N);
  vector<point> white;
  vector<int> score(10);
  point p;
  int a,b;
  std::fill(score.begin(), score.end(), 0);
  score[0] = (long)(H-2)*(W-2);
  for(int i=0; i<N; ++i){
    scanf("%d %d", &a, &b);
    p.m = a; p.n = b;
    black[i] = p;
  }
  debug(black);
  if(N==0){
    for(auto itr = score.begin(); itr!=score.end(); ++itr){
      cout << *itr << endl;
    }
    return 0;
  }
  point center, rectcent, adj;
  for(auto itr=black.begin(); itr!=black.end(); ++itr){
    center = *itr;
    if(!valid(center)) continue;
    for(int i=0; i<9; ++i){
      rectcent.m = center.m + vm[i];
      rectcent.n = center.n + vn[i];
      if(!valid(rectcent)) continue;
      int count = 0;
      for(int j=0; j<9; ++j){
        adj.m = rectcent.m + vm[j];
        adj.n = rectcent.n + vn[j];
        for(auto w = white.begin(); w!=white.end(); ++w){
          point used = *w;
          if(adj.m==used.m&&adj.n==used.n) continue;
        }
        white.push_back(adj);
        for(auto itr2=black.begin(); itr2!=black.end(); ++itr2){
          point p2 = *itr2;
          if(adj.m==p2.m&&adj.n==p2.n){
            count++;
          }
        }
      }
      if(count!=0){
        score[count]+=1;
        score[0]-=1;
      }
    }
    for(auto ans = score.begin(); ans!=score.end(); ++ans){
      cout << *ans << endl;
    }
  }
}

