struct SubRect {
    int x, y;
    int count;
    SubRect(int _x, int _y) {
        x = _x;
        y = _y;
        count = 1;
    }
    bool operator<(const SubRect& other) const {
        return x == other.x ? y < other.y : x < other.x;
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);
