    for (int i = 0; i < n; ++i) {
        int a, b;
        std::cin >> a >> b;
        for (int x = a - 2; x <= a; ++x) {
            for (int y = b - 2; y <= b; ++y) {
                if (x > 0 && y > 0 && x < h - 1 && y < w - 1) {
                    SubRect cur(x, y);
                    auto itr = set.find(cur);
                    if (itr != set.end()) {
                        cur.count += itr->count;
                        set.erase(*itr);
                    }
                    set.emplace(cur);
                }
            }
        }
