#include<bits/stdc++.h>
using namespace std;

typedef pair<long, long> P;

int binary_search(vector<P> &tmp, long long x, long long y_up, long long y_down){
    int ok = (int)tmp.size();
    int ng = -1;
    while (abs(ok - ng) > 1){
        int mid = (ok + ng) / 2;
        if (tmp[mid].first >= x) ok = mid;
        else ng = mid;
    }
    int res = 0;
    while (tmp[ok].first == x && ok != (int)tmp.size()){
        if (y_up <= tmp[ok].second && tmp[ok].second <= y_down) res++;
        ok++;
    }
    return res;
}

int main(){
    long long h, w, n;
    cin >> h >> w >> n;
    vector<P> tmp(n);
    for (int i = 0; i < n; i++) cin >> tmp[i].first >> tmp[i].second;
    sort(tmp.begin(), tmp.end());
    vector<long long> ans(10, 0);
    for (int elm = 0; elm < n; elm++){
        for (int i = - 2; i < 1; i++){
            for (int j = -2; j < 1; j++){
                if (tmp[elm].first + i <= 0 || h < tmp[elm].first + i || tmp[elm].second + j <= 0 || w < tmp[elm].second + j) continue;
                if (tmp[elm].first + i + 2 <= 0 || h < tmp[elm].first + i + 2 || tmp[elm].second + j + 2 <= 0 || w < tmp[elm].second + j + 2) continue;
                int ss = 0;
                ss += binary_search(tmp, tmp[elm].first + i, tmp[elm].second + j, tmp[elm].second + j + 2);
                ss += binary_search(tmp, tmp[elm].first + i + 1, tmp[elm].second + j, tmp[elm].second + j + 2);
                ss += binary_search(tmp, tmp[elm].first + i + 2, tmp[elm].second + j, tmp[elm].second + j + 2);
                ans[ss]++;
            }
        }
    }

    long long tt = 0;
    for (int i = 1; i < 10; i++){
        ans[i] /= i;
        tt += ans[i];
    }
    ans[0] = (h - 2) * (w - 2) - tt;
    for (int i = 0; i < 10; i++) cout << ans[i] << endl;
}

