const int N = 3e5 + 10;
int w, h, n, Ans;
struct node {
	int x, y;
	friend bool operator < (node a, node b) { return (a.x < b.x || ((a.x == b.x) && (a.y < b.y))); } 
} d[N], L[N], R[N];
struct Segment_Tree {
	int mx, tag;	
} tr[4 * N];

#define Ls (x << 1)
#define Rs (Ls | 1)
#define Md ((st + en) >> 1)
void Update(int x, int st, int en, int l, int r, int add) {
	if (l > en || r < st) return;
    if (l <= st && en <= r) {
        tr[x].tag += add, tr[x].mx += add;
        return;
    }
    if (tr[x].tag) {
    	tr[Ls].tag += tr[x].tag, tr[Ls].mx += tr[x].tag;
	    tr[Rs].tag += tr[x].tag, tr[Rs].mx += tr[x].tag;
	    tr[x].tag = 0;
	}
	Update(Ls, st, Md, l, r, add);
	Update(Rs, Md + 1, en, l, r, add);
    tr[x].mx = max(tr[Ls].mx, tr[Rs].mx);
}

void Solve() {
	mem(tr, 0), sort(d + 1, d + n + 1);
//	F(i, 1, n)
//		printf("%d %d\n", d[i].x, d[i].y);
    int l = 0, r = 0;
    F(i, 1, n - 1) {
        int tmp = i - 1;
        if (d[i].y <= h / 2) {
            while (l && d[i].y > L[l].y) {
                Update(1, 1, n, L[l].x, tmp, L[l].y - d[i].y);
                tmp = L[l].x - 1;
                -- l;
            }
			L[++ l] = {tmp + 1, d[i].y};
        }
		else {
            while (r && d[i].y < R[r].y) {
                Update(1, 1, n, R[r].x, tmp, d[i].y - R[r].y);
                tmp = R[r].x - 1;
                -- r;
            }
			R[++ r] = {tmp + 1, d[i].y};
        }
        L[++ l] = {i, 0}, R[++ r] = {i, h};
        Update(1, 1, n, i, i, h - d[i].x);
        mx(Ans, 2 * (d[i + 1].x + tr[1].mx));
    }
}

int main() {
	Re(w), Re(h), Re(n);
	F(i, 1, n) Re(d[i].x), Re(d[i].y);

	d[++ n] = {0, 0};
	d[++ n] = {w, h};

	Solve();

	swap(w, h);
	F(i, 1, n) swap(d[i].x, d[i].y);

	Solve();

	Wr(Ans);
}

