        ms[p]++;
      }
    }
  }

  ll z = (w - 2) * (h - 2);
  counter[0] = z - accumulate(begin(counter) + 1, end(counter), 0);
  for (const auto &val : counter) {
    cout << val << "\n";
  }
  return 0;
}

