void answer() {
  ll h, w, n;
  cin >> h >> w >> n;
  vector<ll> topleft;
  rep(i, n) {
    ll a, b;
    cin >> a >> b;
    a--; b--;
    rep(i, 3) {
      ll na = a - i;
      if(0 <= na && na + 2 < h) {
        rep(j, 3) {
          ll nb = b - j;
          if(0 <= nb && nb + 2 < w) {
            topleft.push_back(na * w + nb);
          }
        }
      }
    }
  }
  sort(ALL(topleft));
  ll past = -1, cnt = 0;
  vector<ll> ans(10, 0);
  for(const auto c : topleft) {
    if(past < c) {
      if(cnt) ans[cnt]++;
      past = c;
      cnt = 1;
    } else {
      cnt++;
    }
  }
  ans[cnt]++;
  ans[0] = (h-2)*(w-2);
  REPC(i, 1, 9) ans[0] -= ans[i];
  rep(i, 10) cout << ans[i] << '\n';
}
