int main()
{
  int H, W, N; scanf("%d %d %d", &H, &W, &N);
  int r, c;
  vector<pair<int, int> > v;
  for (int i = 0; i < N; ++i) {
    scanf("%d %d", &r, &c);
    for (int dr = 0; dr < 3; ++dr) {
      for (int dc = 0; dc < 3; ++dc) {
        int nr = r - dr, nc = c - dc;
        if (1 <= nr and nr + 2 <= H and 1 <= nc and nc + 2 <= W) {
          v.push_back(make_pair(nr, nc));
        }
      }
    }
  }

  sort(v.begin(), v.end());
  int m = v.size();
  vector<ll> ans(10, 0);
  ll total = 1LL * (H - 2) * (W - 2);
  ll sum = 0;
  for (int i = 0; i < m; ) {
    int j = i;
    while (j < m and v[j] == v[i]) { ++j; }
    int cnt = j - i;
    ++ans[cnt];
    ++sum;
    i = j;
  }
  ans[0] = total - sum;
  for (int i = 0; i < 10; ++i) {
    printf("%lld\n", ans[i]);
  }
  return 0;
}

