int dirw[9] = {-1, 0, 1, -1, 0, 1, -1, 0, 1};

vector<i_i> ab;

bool mycom(i_i qwe, i_i rty){
  if(qwe.X != rty.X)return qwe.X < rty.X;
  return qwe.Y < rty.Y;
}

void solve(void){
  int i, j;
  ab.resize(n);
  rep(i, n){
    ab[i].X = a[i] - 1;
    ab[i].Y = b[i] - 1;
  }
  sort(all(ab), mycom);

  rep(i, n){
    i_i now;
    int k;
    rep(k, 9){
      now.X = ab[i].X + dirh[k];
      now.Y = ab[i].Y + dirw[k];
      if(0 < now.X && now.X < h - 1 && 0 < now.Y && now.Y < w - 1){
        int cnt = 0;
        int x;
        rep(x, 9){
          //pri3(i, k, x);
          i_i see;
          see.X = now.X + dirh[x];
          see.Y = now.Y + dirw[x];
          //pri2(see.X, see.Y);

          //(see.X, see.Y)があるかどうか頑張って(logぐらいで)探す
          int l = 0, m, r = n, wantl, wantr;
          if(ab[0].X == see.X){
            wantl = 0;
          }else{
            for(;l + 1 < r;){
              m = (l + r) / 2;
              if(ab[m].X < see.X)l = m;
              else r = m;
            }
            if(ab[r].X != see.X)break;
            wantl = r;
          }
          l = 0; r = n;
          if(ab[n - 1].X == see.X){
            wantr = n;
          }else{
            for(;l + 1 < r;){
              m = (l + r) / 2;
              if(ab[m].X < see.X + 1)l = m;
              else r = m;
            }
            wantr = r;
          }
          //pri2(wantl, wantr);
          l = wantl;
          r = wantr;
          //pri2(l, r);
          for(;l + 1 < r;){
            m = (l + r) / 2;
            if(ab[m].Y <= see.Y)l = m;
            else r = m;
          }
          //pri3(see.X, see.Y, ab[l].Y == see.Y);
          if(ab[l].Y == see.Y)++cnt;
        }//9箇所探した
        //pri3(now.X, now.Y, cnt);
        //kabe;
        ++res[cnt];
      }
    }
  }

  return;
}

signed main(void){
  int i, j;
  for(int testcase = 0;testcase >= 0;testcase++){
    cin >> h >> w >> n;
    sc2n(n, a, b);
    res[0] = (ll)(h - 2) * (ll)(w - 2);
    solve();
    rep1(i, 10){
      res[i] /= i;
      res[0] -= res[i];
    }
    rep(i, 10)pri(res[i]);



/*/

