int dx9[9]={0,0,0,1,1,1,-1,-1,-1};
int dy9[9]={1,0,-1,1,0,-1,1,0,-1};
ll ans[10];

void solve(void){
    ll h, w, n;
    scanf("%lld%lld%lld\n", &h, &w, &n);
