long long gridToKey(int a, int b)
{
    return static_cast<long long>(W - 1) * a + b;
}

int check9grids(int a, int b)
{
    int res = 0;
    for (int i = a - 1; i <= a + 1; i++) {
        for (int j = b - 1; b <= b + 1; j++) {
            auto ite = bls.find(gridToKey(i, j));
            if (ite != bls.end()) {
                res++;
            }
        }
    }
    return res;
}

void check25grids(int a, int b)
{
    for (int i = max(a - 1, 1); i <= min(a + 1, H - 2); i++) {
        for (int j = max(b - 1, 1); b <= min(b + 1, W - 2); j++) {
            auto ite = chks.find(gridToKey(i, j));
            if (ite == chks.end()) {
                ans[check9grids(i, j)]++;
                chks.insert(gridToKey(i, j));
            }
        }
    }
}

