vector<pair<ll, ll>> get_surround(ll x, ll y, ll H, ll W){
    vector<pair<ll, ll>> res;
    res.emplace_back(x,y);

    if(x-1 >= 0){
        res.emplace_back(x-1,y);
        if(y-1 >= 0) res.emplace_back(x-1,y-1);
        if(y+1 < W) res.emplace_back(x-1,y+1);
    }

    if(y-1 >= 0) res.emplace_back(x,y-1);
    if(y+1 < W) res.emplace_back(x,y+1);

    if(x+1 < H){
        res.emplace_back(x+1,y);
        if(y-1 >= 0) res.emplace_back(x+1,y-1);
        if(y+1 < W) res.emplace_back(x+1,y+1);
    }

    return res;
}

