struct Accum2D{
  map<ll, ll> x, y;
  ll mode = 1;
  vvl dat;
  vvl v;
  Accum2D(vvl point, ll h=0, ll w=0){
    if(point.size()==0) mode=0;
    for(int i=0;i<point.size();i++){
      if(x.find(point[i][0])==x.end()) x.emplace(point[i][0], 0);
      if(y.find(point[i][1])==y.end()) y.emplace(point[i][1], 0);
    }
    ll k = 0;
    for(auto itr = x.begin();itr!=x.end();itr++) (*itr).second = k, k++;
    k = 0;
    for(auto itr = y.begin();itr!=y.end();itr++) (*itr).second = k, k++;
    if(mode==1) {
      dat.resize(x.size(), vll(y.size(), 0));
      v.resize(x.size(), vll(y.size(), 0));
    }else {
      dat.resize(h+1, vll(w+1, 0));
      v.resize(h+1, vll(w+1, 0));
    }
  }
  void insert(vll p){
    if(mode==1) dat[x.at(p[0])][y.at(p[1])]++;
    else dat[p[0]][p[1]]++;
  }
  void calc(){
    for(int j=0;j<v[0].size();j++){
      for(int i=0;i<v.size();i++){
        v[i][j] = (i==0?0:v[i-1][j]) + dat[i][j];
      }
    }
    for(int i=0;i<v.size();i++){
      for(int j=0;j<v[0].size();j++){
        v[i][j] = v[i][j] + (j==0?0:v[i][j-1]);
      }
    }
  }
  ll get(vll a, vll b){
    if(a[0]>b[0]) swap(a[0], b[0]);
    if(a[1]>b[1]) swap(a[1], b[1]);
    if(mode==1){
      a = vll{x.at(a[0]), y.at(a[1])};
      b = vll{x.at(b[0]), y.at(b[1])};
    }
    ll r = v[b[0]][b[1]];
    ll u = (a[0]==0?0:v[a[0]-1][b[1]]);
    ll l = (a[1]==0?0:v[b[0]][a[1]-1]);
    ll o = (a[0]==0||a[1]==0?0:v[a[0]-1][a[1]-1]);
    return r - u - l + o;
  }
};
int main(int argc, char const *argv[]) {
  ll h, w, n;std::cin >> h >> w >> n;
  vvl p = vv(n, 2, 0, ll);
  vvl t = vv(0, 2, 0, ll);
  re(i, n) {
    std::cin >> p[i][0] >> p[i][1];
    for(int j=-2;j<=2;j++){
      for(int k=-2;k<=2;k++){
        t.push_back(vll{p[i][0]+j, p[i][1]+k});
      }
    }
  }
  Accum2D a(t);
  re(i, n) a.insert(p[i]);
  a.calc();
  vll ans(10, 0);
  re(i, n){
    for(int j=-2;j<=0;j++){
      for(int k=-2;k<=0;k++){
        if(p[i][0]+j<=0||p[i][1]+k<=0||p[i][0]+j+2>h||p[i][1]+k+2>w) continue;
        ll y = a.get(vll{p[i][0]+j, p[i][1]+k}, vll{p[i][0]+j+2, p[i][1]+k+2});
        ans[y]++;
      }
    }
  }
  ll tmp = 0;
  for(int i=1;i<=9;i++) tmp += ans[i]/i;
  std::cout << (h-2)*(w-2) - tmp << '\n';
  for(int i=1;i<=9;i++){
    std::cout << ans[i]/i << '\n';
  }
  return 0;
}

