int compress(vector< int > &x1, int W) {
	vector< int > xs;
	int N = x1.size();
	for (int i = 0; i < N; i++) {
		for (int d = -2; d <= 2; d++) {
			int tx1 = x1[i] + d;
			if (0 <= tx1 && tx1 < W)
				xs.push_back(tx1);
		}
	}
	sort(xs.begin(), xs.end());
