#define MAX_N 100005
using namespace std;
typedef pair<int,int> P;
int dxx[3]={-2,-1,0};
int dyy[3]={-2,-1,0};

P blacks[MAX_N];
set<P> s;

set<P> squares;

long long cnts[10];
long long h,w,n;
int x,y;
int xx,yy;
long long cnt;
bool inBound(int a,int b){
    if(a>h || a<=0 || b<=0 || b>w)return false;
    return true;
}

void solve()
{
    long long tmp = 0;
    for(int i = 0;i<n;i++){
        x = blacks[i].first;
        y = blacks[i].second;
        for(int k = 0;k<3;k++)
            for(int l = 0;l<3;l++){
                xx = x + dxx[k];
                yy = y + dyy[l];
                if(inBound(xx,yy) && inBound(xx+2,yy+2) && squares.find(P(xx,yy))==squares.end()){
                    cnt = 0;
                    for(int j = 0;j<3;j++)
                        for(int p = 0;p<3;p++)
                            if(s.find(P(xx+j,yy+p))!=s.end())
                                cnt+=1;
                    cnts[cnt] += 1;
                    squares.insert(P(xx,yy));             
                }
            }
    }
    for(int i = 0;i<10;i++)tmp+=cnts[i];

    cnts[0] = (h-2)*(w-2)-tmp;
}

int main()
{
    cin>>h>>w>>n;
    for(int i = 0;i<n;i++){
        cin>>xx>>yy;
        blacks[i] = P(xx,yy);
        s.insert(P(xx,yy));
    }
    solve();
    for(int i = 0;i<10;i++)
        cout<<cnts[i]<<endl;
    return 0;
}

