int main()
{
    int H, W, N;
    cin >> H >> W >> N;


    // 黒になった点を含む正方形 9 つをチェックして答えを更新する
    vector<long long> ans(10);
    ans[0] = (long long) (H-3+1) * (W-3+1);
    map<pair<int,int>,bool> isBlack;
    for( int n = 0; n < N; ++n ){
        int a, b;
        cin >> a >> b;
        // 9 つの正方形を順にチェックして黒に塗られているものの個数 numBlack を求め、
        // --numPaintedBlack[numBlack], ++numPaintedBlack[numBlack+1] する
        for( int i = 0; i < 3; ++i ){  // (a+i, b+j) は正方形の右下の位置に対応
            for( int j = 0; j < 3; ++j ){
                int numBlack = 0;
                if( a-2+i <= 0 or a+i > H ) continue;  // 列方向のはみ出しチェック
                if( b-2+j <= 0 or b+j > W ) continue;  // 行方向のはみ出しチェック
                for( int k = a-2+i; k <= a+i; ++k ){
                    for( int l = b-2+j; l <= b+j; ++l ){
                        if( isBlack[make_pair(k,l)] ) ++numBlack;
                    }
                }
                --ans[numBlack];
                ++ans[numBlack+1];
            }
        }
        isBlack[make_pair(a,b)] = true;
    }

    for( int i = 0; i < 10; ++ i ) cout << ans[i] << endl;


    return 0;
}

