//一つの黒く塗られたマスが影響を与える範囲は周辺にあるいくつかの3*3領域しかない
//これらの周辺の少しのマスにのみ何かの処理をするだけで計算できれば高速に答えが求められる
//(i,j)を上からi行目で左からj行目のマスを左上とする3*3の正方形を表すことにする
//例えば上からp行目で左からq行目のマスを黒く塗ると(p-k,q-l)(k=0,1,2)(l=0,1,2)に含まれる黒いマスが一つ増える
//だから入力で与えられる点に対してこれらの正方形の左上のマスを全部列挙しておき
//最大で9N個列挙される。その列挙されたものの中でそれぞれの正方形で何回出現するかがカウントできれば良い
//これはpairやmapなどで処理する
//最後に黒いマス0個の個数は全体(H-2)*(W-2)個から一回以上黒いマスが出現した3*3領域を引けば求められる

int main() {
	int H, W, N; cin >> H >> W >> N;
	vector<pii>V;
	for (int i = 0; i < N; ++i) {
		int a, b; cin >> a >> b;
		a--, b--;
		for (int j = 0; j < 3; ++j) {
			for (int k = 0; k < 3; ++k) {
				if (a - j < 0 || a -j+2 >= H || b - k < 0|| b -k+ 2 >= W) {
					continue;
				}
				V.push_back({ a - j,b - k });
			}
		}
	}
	sort(V.begin(), V.end());
	ll ans[10];
	REP(i, 10)ans[i] = 0;
	int cnt = 1;
	for (int i = 0; i < V.size()-1; ++i) {
		if (V[i].first == V[i + 1].first&&V[i].second == V[i + 1].second) {
			cnt++;
		}
		else {
			ans[cnt]++;
			cnt = 1;
		}
	}
	ans[cnt]++;
	ll sum = 0;
	for (int i = 1; i <= 9; ++i) {
		sum += ans[i];
	}
	ans[0] = (H - 2)*(W - 2) - sum;
	for (int i = 0; i <= 9; ++i) {
		cout << ans[i] << endl;
	}
	return 0;
}

