void solve() {
  REP(k, N) {
    FOR(i, -2, 0) FOR(j, -2, 0) {
      int i2 = a[k] - 1 + i;
      int j2 = b[k] - 1 + j;
      if (i2 < 0 || i2 + 2 >= H || j2 < 0 || j2 + 2 >= W) continue;
      sqs[make_pair(i2, j2)]++;
