  map<pair<int, int>, int>::iterator it;
  ITR(sqs, it) cnts[it->second]++;
  ll total = (ll) (H - 2) * (W - 2);
  FOR(k, 1, 9) total -= cnts[k];

  printf("%lld\n", total);
  FOR(k, 1, 9) printf("%d\n", cnts[k]);
}

