			D[k].first = a;
			D[k].second = b - 1;

			k++;
		}
		else n++;
		if (b + 1 < W&&a!=1&&a!=H) {
			D[k].first = a;
			D[k].second = b + 1;

			k++;
		}
		else n++;
		if (a - 1 >1 && b - 1 >1) {
			D[k].first = a - 1;
			D[k].second = b - 1;

			k++;
		}
