			D[k].first = a + 1;
			D[k].second = b - 1;

			k++;
		}
		else n++;
	}
	sort(D, D +k,greater<Edge>());


	long long int d = 0;
	for (int i = 0; i <k ; i++) {


		if (D[i].first == D[i + 1].first&&D[i].second == D[i + 1].second) {
			d++;
