bool mycom(i_i qwe, i_i rty){
  if(qwe.X != rty.X)return qwe.X < rty.X;
  return qwe.Y < rty.Y;
}

void solve(void){
  int i, j;
  ab.resize(n);
  rep(i, n){
    ab[i].X = a[i] - 1;
    ab[i].Y = b[i] - 1;
  }
  sort(all(ab), mycom);

