ll H, W, N;
set<pair<int, int>> s, q;
int dx[] = {0, 1, 1, 1, 0, -1, -1, -1, 0}, dy[] = {1, 1, 0, -1, -1, -1, 0, 1, 0};

bool inside(int y, int x) {
    return y >= 0 && y < H && x >= 0 && x < W;
}

ll ans[10];

int main() {
    COME_LET_THE_GAMES_BEGIN();
    cin >> H >> W >> N;
    rep(i, N) {
        int a, b;
        cin >> a >> b;
        a--, b--;
        s.insert(make_pair(a, b));
        rep(j, 9) {
            int y = a + dy[j], x = b + dx[j];
            if (inside(y, x)) {
                q.insert(make_pair(y, x));
            }
        }
    }
    for (auto p:q) {
        int y = p.first, x = p.second;
        int o = 0;
        bool flag = true;
        rep(i, 9) {
            int xx = x + dx[i], yy = y + dy[i];
            if (!inside(yy, xx)) {
                flag = false;
                break;
            }
            if (s.find(make_pair(yy, xx)) != s.end()) {
                o++;
            }
        }
        if (flag) {
            ans[o]++;
        }
    }
    ans[0] = (H - 2) * (W - 2);
    for (int i = 1; i <= 9; i++) {
        ans[0] -= ans[i];
    }
    for (int i = 0; i < 10; i++) {
        cout << ans[i] << endl;
    }
}

