using namespace std;

bool mySort(pair<long,long> i, pair<long,long> j){
    if (i.first == j.first) return i.second < j.second;
    else return i.first < j.first;
}

bool binarySearch(int low, int high, vector< pair<long,long> >* v, pair<long,long> i){
    int mid = (low + high)/2;
    while (high - low >= 0){
        mid = (high+low)/2;
        if ((*v)[mid].first == i.first && (*v)[mid].second == i.second) return true;
        else if (mySort((*v)[mid], i)) low = mid+1;
        else high = mid-1;
    }
    return false;
}

long long tot(long H, long W){
    return (H-2)*(W-2);
}

int main(){
    vector < pair<long, long> > points;
    long H, W, N, x, y; cin >> H >> W >> N;
    for (int i = 0; i < N; i++){
        cin >> x >> y;
        points.push_back(make_pair(x, y));
    }
    sort(points.begin(), points.end(), mySort);

    int counter[10];
    int surr[5][5];
    for (int i = 0; i < 10; i++) counter[i] = 0;
    for (int i = 0; i < N; i++){
        long x, y;
        x = points[i].first; y = points[i].second;
        for (int j = 0; j < 5; j++){
            for (int k = 0; k < 5; k++) surr[j][k] = -1;
        }
        for (long j = max(long(1), x-2); j <= min(H, x+2); j++){
            for (long k = max(long(1), y-2); k <= min(W, y+2); k++){
                if (binarySearch(0, N, &points, make_pair(j, k))){
                    surr[2+j-x][2+k-y] = 1;
                } else surr[2+j-x][2+k-y] = 0;
            }
        }
        for (int j = 0; j < 3; j++){
            for (int k = 0; k < 3; k++){
                int tempc = 0;
                bool check = true;
                for (int l = 0; l < 3; l++){
                    for (int m = 0; m < 3; m++){
                        if (surr[j+l][k+m] == 1) tempc++;
                        else if (surr[j+l][k+m] == -1) { tempc = 0; check = false; }
                    }
                }
                if (check) counter[tempc]++;
            }
        }
    }
    long long S = 0;
    for (int i = 1; i < 10; i++){
        S += counter[i]/i;
    }
    cout << tot(H, W)-S << endl;
    for (int i = 1; i < 10; i++){
        cout << counter[i]/i << endl;
    }
    return 0;
}

