using namespace std;

class compressed{
public:
    vector<LL> xx, yy;
    vector<vector<LL>> _tab;
    LL H, W;

    compressed(LL N, vector<LL> const &x, vector<LL> const &y){
        copy(x.begin(), x.end(), back_inserter(xx));
        copy(y.begin(), y.end(), back_inserter(yy));
        sort(xx.begin(), xx.end());
        sort(yy.begin(), yy.end());
        xx.erase(unique(xx.begin(), xx.end()), xx.end());
        yy.erase(unique(yy.begin(), yy.end()), yy.end());
        W = xx.size();
        H = yy.size();
        rep(i, H)_tab.emplace_back(vector<LL>(W, 0));
        for(int i=0; i<N; i++){
            int xi = lower_bound(xx.begin(), xx.end(), x[i]) - xx.begin();
            int yi = lower_bound(yy.begin(), yy.end(), y[i]) - yy.begin();
            _tab[yi][xi] = 1;
        }
    }

    bool exist(int x, int y){
        int xi = lower_bound(xx.begin(), xx.end(), x) - xx.begin();
        int yi = lower_bound(yy.begin(), yy.end(), y) - yy.begin();
        if(xx[xi]!=x || yy[yi] != y)return false;
        if(xi==W || yi==H)return false;
        return _tab[yi][xi]>0;
    }
};


void solve(long long H, long long W, long long N, std::vector<long long> a, std::vector<long long> b){
    auto comp = compressed(N, b, a);

    vector<LL> ans(10);
    set<pair<int, int>> visited;
    rep(i, N){
        int ccy=a[i], ccx=b[i];

        for(int cx=ccx-1; cx<=ccx+1; cx++) {
            for(int cy=ccy-1; cy<=ccy+1; cy++) {
                if (cx <= 1 || cx >= W || cy <= 1 || cy >= H)continue; // corners should be neglected

                // check if visited
                auto tmp = make_pair(cx, cy);
                if(visited.find(tmp) != visited.end())continue;
                visited.insert(tmp);

                // count
                LL cnt = 0;
                for (int x = cx - 1; x <= cx + 1; x++)
                    for (int y = cy - 1; y <= cy + 1; y++)
                        if (comp.exist(x, y))cnt++;
                ans[cnt]++;
            }
        }
    }
    ans[0]=(H-2)*(W-2)-accumulate(ans.begin()+1, ans.end(), 0LL);
    for(int i=0; i<10; i++)
        cout << ans[i] << endl;
}

int main(){
    long long H;
    scanf("%lld",&H);
    long long W;
    scanf("%lld",&W);
    long long N;
    scanf("%lld",&N);
    std::vector<long long> a(N);
    std::vector<long long> b(N);
    for(int i = 0 ; i < N ; i++){
        scanf("%lld",&a[i]);
        scanf("%lld",&b[i]);
    }
    solve(H, W, N, std::move(a), std::move(b));
    return 0;
}

