#include <bits/stdc++.h>

#define ll  long long

#define AREA_W  3
#define AREA_H  3

void solve(const ll H, const ll W, const std::vector<std::pair<ll, ll>>& I)
{
    std::vector<std::pair<ll, ll>> P;
    for (auto itr = I.begin(); itr != I.end(); ++itr)
    {
        for (int w = 0; w < AREA_W; w++)
        {
            for (int h = 0; h < AREA_H; h++)
            {
                if (1 <= itr->second - w && itr->second - w <= W - (AREA_W - 1) && 1 <= itr->first - h && itr->first - h <= H - (AREA_H - 1))
                {
                    P.push_back(std::make_pair(itr->second - w, itr->first - h));
                }
            }
        }
    }
    std::sort(P.begin(), P.end());

    int c = 1;
    std::vector<ll> A(10, 0);
    A[0] = (H - (AREA_H - 1)) * (W - (AREA_W - 1));
    for (int i = 0; i < P.size(); i++)
    {
        if (P[i].first == P[i + 1].first && P[i].second == P[i + 1].second)
        {
            c++;
        }
        else
        {
            A[0]--;
            A[c]++;
            c = 1;
        }
    }

    for (auto itr = A.begin(); itr != A.end(); ++itr)
    {
        std::cout << *itr << std::endl;
    }
}

int main(void)
{
    int H, W, N;
    std::cin >> H >> W >> N;

    std::vector<std::pair<ll, ll>> I(N);
    for (ll i = 0; i < N; i++)
    {
        std::cin >> I[i].first >> I[i].second;
    }
    solve(H, W, I);

    return 0;
}

