ll dx[9] = {0, -1, -2, 0, -1, -2, 0, -1, -2};
ll dy[9] = {0, 0, 0, -1, -1, -1, -2, -2, -2};

int compress(int n, vl &X, ll w) {
  vector<ll> xs;
  rep(i, 0, n) {
    for (int d = -1; d <= 1; d++) {
      int tx = X[i]+d;
      if (1 <= tx && tx <= w) xs.pb(tx);
    }
  }

  sort(All(xs));
  xs.erase(unique(All(xs)), xs.end());
  rep(i, 0, n) {
    X[i] = lbidx(xs, X[i]);
  }

  return xs.size();
};

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  ll h, w;
  cin >> h >> w;
  int n;
  cin >> n;

  vl X(n), Y(n);
  rep(i, 0, n) {
    cin >> Y[i] >> X[i];
  }

  ll W = compress(n, X, w);
  ll H = compress(n, Y, h);

  map<PLL, int> mp;

  vl ans(10, 0ll);
  vector<vector<bool>> counted(n, vector<bool> (9, false));
  rep(i, 0, n) {
    ll xi = X[i];
    ll yi = Y[i];
    rep(j, 0, 9) { // 黒い点についてどの位置としてカウントされるか
      // カウントされる時3x3の原点
      ll ox = xi + dx[j];
      ll oy = yi + dy[j];
      if (0ll <= ox && ox < W-2 && 0ll <= oy && oy < H-2) {
        bool flag = true;
        rep(k, 0, 9) { // その位置がカウントされていない黒い点かどうか
          ll r = k / 3ll;
          ll c = k % 3ll;
          ll x = ox + c;
          ll y = oy + r;
          if (Find(mp, make_pair(y, x))) { // 黒い点である
            if (counted[mp[make_pair(y, x)]][k]) { // その位置としてカウントされた黒い点である
              flag = false;
              break;
            }
          }
        }
        if (flag) {
          int tmp = 0;
            rep(k, 0, 9) {
            ll r = k / 3ll;
            ll c = k % 3ll;
            ll x = ox + c;
            ll y = oy + r;
            if (Find(mp, make_pair(y, x))) { // 黒い点である
              counted[mp[make_pair(y, x)]][k] = true;
              tmp++;
            }
          }
          ans[tmp]++;
        }
      }
    }
  }

  ans[0] = (h-2ll) * (w-2ll);
  rep(i, 1, 10) {
    ans[0] -= ans[i];
  }

  rep(i, 0, 10) {
    cout << ans[i] << endl;
  }

  return 0;
};

