#include <bits/stdc++.h>
using namespace std;
using LL = long long;
using PLL = pair<LL,LL>;
#define MP make_pair


void cnt(PLL cp, vector<LL>& res, set<PLL>& ps){
  int c = 0;
  for(int dx=-1;dx<=1;++dx)
	for(int dy=-1;dy<=1;++dy)
	  if(ps.count(MP(cp.first+dx, cp.second+dy)))
		++c;
  res[c]++;
}

int main(){
  LL H, W, N; cin >> H >> W >> N;
  set<PLL> ps;
  vector<PLL> evs;
  for(int i=0;i<N;++i){
	PLL p; cin >> p.second >> p.first;
	ps.insert(p);
	for(LL x=max(1LL,p.first-2);x<=min(W,p.first+2);++x)
	  for(LL y=max(1LL,p.second-2);y<=min(H,p.second+2);++y)
		evs.emplace_back(x, y);
  }
  sort(begin(evs), end(evs));
  evs.erase(unique(begin(evs), end(evs)), end(evs));

  vector<LL> ans(10, 0);
  for(auto&& p: evs){
	if(p.first-1 <= 0 || p.first+1 > W) continue;
	if(p.second-1 <= 0 || p.second+1 > H) continue;
	cnt(p, ans, ps);
  }
  LL sum = 0;
  for(int i=0;i<10;++i)
	sum += ans[i];
  ans[0] += (H-2)*(W-2) - sum;

  for(int i=0;i<10;++i)
	cout << ans[i] << endl;

  return 0;
}

