  map<int, map<int, bool> > grid;
  map<int, ll> counter;
  counter[0] = (H - 2) * (W - 2);

  for (int i = 0; i < N; i++) {
    int a, b;
    cin >> a >> b;

    grid[a][b] = true;

    for (int j = 0; j < 3; j++) {
      for (int k = 0; k < 3; k++) {
        int cnt = 0;
        int cy = a + D1[j];
        int cx = b + D1[k];
        if (cy <= 0 || cx <= 0 || H < cy + 2 || W < cx + 2) continue;

