            int ny = cy + D2[n];
            int nx = cx + D2[m];

            if (grid[ny][nx]) cnt++;
          }
        }

        counter[cnt - 1]--;
        counter[cnt]++;
      }
    }
  }

  for (int i = 0; i <= 9; i++) {
    cout << counter[i] << endl;
  }

  return 0;
}

