bool check(int i, int j) {
    return (i >= 1 && i <= N && j >= 1 && j <= M);
}

void calc(int x, int y) {
    int cnt = 0;
    REP(i, -1, 1) REP(j, -1, 1) {
        if(!check(x+i, y+j)) return;
        if(mp.count(mk(x+i, y+j))) cnt++;
    }
    ans[0]--; ans[cnt]++;
}

void calc() {
    map<ii, bool> vis;
    rep(k, 0, K)
        REP(i, -1, 1) REP(j, -1, 1) {
