}s[MAXN];
bool cmp1(node A,node B){
	return A.a<B.a||(A.a==B.a&&A.b<B.b);
}
bool cmp2(node A,node B){
	return A.b<B.b||(A.b==B.b&&A.a<B.a);
}
map<int,int>T[MAXN];
void check(int x,int y){
	for(int i=0;i<9;i++){
		int w1=x+f[i][0];
		int w2=y+f[i][1];
		if(w1>1&&w2>1&&w1<h&&w2<w){
			ans[T[w1][w2]]--;
			ans[++T[w1][w2]]++;
			//for(int i=1;i<=h;i++){for(int j=1;j<=w;j++)printf("%d ",T[i][j]);puts("");}puts("");
		}
	}
