int main() {
    int H,W,N,a,b;
    int ans[10]={0};
    set<pii> s1,s2;
    scanf("%d%d%d",&H,&W,&N);
    while (N--){
        scanf("%d%d",&a,&b);
        s1.insert({a,b});
        for(int i=0;i<3;i++)for(int j=0;j<3;j++)s2.insert({a-i,b-j});
