	mint nCrMod(lint n, lint r)
	{
		if (n < r || n < 0 || r < 0)
		{
			return 0;
		}
		r = mmin(r, n - r);
		mint a = 1;
		repb(i, n - r + 1, n)
		{
			a *= i;
		}

		a /= factMod(r);
		return a;
	}

	mint nHrMod(lint n, lint r)
	{
		return nCrMod(n + r - 1, r);
	}

