array<uint, 10> getResult(const int heightSize, const int widthSize,
                          const vector<pair<long, long>> &drawPosList){
  vector<vector<uint>> blackCount(heightSize-2, vector<uint>(widthSize-2));
  for(size_t i = 0; i < heightSize-2; i++){
    for(size_t j = 0; j < widthSize-2; j++){
      blackCount[i][j] = 0;
    }
  }

  for(pair<long, long> drawPos : drawPosList){
    uint h = (drawPos.first < 2)? 0 : drawPos.first - 2;
    uint hMax = (drawPos.first < heightSize - 2)? drawPos.first : heightSize - 3;
    for(; h <= hMax; h++){
      uint w = (drawPos.second < 2)? 0 : drawPos.second - 2;
      uint wMax = (drawPos.second < widthSize - 2)? drawPos.second : widthSize - 3;
      for(; w <= wMax; w++){
        blackCount[h][w]++;
      }
    }
  }

  array<uint, 10> result = {0};
  for(vector<uint> blackCountH : blackCount){
    for(uint blackCountHW : blackCountH){
      result[blackCountHW]++;
    }
  }

  return result;
}

int main(){
  long H, W;
  uint N;
  cin >> H >> W >> N;
  vector<pair<long, long>> drawPosList(N);
  for(uint i = 0; i < N; i++){
    int ai, bi;
    cin >> ai >> bi;
    drawPosList[i].first = ai - 1;
    drawPosList[i].second = bi - 1;
  }

  array<uint, 10> result = getResult(H, W, drawPosList);

  for(uint r : result){
    cout << r << endl;
  }
  return 0;
}

