#define mp make_pair
using namespace std;

map<pair<int,int>,int> m;
map< pair<pair<int,int>,pair<int,int> >,int> mm;

int h,w,n,x[100010],y[100010],cnt[11];

int dx1[]={-2,-2,-2,-1,-1,-1,0,0,0},dy1[]={-2,-1,0,-2,-1,0,-2,-1,0},dx2[]={0,0,0,1,1,1,2,2,2},dy2[]={0,1,2,0,1,2,0,1,2};

inline int check(int x1,int y1,int x2,int y2)
{
	if(1<=x1&&1<=y1&&x2<=h&&y2<=w)
	{
		return 1;
	}
	return 0;
}

inline void count_(int x1,int y1,int x2,int y2)
{
	int ans=9;
	for(int xx=x1;xx<=x2;xx++)
	{
		for(int yy=y1;yy<=y2;yy++)
		{
			if(m.count(mp(xx,yy))==0)
			{
				ans--;
			}
		}
	}
	cnt[ans]++;
}

inline void solve(int x,int y)
{
	for(int i=0;i<=8;i++)
	{
		int x1=x+dx1[i];
		int y1=y+dy1[i];
		int x2=x+dx2[i];
		int y2=y+dy2[i];
		if(check(x1,y1,x2,y2)&&mm.count(mp(mp(x1,y1),mp(x2,y2)))==0)
		{
			mm[mp(mp(x1,y1),mp(x2,y2))]=1;
			count_(x1,y1,x2,y2);
		}
	}
}

int main()
{
	scanf("%d%d%d",&h,&w,&n);
	for(int i=1;i<=n;i++)
	{
		scanf("%d%d",&x[i],&y[i]);
		m[mp(x[i],y[i])]=1;
	}
	for(int i=1;i<=n;i++)
	{
		solve(x[i],y[i]);
	}
	long long sum=1ll*(h-2)*(w-2);
	for(int i=1;i<=9;i++)
	{
		sum-=cnt[i];
	}
	printf("%lld\n",sum);
	for(int i=1;i<=9;i++)
	{
		printf("%d\n",cnt[i]);
	}
}

