}

struct UnionFind {
    vector<int> data;
    UnionFind(int size) : data(size, -1) { }
    bool unionSet(int x, int y) {
        x = root(x); y = root(y);
        if (x != y) {
            if (data[y] < data[x]) swap(x, y);
            data[x] += data[y]; data[y] = x;
        }
        return x != y;
    }
    bool findSet(int x, int y) {
        return root(x) == root(y);
    }
    int root(int x) {
        return data[x] < 0 ? x : data[x] = root(data[x]);
    }
    int size(int x) {
        return -data[root(x)];
    }
};

const ll mod = (ll)(1e9+7);

struct SimpleHash {
    size_t operator()(const std::pair<ll, ll>& p) const {
        return p.first * mod + p.second;
    }
};

int main()
{
    ll h,w,n;
    cin >> h >> w >> n;
    unordered_set<pii, SimpleHash> s;
    unordered_set<pii, SimpleHash> dot;
    vector<pii> hi;
    for(int i = 0;i < n;i++)
    {
        ll y, x;
        cin >> y >> x;
        y--;
        x--;
        dot.insert(make_pair(x,y));
        for(ll dx = max((ll)1L, (ll)(x-1L)); dx <= min(w-2L, x+1L);dx++)
        {
            for(ll dy = max((ll)1L, (ll)(y-1L)); dy <= min(h-2L, y+1L);dy++)
            {
                pii d = make_pair(dx, dy);
                if(s.find(d) == s.end())
                {
                    hi.push_back(d);
                    s.insert(make_pair(dx, dy));
                }
            }
        }
    }
    map<pii, int> counts;
    ll cs[10];
    fill(cs, cs + 10, 0);
    for(auto& e: hi)
    {
        ll x = e.first;
        ll y = e.second;
        int c = 0;
        for(ll dx = max((ll)0L, (ll)(x-1L)); dx <= min(w-1L, x+1L);dx++)
        {
            for(ll dy = max((ll)0L, (ll)(y-1L)); dy <= min(h-1L, y+1L);dy++)
            {
                if(dot.find(make_pair(dx, dy)) != dot.end())
                {
                    c++;
                }
            }
        }
        counts[e] = c;
        cs[c]++;
    }
    ll nz = 0;
    for(int i = 1;i < 10;i++)
    {
        nz += cs[i];
    }
    cs[0] = (w-2) * (h-2) - nz;
    for(int i = 0;i < 10;i++)
    {
        cout << cs[i] << endl;
    }    
    return 0;
}

