#include<bits/stdc++.h>
using namespace std;

int main(){
  int h, w, n;
  vector<int> a, b;
  map<pair<int, int>, int> m;
  int dx[9] = {0,-1,0,1,1,1,0,-1,-1};
  int dy[9] = {0,-1,-1,-1,0,1,1,1,0};
  unsigned long long int res[10] = {};
  int x, y, k, count=0;

  cin >> h >> w >> n;
  a.resize(n);
  b.resize(n);
  for(int i=0; i<n; ++i){
    cin >> b[i] >> a[i];

    for(k=0; k<9; ++k){
      x=a[i]+dx[k];
      y=b[i]+dy[k];

      if(x>=1 && x<=w && y>=1 && y<=h){
	auto itr = m.find(make_pair(x,y));
	if(itr != m.end()){
	  itr->second++;
	}else{
	  m[make_pair(x,y)]=1;
	}
      }
    }
  }

  for(auto itr=m.begin(); itr!=m.end(); ++itr){
    pair<int,int> p = itr->first;

    if(p.first!=1 && p.first!=w && p.second!=1 && p.second!=h){
      res[itr->second]++;
      count++;
    }
  }

  res[0] = (unsigned long long int)(h-2)*(w-2)-count;

  for(int i=0; i<10; ++i){
    cout << res[i] << endl;
  }

  return 0;
}

