#define all(vec) vec.begin(), vec.end()

using ll = long long;
const char dx[9] = { 1,1,1,0,0,0,-1,-1,-1 }, dy[9] = { 1,0,-1,1,0,-1,1,0,-1 };

ll h, w, n, a, b, cnt, x, y, nx, ny, nnx, nny, sum, ans[10];
char j, k;
vector<ll>v;
unordered_map<ll, bool>mp;
signed main() {
	scanf("%lld %lld %lld", &h, &w, &n);
	rep(i, n) {
		scanf("%lld %lld", &a, &b);
		--a; --b;
		v.emplace_back(w * a + b);
	}
    sort(all(v));
	for (ll i : v) {
		y = i / w, x = i % w;
		for (j = 0; j < 9; ++j) {
			nx = x + dx[j], ny = y + dy[j];
			if (0 < nx && nx < w - 1 && 0 < ny && ny < h - 1) {
				if (!mp[w * ny + nx]) {
					mp[w * ny + nx] = true;
					for (k = 0; k < 9; ++k) {
						nnx = nx + dx[k], nny = ny + dy[k];
						if (binary_search(all(v), w * nny + nnx)) {
							++cnt;
						}
					}
					++ans[cnt];
					++sum;
					cnt = 0;
				}
			}
		}
	}
	ans[0] += (h - 2) * (w - 2) - sum;
	for (ll i : ans) {
		printf("%lld\n", i);
	}
}

