int count(map<pair<long long, long long>, bool> &x, int start_idx_h, int start_idx_w, long long H, long long W)
{
    if (start_idx_h < 0 || H <= start_idx_h + 2)
    {
        return -1;
    }

    if (start_idx_w < 0 || W <= start_idx_w + 2)
    {
        return -1;
    }

    int ret = 0;
    for (long long i = start_idx_h; i < start_idx_h + 3; i++)
    {
        for (long long j = start_idx_w; j < start_idx_w + 3; j++)
        {
            if (x[make_pair(i, j)])
            {
                ret++;
            }
        }
    }
    return ret;
}

