          num += pts.count({basei + i, basej + j});
        }
        cnt[{basei, basej}] = num;
      }
    }
  }

  for(auto e: cnt) {
    ans[e.second]++;
  }

  ans[0] = ll(H - 2) * (W - 2);
  REP(i, 1, 10) {
    ans[0] -= ans[i];
  }

  rep(i, 10) {
