uint getBlackCount(const uint heightPos, const uint widthPos,
                   const vector<pair<uint, uint>> &drawPosList){
  uint count = 0;
  for(pair<uint, uint> drawPos : drawPosList){
    for(uint h = heightPos; h <= heightPos + 2; h++){
      for(uint w = widthPos; w <= widthPos + 2; w++){
      	if(drawPos.first == h + 1 && drawPos.second == w + 1) count++;
      }
    }
  }
  return count;
}

array<uint, 10> getResult(const uint heightSize, const uint widthSize,
                          const vector<pair<uint, uint>> &drawPosList){
  array<uint, 10> blackCountList = {0};
  for(uint h = 0; h + 2 < heightSize; h++){
    for(uint w = 0; w + 2 < widthSize; w++){
      uint count = getBlackCount(h, w, drawPosList);
      blackCountList[count]++;
    }
  }
  return blackCountList;
}

