  for(int i = 0; i < N; i++){
    cin >> drawPosList[i].first >> drawPosList[i].second;
  }

  array<uint, 10> result = getResult(H, W, drawPosList);

  for(uint r : result){
    cout << r << endl;
  }
  return 0;
}

