#include <bits/stdc++.h>
#define SVLL set<vector<LL>>
#define VLL vector<LL>
using namespace std;
typedef long long LL;
int countBlack(SVLL &black, LL a, LL b, LL h, LL w){
    int count = 0;
    for(int i = a - 1; i <= a + 1; i++){
        for(int j = b - 1; j <= b + 1; j++){
            count += black.find(VLL {i, j}) != black.end(); //O(log N)
        }
    }
    return count;
}
void updateBox(SVLL &black, LL *box, LL a, LL b, LL h, LL w){
    for(int i = max((LL)2, a - 1); i <= min(h - 1, a + 1); i++){
        for(int j = max((LL)2, b - 1); j <= min(w - 1, b + 1); j++){
            int t = countBlack(black, i, j, h, w);
            box[t]--;
            box[t + 1]++;
        }
    }
}
int main(){
    LL h, w, n, a, b;
    LL box[10] = {};
    SVLL black;

    cin >> h >> w >> n;
    box[0] = (h - 2) * (w - 2);
    for(int i = 0; i < n; i++){
        cin >> a >> b;
        updateBox(black, box, a, b, h, w);
        black.insert(VLL {a, b});   //O(log N)
    }
    for(auto v: box){
        cout << v << endl;
    }
    return 0;
}

