void solve()
{
	ll h,w,n;  cin >> h >> w >> n;
	vector<pair<ll,ll>> ab(n);
	rep(i,0,n-1){ ll a; ll b; cin>>a>>b; ab[i]={a-1,b-1}; }

	set<pll> st;

	vll ans(10);
	ans[0]=(h-2)*(w-2);

	rep(i,0,n-1){
		ll x,y;  tie(x,y) = ab[i];
		vvll mp_(5,vll(5));
		auto mp = [&](ll i,ll j)->ll&{
			return mp_[i+2][j+2];
		};

		rep(xx,-2,2){
			rep(yy,-2,2){
				if (st.count({x+xx,y+yy})==1){
					mp(xx,yy)=1;
				}
			}
		}

		rep(xx,-1,1){
			rep(yy,-1,1){
				ll zx=x+xx;
				ll zy=y+yy;
				if (zx<1 or h-2<zx or zy<1 or w-2<zy)continue;

