LL dy[9]={-2,-1,0,-2,-1,0,-2,-1,0};
void solve(LL x,LL y)
{
	LL a,b,id;
	for(int i=0;i<9;i++)
	{
		a=x+dx[i];
		b=y+dy[i];
		if(a<1||b<1||a>H-2||b>W-2) continue;
