ll cnt[10];

pair<int,int> countP(int x, int y)
{
    if(x+2 >= h || y + 2 >= w || x < 0 || y < 0)
        return {0,0};
    int t = 0;
    int l = 0;
    for(int i=x; i<=x+2; i++)
        for(int j=y; j<=y+2; j++)
            if(p.find({i,j}) != p.end()){
                t++;
                l = (i-x) * 3 + j-y;
            }
    return {t,l};
}

int main()
{
    cin >> h >> w >> n;
    int x,y;
    for(int i=0; i<n; i++)
    {
        cin >> x >> y;
        p.insert({x-1,y-1});
    }

    ll sum = 0;
    for(auto it : p)
    {
        x = it.first;
        y = it.second;
        for(int i = x - 2; i <= x; i++)
            for(int j=y-2; j <= y; j++)
            {
                pair<int,int> val = countP(i,j);
                if(val.first <= 0 || val.second > (x-i) * 3 + y-j)
                    continue;
                cnt[val.first]++;
                sum++;
            }
    }
    cnt[0] = 1ll * (h-2) * (w-2) - sum;
    for(int i=0; i<10; i++)
        cout << cnt[i] << "\n";
