void add (LL x, LL y)
{
	LL tx, ty;
	for (int i = 0; i < 3; ++i)
		for (int j = 0; j < 3; ++j)
		{
			tx = x + dx[i];
			ty = y + dy[j];
			if(tx < 1 || ty < 1 || tx > h - 2 || ty > w - 2)
				continue;
			++mp[(tx - 1) * (w - 2)+ty];
		}
}

