					if (D.in(nxt1, D2::R, ww)) {
						auto nxt = D.next(nxt1, D2::R, ww);
						if (0 < D.W(nxt) && D.W(nxt) < w - 1 && 0 < D.H(nxt) && D.H(nxt) < h - 1)
