        if(x > 2)
            u = true;
        if(y > 2)
            l = true;
        if(x < h - 1)
            d = true;
        if(y < w - 1)
            r = true;
        if(u&&y>1&&y<w) (sq.count(pii (x-2,y-1))?sq.at(pii (x-2,y-1))+=1:sq[pii (x-2,y-1)]=1);
        if(u&&l) (sq.count(pii (x-2,y-2))?sq.at(pii (x-2,y-2))+=1:sq[pii (x-2,y-2)]=1);
        if(u&&r) (sq.count(pii (x-2,y))?sq.at(pii (x-2,y))+=1:sq[pii (x-2,y)]=1);
        if(d&&y>1&&y<w) (sq.count(pii (x,y-1))?sq.at(pii (x,y-1))+=1:sq[pii (x,y-1)]=1);
        if(d&&l) (sq.count(pii (x,y-2))?sq.at(pii (x,y-2))+=1:sq[pii (x,y-2)]=1);
        if(d&&r) (sq.count(pii (x,y))?sq.at(pii (x,y))+=1:sq[pii (x,y)]=1);
        if(l&&x>1&&x<h) (sq.count(pii (x-1,y-2))?sq.at(pii (x-1,y-2))+=1:sq[pii (x-1,y-2)]=1);
        if(r&&x>1&&x<h) (sq.count(pii (x-1,y))?sq.at(pii (x-1,y))+=1:sq[pii (x-1,y)]=1);
        if(x>1&&x<h&&y>1&&y<w) (sq.count(pii (x-1,y-1))?sq.at(pii (x-1,y-1))+=1:sq[pii (x-1,y-1)]=1);
    }
    for(pair <pii, int> p : sq){
        vec.at(p.second) += 1;
    }
    vec.at(0) = all - sq.size();
    vout(vec);
}

