void bfs(P now) {
	P next, target;
	ll h, w;
	ll num;

	if (visited.find(now) != visited.end()) return;

	visited.insert(now);
	h = now.first;
	w = now.second;

	if (h > 1) {
		next = make_pair(now.first - 1, now.second);
		bfs(next);
		if (w > 0) {
			next = make_pair(now.first - 1, now.second - 1);
			bfs(next);
		}
		if (w < W) {
			next = make_pair(now.first - 1, now.second + 1);
			bfs(next);
		}
	}
	if (h < H) {
		next = make_pair(now.first + 1, now.second);
		bfs(next);
		if (w > 0) {
			next = make_pair(now.first + 1, now.second - 1);
			bfs(next);
		}
		if (w < W) {
			next = make_pair(now.first + 1, now.second + 1);
			bfs(next);
		}
	}
	if (w > 1) {
		next = make_pair(now.first, now.second - 1);
		bfs(next);
	}
	if (w < W) {
		next = make_pair(now.first, now.second + 1);
		bfs(next);
	}

	if (h > 1 && h < H && w > 1 && w < W) {
		num = 0;
		rep(i, 3) {
			rep(j, 3) {
				target = make_pair(h - 1 + i, w - 1 + j);
				if (ab.find(target) != ab.end()) {
					num++;
				}
			}
		}
		ans[num]++;
	}
}

