  rep(i, n) {
    int a, b;
    cin >> a >> b;
    if(mp.find(P(a, b)) == mp.end()) {
      mp[P(a, b)] |= false;;
      rep(k, 8) {
        int na = a+di[k], nb = b+dj[k];
        if(na < 1 || na > h || nb < 1 || nb > w) continue;
        mp[P(na, nb)] |= false;
      }
    }
    mp[P(a, b)] |= true;
  }
  vector<ll> ans(10, 0);
  ans[0] = (h-2)*(w-2);
  for(auto x : mp) {
    auto p = x.first;
    if(p.first < 2 || p.first > h-1 || p.second < 2 || p.second > w-1) continue;
    int c = 0;
