int counting(long long int x, long long int y)
{
	int res = 0;

	for (long long int i = y; i <= y + 2; i++)
	{
		for (long long int j = x; j <= x + 2; j++)
		{
			if (painted[make_pair(i, j)] == 1)
			{
				res += 1;
			}
		}
	}

	return res;
}
int main(void)
{
