	{
		cin >> a >> b;
		painted[make_pair(a,b)] = 1;
	}
	//아무것도 색칠되지 않았다고 설정.
	count[0] = (H - 2)*(W - 2);

	//블락에 몇개나 색칠되어 있는지 확인.
	for (auto it = painted.begin(); it != painted.end(); it++)
	{
		int res;
		long long int x = it->first.second;
		long long int y = it->first.first;
		if (y > H - 2 || x > W - 2)
		{
			continue;
		}
		res = counting(x, y);
		//0이면 안해도 됨.
		if (res != 0)
		{
			count[res] += 1;
			count[0] -= 1;
		}
	}

	for (int i = 0; i < 10; i++)
	{
		cout << count[i] << endl;
	}
	return 0;
}

