typedef pair<long, long> P;

int binary_search(vector<P> &tmp, long long x, long long y_up, long long y_down){
    int ok = (int)tmp.size();
    int ng = -1;
    while (abs(ok - ng) > 1){
        int mid = (ok + ng) / 2;
        if (tmp[mid].first >= x) ok = mid;
        else ng = mid;
    }
    int ok2 = (int)tmp.size();
    int ng2 = -1;
    while (abs(ok2 - ng2) > 1){
        int mid = (ok2 + ng2) / 2;
        if (tmp[mid].first >= x + 1) ok2 = mid;
        else ng2 = mid;
    }
    int ok3 = ok2;
    int ng3 = ng;
    while (abs(ok3 - ng3) > 1){
        int mid = (ok3 + ng3) / 2;
        if (tmp[mid].second >= y_up) ok3 = mid;
        else ng3 = mid;
    }
    int ok4 = ok2;
    int ng4 = ng;
    while (abs(ok4 - ng4) > 1){
        int mid = (ok4 + ng4) / 2;
        if (tmp[mid].second >= y_donw + 1) ok4 = mid;
        else ng4 = mid;
    }
    return ng4 - ng3;
}

