			tot=a[mp(x-1,y)]+a[mp(x-1,y+1)]+a[mp(x-1,y+2)]+a[mp(x,y)]+a[mp(x,y+1)]+a[mp(x,y+2)]+a[mp(x+1,y)]+a[mp(x+1,y+1)]+a[mp(x+1,y+2)];
