#include <bits/stdc++.h>

#define ll  long long

#define WHITE   0
#define BLACK   1

int black3x3(const std::vector<std::vector<ll>>& b, const ll x, const ll y)
{
    int a = 0;
    for (int i = 0; i < 3; i++)
    {
        for (int j = 0; j < 3; j++)
        {
            if (BLACK == b[y + i][x + j])
            {
                a++;
            }
        }
    }
    return a;
}

void solve(const ll H, const ll W, const std::vector<std::pair<ll, ll>>& P)
{
    if (!P.size())
    {
        std::cout << ((H - 2) * (W - 2)) << std::endl;
        for (int i = 0; i < 9; i++)
        {
            std::cout << 0 << std::endl;
        }
        return;
    }

    std::vector<std::vector<ll>> b;
    try
    {
        b.resize(H);
        for (ll i = 0; i < H; i++)
        {
            b[i].resize(W);
        }
    }
    catch (std::bad_alloc& e)
    {
        for (ll i = 0; i < 10; i++)
        {
            std::cout << 0 << std::endl;
        }
        return;
    }

    for (auto itr = P.begin(); itr != P.end(); ++itr)
    {
        b[itr->first - 1][itr->second - 1] = BLACK;
    }

    std::vector<ll> p(10);
    for (ll x = 0; x < W - 2; x++)
    {
        for (ll y = 0; y < H - 2; y++)
        {
            p[black3x3(b, x, y)]++;
        }
    }

    for (auto itr = p.begin(); itr != p.end(); ++itr)
    {
        std::cout << *itr << std::endl;
    }
}

int main(void)
{
    int H, W, N;
    std::cin >> H >> W >> N;

    std::vector<std::pair<ll, ll>> P(N);
    for (ll i = 0; i < N; i++)
    {
        std::cin >> P[i].first >> P[i].second;
    }
    solve(H, W, P);

    return 0;
}

