bool check(int i, int j) {
    return (i >= 1 && i <= N && j >= 1 && j <= M);
}

int calc(int x, int y, int j) {
    int cnt = 0;
    REP(i, -1, 1) REP(j, -1, 1)
        if(!check(x+i, y+j)) return 0;

    REP(i, -1, 1) REP(j, -1, 1)
        if(mp.count(mk(x+i, y+j))) cnt++;
    return (cnt == j);
}

int calc(int p) {
    map<ii, bool> vis;
    int ans = 0;
    rep(k, 0, K)
        REP(i, -1, 1) REP(j, -1, 1) {
            if(!vis[mk(v[k].F+i, v[k].S+j)])
                ans += calc(v[k].F+i, v[k].S+j, p);
            vis[mk(v[k].F+i, v[k].S+j)] = 1;
        }
    return ans;
}

