class UnionFind
{
public:
    vector<ll> Parent;

    UnionFind(ll N)
    {
        Parent = vector<ll>(N, -1);
    }
    ll find(ll A)
    {
        if (Parent[A] < 0)
            return A;
        return Parent[A] = find(Parent[A]);
    }

    ll size(ll A)
    {
        return -Parent[find(A)];
    }

    bool Union(ll A, ll B)
    {
        A = find(A);
        B = find(B);
        if (A == B)
        {
            return false;
        }
        if (size(A) < size(B))
            swap(A, B);

        Parent[A] += Parent[B];
        Parent[B] = A;

        return true;
    }
};

ll gcd(ll a, ll b)
{
    if (b == 0)
        return a;
    return gcd(b, a % b);
}

ll lcm(ll a, ll b)
{
    ll g = gcd(a, b);
    return a / g * b;
}

ll mulMod(ll a, ll b)
{
    return (((a % MOD) * (b % MOD)) % MOD);
}

ll powMod(ll a, ll p)
{
    if (p == 0)
    {
        return 1;
    }
    else if (p % 2 == 0)
    {
        ll half = powMod(a, p / 2);
        return mulMod(half, half);
    }
    else
    {
        return mulMod(powMod(a, p - 1), a);
    }
}

ll ceil(ll a, ll b)
{
    return (a + b - 1) / b;
}

void solve(long long H, long long W, long long N, std::vector<long long> a, std::vector<long long> b)
{
    vector<vector<ll>> mapping(H, vector<ll>(W));

    for (int i = 0; i < N; i++)
    {
        for (ll x = max(0LL, a[i] - 1); x <= min(H - 1, a[i] + 1); x++)
        {
            for (ll y = max(0LL, b[i] - 1); y <= min(W - 1, b[i] + 1); y++)
            {
                mapping[x][y]++;
            }
        }
    }

    vector<ll> ans(10, 0);
    for (int i = 1; i < H - 1; i++)
    {
        for (int j = 1; j < W - 1; j++)
        {
            ans[mapping[i][j]]++;
        }
    }

    for (int i = 0; i < 10; i++)
    {
        cout << ans[i] << endl;
    }
}

int main()
{
    long long H;
    scanf("%lld", &H);
    long long W;
    scanf("%lld", &W);
    long long N;
    scanf("%lld", &N);
    std::vector<long long> a(N);
    std::vector<long long> b(N);
    for (int i = 0; i < N; i++)
    {

        scanf("%lld", &a[i]);
        scanf("%lld", &b[i]);
        a[i]--;
        b[i]--;
    }
    solve(H, W, N, std::move(a), std::move(b));
    return 0;
}

