//main code
class HashPair {
public:
    static size_t m_hash_pair_random;
	template<class T1, class T2>
	size_t operator()(const pair<T1, T2> &p) const {
		auto hash1 = hash<T1>{}(p.first);
		auto hash2 = hash<T2>{}(p.second);

		size_t seed = 0;
        seed ^= hash1 + 0x9e3779b9 + (seed << 6) + (seed >> 2);
        seed ^= hash2 + 0x9e3779b9 + (seed << 6) + (seed >> 2);
		seed ^= m_hash_pair_random + 0x9e3779b9 + (seed << 6) + (seed >> 2);
        return seed;
	}
};
size_t HashPair::m_hash_pair_random = (size_t) random_device()();

int main(int argc, char const* argv[])
{
	LL h,w,n;
	cin >> h >> w >> n;
	VL a(n), b(n);
	for (int i = 0; i < n; i++) {
		cin >> a[i] >> b[i];
		a[i]--;b[i]--;
	}
	unordered_map<PLL, LL, HashPair> mp;
	auto h_ok = [&](LL a){if(a < 2 or a >= h) return false; return true;};
	auto w_ok = [&](LL a){if(a < 2 or a >= w) return false; return true;};
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < 3; j++) {
			for (int k = 0; k < 3; k++) {
				LL hi = a[i]+j;
				LL wi = b[i]+k;
				if (h_ok(hi) and w_ok(wi)) {
					mp[{hi,wi}]++;
				}
			}
		}
	}
	VL ans(10,0);
	LL c = 0;
	for (auto i : mp) {
		ans[i.second]++;
		c++;
	}
	ans[0] = (h-2)*(w-2)-c;
	for (auto i : ans) {
		cout << i << endl;
	}
	return 0;
}

