void warshall_floyd(ll n)
{
    for (size_t i = 0; i < n; i++)
    {
        for (size_t j = 0; j < n; j++)
        {
            for (size_t k = 0; k < n; k++)
            {
                dist[j][k] = min(dist[j][k], dist[j][i] + dist[i][k]);
            }
        }
    }
}

class UnionFind
{
public:
    vector<ll> Parent;

    UnionFind(ll N)
    {
        Parent = vector<ll>(N, -1);
    }
    ll find(ll A)
    {
        if (Parent[A] < 0)
            return A;
        return Parent[A] = find(Parent[A]);
    }

    ll size(ll A)
    {
        return -Parent[find(A)];
    }

    bool Union(ll A, ll B)
    {
        A = find(A);
        B = find(B);
        if (A == B)
        {
            return false;
        }
        if (size(A) < size(B))
            swap(A, B);

        Parent[A] += Parent[B];
        Parent[B] = A;

        return true;
    }
};

ll gcd(ll a, ll b)
{
    if (b == 0)
        return a;
    return gcd(b, a % b);
}

ll lcm(ll a, ll b)
{
    ll g = gcd(a, b);
    return a / g * b;
}

ll mulMod(ll a, ll b)
{
    return (((a % MOD) * (b % MOD)) % MOD);
}

ll powMod(ll a, ll p)
{
    if (p == 0)
    {
        return 1;
    }
    else if (p % 2 == 0)
    {
        ll half = powMod(a, p / 2);
        return mulMod(half, half);
    }
    else
    {
        return mulMod(powMod(a, p - 1), a);
    }
}

ll ceil(ll a, ll b)
{
    return (a + b - 1) / b;
}

void solve(long long H, long long W, long long N, std::vector<long long> a, std::vector<long long> b)
{
    set<pair<int, int>> S;
    set<pair<int, int>> S2;
    ll ans[10] = {0};
    for (int i = 0; i < N; i++)
    {
        S.insert({a[i], b[i]});
        for (int j = 0; j < 3; j++)
        {
            for (int k = 0; k < 3; k++)
            {
                S2.insert({a[i] - j, b[i] - k});
            }
        }
    }

    ans[0] = (H - 2) * (W - 2);
    for (auto &&i : S2)
    {
        int x = i.first;
        int y = i.second;
        if (x <= 0 || x + 2 > H)
            continue;
        if (y <= 0 || y + 2 > W)
            continue;

        int ret = 0;
        for (int j = 0; j < 3; j++)
        {
            for (int k = 0; k < 3; k++)
            {
                ret += S.count({x + j, y + k});
            }
        }
        ans[ret]++;
        ans[0]--;
    }

    for (int i = 0; i < 10; i++)
    {
        cout << ans[i] << endl;
    }
}

