  rep(i, 0, n) {
    cin >> Y[i] >> X[i];
  }

  ll W = compress(n, X, w);
  ll H = compress(n, Y, h);

  map<PLL, int> mp;
  rep(i, 0, n) {
    mp[make_pair(Y[i], X[i])] = i;
  }

  vl ans(10, 0ll);
