    rep(j, 0, 9) {
      ll ox = xi + dx[j];
      ll oy = yi + dy[j];
      if (0ll <= ox && ox < W-2ll && 0ll <= oy && oy < H-2ll) {
        s.insert(make_pair(oy, ox));
      }
    }
  }

  for (PLL pl: s) {
    ll y = pl.first;
    ll x = pl.second;
    int tmp = 0;
    for (ll i = 0ll; i < 9ll; i++) {
      ll r = i / 3ll;
      ll c = i % 3ll;
      if (Find(mp, make_pair(y+r, x+c))) tmp++;
    }
    ans[tmp]++;
  };

  ans[0] = (h-2ll) * (w-2ll);
  rep(i, 1, 10) {
    ans[0] -= ans[i];
  }

  rep(i, 0, 10) {
    cout << ans[i] << endl;
  }

  return 0;
};

