int main(){
    int h, w, n; cin >> h >> w >> n;
    vector<pair <int, int>> black_point(n);
    for (int i=0; i<n; i++){
        cin >> black_point.at(i).first >> black_point.at(i).second;
    }
    //sort(black_point.begin(), black_point.end());
    vector<pair<int, int>> square_point(n*9);
    int p=0;
    for (int i=0; i<n; i++){//入力された黒いマスを含む９個の正方形の左上のマス(9n個)を登録
        for (int j=0; j<3; j++){
            for (int k=0; k<3; k++){
                if (black_point.at(i).first-j>0 && black_point.at(i).second-k>0 && black_point.at(i).first-j+2<=h && black_point.at(i).second-k+2<=w){//その正方形が範囲内に収まるのであれば
                    square_point.at(p).first=black_point.at(i).first-j;
                    square_point.at(p).second=black_point.at(i).second-k;
                    p++;
                }
            }
        }
    }
    //その正方形が出現する回数をカウント
    vector<int> ans(10, 0);
    sort(square_point.begin(), square_point.begin()+p);
    //cout << "p is " << p << endl; 
    /*for (int i=0; i<p; i++){
        cout << square_point.at(i).first << ", " << square_point.at(i).second << endl;
    }*/
    int temp_first=square_point.at(0).first, temp_second=square_point.at(0).second, count=1;
    for (int i=1; i<p; i++){
        if (temp_first==square_point.at(i).first && temp_second==square_point.at(i).second){//前と同じ座標ならば
            count++;
            if (i==p-1) ans.at(count)++;
        } else {//違うならば
            ans.at(count)++;
            temp_first=square_point.at(i).first;
            temp_second=square_point.at(i).second;
            count=1;
        }
    }
    int sum=0;
    for(int i=1; i<10; i++){//真っ白の正方形を計算　h*w　から黒が1~9枚の正方形の枚数(sum)を引く
        sum+=ans.at(i);
    }
    ans.at(0)=(h-2)*(w-2)-sum;
    for(int i=0; i<10; i++){//出力
        //cout << i << ": ";
        cout << ans.at(i) << endl;
    }
    return 0;
}

