long long h, w, n;
map<pair<ll, ll>, ll> mp;
map<pair<ll, ll>, ll> ch;
ll ans[10] = {0};

void solve();

int main() {
  cin >> h >> w >> n;
  for(ll i = 0; i < n; ++i) {
    ll x, y;
    cin >> x >> y;
    --x;
    --y;
    ++mp[make_pair(x, y)];
  }
  solve();
  for(int i = 0; i < 10; ++i) cout << ans[i] << endl;
  return 0;
}

void solve() {
  ll sum = 0, cnt = 0;
  ans[0] = (h - 2) * (w - 2);
  for(auto it = mp.begin(); it != mp.end(); ++it) {
    pair<ll, ll> now = it->first;
    for(ll i = now.fi - 2; i <= now.fi; ++i)
      for(ll j = now.se - 2; j <= now.se; ++j) {
        if(i < 0 || j < 0 || i + 2 >= h || j + 2 >= w)
          continue;
        if(ch[make_pair(i, j)] != 0) continue;
        cnt = 0;
        for(ll k = 0; k < 3; ++k)
          for(ll l = 0; l < 3; ++l)
            if(mp.find(make_pair(i + k, j + l)) != mp.end())
              ++cnt;
        ++ans[cnt];
        ++ch[make_pair(i, j)];
      }
  }
  for(int i = 1; i < 10; ++i) sum += ans[i];
  ans[0] -= sum;
}

