    a[n]--; b[n]--;
  }
  // create table_h
  size_table = DIVIDE_ROUNDUP(H, ROW_PER);
  for (int i = 0; i < size_table; i++)
    table_h.push_back(std::vector<std::pair<long, long>>());
  for (int n = 0; n < N; n++)
    table_h[a[n] / ROW_PER].push_back(std::pair<long, long>(a[n], b[n]));
  for (int i = 0; i < size_table; i++)
    std::sort(table_h[i].begin(), table_h[i].end());
  // count number of neighbours
  for (int n = 0; n < N; n++) {
    int a_n = a[n], b_n = b[n];
    // printf("n = %d, a_n = %d, b_n = %d\n", n, a_n, b_n);
    for (int di = -1; di <= 1; di++) {
      for (int dj = -1; dj <= 1; dj++) {
        int center_h = a_n + di, center_w = b_n + dj;
        if (center_h - 1 >= 0 && center_h + 1 < H &&
            center_w - 1 >= 0 && center_w + 1 < W) {
          // printf("center_h = %d, center_w = %d\n", center_h, center_w);
          int num_in_cell = 0;
          for (int i = center_h - 1; i <= center_h + 1; i++)
            for (int j = center_w - 1; j <= center_w + 1; j++)
              if (std::binary_search(table_h[i / ROW_PER].begin(),
                                     table_h[i / ROW_PER].end(),
                                     std::pair<long, long>(i, j)))
                num_in_cell++;
          ans[num_in_cell]++;
          // printf("num_in_cell = %d\n", num_in_cell);
        }
      }
    }
  }
  // remove duplicates and calculate 0
  ans[0] = (W - 2) * (H - 2);
  for (int k = 1; k < 10; k++) {
    ans[k] /= k;
    ans[0] -= ans[k];
  }
  // print answer
  for (int k = 0; k < 10; k++)
    printf("%ld\n", ans[k]);

  return 0;
}

