int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    ll H, W, N;
    cin >> H >> W >> N;

    set<pair<ll, ll>> coords;

    for (int i = 0; i < N; i++)
    {
        pair<ll, ll> aux;
        cin >> aux.second >> aux.first;
        coords.insert(aux);
    }

    vector<ll> count(10);
    count[0] = (H - 2) * (W - 2);

    int adderx[] = {-1, 0, 1, -1, 0, 1, -1, 0, 1};
    int addery[] = {-1, -1, -1, 0, 0, 0, 1, 1, 1};

    set<pair<ll, ll>> checked;

    for (auto coord : coords)
    {
        for (int c = 0; c < 9; c++)
        {
            ll x = coord.first + adderx[c];
            ll y = coord.second + addery[c];

            if (x < 2 || x > W - 1 || y < 2 || y > H - 1)
                continue;
            pair<ll, ll> aux(x, y);

            if (checked.find(aux) != checked.end())
                continue;
            checked.insert(aux);

            int surr = 0;

            for (int l = 0; l < 9; l++)
            {
                ll x2 = x + adderx[l];
                ll y2 = y + addery[l];

                if (x2 < 1 || x2 > W || y2 < 1 || y2 > H)
                    continue;

                pair<ll, ll> aux2(x2, y2);

                if (coords.find(aux2) != coords.end())
                {
                    surr++;
                }
            }
            count[surr]++;
        }
    }

    for (int i = 1; i < 10; i++)
    {
        count[0] -= count[i];
    }

    for (int i = 0; i < 10; i++)
    {
        cout << count[i] << "\n";
    }
}

