    ull H, W, N;
    cin >> H >> W >> N;


    vector<int> a_all(N), b_all(N);
    for (int i = 0; i < N; i++) {
        cin >> a_all[i] >> b_all[i];
    }

    map<pair<int, int>, int> pool;
    for (int i = 0; i < N; i++) {
        int a = a_all[i];
        int b = b_all[i];

        for (int y = a - 1; y <= a + 1; y++) {
            if (y <= 1 || y >= H) continue;
            for (int x = b - 1; x <= b + 1; x++) {
                if (x <= 1 || x >= W) continue;

                auto key = make_pair(y, x);
                auto iter = pool.find(key);
                if (iter != pool.end()) {
                    pool[key] += 1;
                } else {
                    pool[key] = 1;
                }
            }
        }
    }

    vector<ull> count(10, 0);
    for (const auto& item : pool) {
        count[item.second] += 1;
    }
    ull sum = 0;
    for (int i = 0; i < 10; i++) {
        sum += count[i];
    }
    count[0] = (H - 2) * (W - 2) - sum;
    for (int i = 0; i < 10; i++) {
        cout << count[i] << endl;
    }

    return 0;
}

