void solve(int H, int W, int N, vi a, vi b) {
  unordered_map<int, int> m;
  rep(i, N) {
    rep(h, a[i] - 1, a[i] + 2)rep(w, b[i] - 1, b[i] + 2) {
      if(h < 1 || w < 1 || h >= H - 1 || w >= W - 1) continue;
      m[h + w * H]++;
    }
  }
  vi ans(10);
  each(p, m)ans[p.second]++;
  ans[0] = (H - 2) * (W - 2);
  rep(i, 1, 10)ans[0] -= ans[i];
  each(x, ans)COUT(x);
}


