using namespace std;

typedef long long ll;
typedef pair<int,int> ii;

#define MAX 100010
int H,W,N,a[MAX],b[MAX];

bool isValid(int x,int y) { return 0 <= x && x < W && 0 <= y && y < H; }

set<ii> B;

int count(int x,int y) {
  int cnt = 0;
  REP(dy,-1,2) {
    REP(dx,-1,2) {
      int nx = x + dx;
      int ny = y + dy;
      if( !isValid(nx,ny) ) return -1;
      if( B.count(ii(nx,ny)) ) ++cnt;
    }
  }
  return cnt;
}

void compute() {
  set<ii> S;
  vector<ll> ans(10,0);
  rep(i,N) {
    REP(dy,-1,2) {
      REP(dx,-1,2) {
	int x = b[i] + dx;
	int y = a[i] + dy;
	if( !isValid(x,y) ) continue;
	if( S.count(ii(x,y)) ) continue;
	S.insert(ii(x,y));
	int cnt = count(x,y);
	if( cnt <= 0 ) continue;
	++ans[cnt];
      }
    }
  }
  long long sum = (ll)( H - 2 ) * (ll)( W - 2 );
  REP(i,1,10) sum -= ans[i];
  ans[0] = sum;
  rep(i,10) cout << ans[i] << endl;
}

int main() {
  cin >> H >> W >> N;
  rep(i,N) {
    cin >> a[i] >> b[i];
    --a[i], --b[i];
    B.insert(ii(b[i],a[i]));
  }
  compute();
  return 0;
}

