typedef long long Index;
typedef std::pair<Index, Index> Position;
typedef std::map<Position, Index> Counter;


constexpr int MAX_J = 9;
constexpr int SQUARE_SIZE = 3;


class Board {
public:
    Board (Index height, Index width) : height_(height), width_(width) {}
    void paintCell(Index r, Index c){
        for (auto k = 0; k < SQUARE_SIZE; k++)
        {
            for (auto l = 0; l < SQUARE_SIZE; l++)
            {
                auto sr = r - k;
                auto sc = c - l;
                if (insideBoard(sr, sc))
                {
                    counter_[std::make_pair(sr, sc)]++;
                }
            }
        }
    }
    std::vector<Index> summarize() {
        std::vector<Index> ans(MAX_J + 1);
        for (const auto& elem : counter_)
        {
            if (1 <= elem.second and elem.second <= MAX_J)
            {
                ans[elem.second]++;
            }
        }
        ans[0] = (height_ - 2) * (width_ - 2) - std::accumulate(ans.begin(), ans.end(), 0LL);
        return ans;
    }
private:
    Index height_;
    Index width_;
    Counter counter_;
    bool insideBoard(Index r, Index c) const {
        return 0 <= r and r < height_ - 2 and 0 <= c and c < width_ - 2;
    }
};


int main() {
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);
    Index h, w, n;
    std::cin >> h >> w >> n;
    Board board(h, w);
    for (auto i = 0; i < n; i++)
    {
        Index a, b;
        std::cin >> a >> b;
        a--;
        b--;
        board.paintCell(a, b);
    }
    auto ans = board.summarize();
    for (const auto& x : ans)
    {
        std::cout << x << std::endl;
    }
    return EXIT_SUCCESS;
}

