using namespace std;

ll inf=1e9+5;

map<ll,int> s;
vector<ll> pot;
ll h,w;
void goo(ll x)
{
    ll H,W;
    W=x%inf;
    x-=x%inf;
    H=x/inf;
    for(int i=H-2;i<=H;i++)
    {
        for(int j=W-2;j<=W;j++)
        {
            if(i>=1 && i<=h && j>=1 && j<=w)
            {
                ll res=(ll)i*inf+j;
                pot.push_back(res);
            }
        }
    }
}

int cnt[10];

void doo(ll x)
{
    ll H,W;
    W=x%inf;
    x-=x%inf;
    H=x/inf;
    int res=0;
    if(H>=1 && H+2<=h && W>=1 && W+2<=w)
    {
        for(int i=H;i<=H+2;i++)
        {
            for(int j=W;j<=W+2;j++)
            {
                ll akt=(ll)i*inf+j;
                res+=s[akt];
            }
        }
    }
    else return;
    cnt[res]++;
}

int main()
{
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cin>>h>>w;
    int n; cin>>n;
    vector<ll> a;
    for(int i=0;i<n;i++)
