        a.push_back((ll)x*inf+y);
        s[a[i]]=1;
    }
    for(int i=0;i<n;i++)
    {
        goo(a[i]);
    }
    sort(pot.begin(),pot.end());
    for(int i=0;i<pot.size();i++)
    {
        if(i==0 || pot[i]!=pot[i-1])
        {
            doo(pot[i]);
        }
    }
    ll cnn=0;
    for(int i=1;i<=9;i++)
    {
        cnn+=cnt[i];
    }
    cout<<(ll)(w-2)*(h-2)-cnn<<endl;
    for(int i=1;i<=9;i++) cout<<cnt[i]<<endl;
    return 0;
}

