//const ll dy[4]={0,1,0,-1};
const ll dx[9] = {0, 1, 1, 0, -1, -1, -1, 0, 1};
const ll dy[9] = {0, 0, 1, 1, 1, 0, -1, -1, -1};
//2次元配列の宣言
//vector<vector<ll>> field(h, vector<ll>(w));

int main()
{
    cout << fixed << setprecision(30);
    ll H, W, N;
    cin >> H >> W >> N;
    vector<ll> a(N), b(N);
    /*
    方針
    (x,y)が黒マスのとき、(x,y)を中心とする3*3の正方形の各マスについて
    そのマスがグリッドの端(正方形の中心となりえない)or探索済みならcontinue
    そのマスを中心とする3*3の正方形に含まれる黒マスの数をカウントしてcount[黒マスの数]++
    seen[そのマス]=true
    count[0]は、count[1]~count[9],H,Wから分かる
    */
    vector<ll> count(10);          //答え
    map<pair<ll, ll>, bool> exist; //そのマスが黒マスか
    map<pair<ll, ll>, bool> seen;  //そのマスを中心として探索済みか
    //(x,y)について、x<=1||x>=H||y<=1||y>=Wなら(x,y)はグリッドの端(または外)
    loop(i, N)
    {
        cin >> a[i] >> b[i];
        exist[make_pair(a[i], b[i])] = true;
    }
    loop(i, N)
    {
        ll x = a[i], y = b[i];
        loop(d, 9)
        {
            ll nx = x + dx[d], ny = y + dy[d];
            if (nx <= 1 || nx >= H || ny <= 1 || ny >= W)
                continue;
            if (seen[make_pair(nx, ny)])
                continue;
            //さらにこのマスを中心に探索
            ll c = 0;
            loop(dd, 9)
            {
                ll nnx = nx + dx[dd], nny = ny + dy[dd];
                if (exist[make_pair(nnx, nny)])
                    c++;
            }
            count[c]++;
            seen[make_pair(nx, ny)] = true;
        }
    }
    ll nowS = Sum(count);
    count[0] = (H - 2) * (W - 2) - nowS;
    loop(i, 10) putout(count[i]);
    return 0;
}

