using namespace std;
typedef pair<int,int> pp;
typedef long long lint;

int H,W,N;

map<pp,int> M;

void update(int x,int y){
    for(int i=-2;i<=0;i++){
        for(int j=-2;j<=0;j++){
            int tx = x+i, ty = y+j;
            if(tx > 0 && ty > 0 && tx <= H-2 && ty <= W-2){
                M[pp(tx,ty)]++;
            }
        }
    }
}

void solve(){
    lint tot = (H-2ll)*(W-2ll);
    lint ans[10] = {tot, 0};
    for(auto it:M){
        ans[it.second]++;
        ans[0]--;
    }
    for(int i=0;i<=9;i++){
        printf("%lld\n",ans[i]);
    }
}

int main(){
    scanf("%d%d%d",&H,&W,&N);
    int x,y;
    for(int i=0;i<N;i++){
        scanf("%d%d",&x,&y);
        update(x,y);
    }
    solve();
    return 0;
}

