int main() {
  int H, W, N;
  cin >> H >> W >> N;

  using P = pair<int, int>;
  auto valid = [&](auto i, auto j) {return 0 <= i && i < H-2 && 0 <= j && j < W-2;};
  auto next = [&](auto i, auto j) {
    vector<P> r;
    for(auto y: {i-2,i-1,i}) for(auto x: {j-2,j-1,j}) if(valid(y,x)) r.emplace_back(y,x);
    return r;
  };
  map<P, int> memo;
  for(auto i = 0; i < N; ++i) {
    int a, b;
    cin >> a >> b;
    --a; --b;
    for(auto p: next(a, b)) ++memo[p];
  }

  using LL = long long;
  vector<LL> sum(10);
  for(auto i: memo) ++sum[i.second];
  for(auto i: sum) sum[0] -= i;
  sum[0] += LL(H-2)*LL(W-2);
  for(auto i: sum) cout << i << endl;
}

