int main(int argc, char* argv[]) {
  ll h, w, n;
  cin >> h >> w >> n;
  vec<ll> a(n), b(n);
  map<ll_ll, bool> black, visited;
  for (int i = 0; i < n; i++) {
    scanf("%lld %lld", &a[i], &b[i]);
    a[i]--, b[i]--;
    black[make_pair(a[i], b[i])] = true;
  }

  vec<ll> ans(10);
  rep(i, 0, n) {
    ll_ll pivot{a[i], b[i]};
    rep(c_h, -2, 1) rep(c_w, -2, 1) {
      ll_ll corner{pivot.first + c_h, pivot.second + c_w};
      ll count = 0;

      if (visited[corner]) continue;

      if (corner.first < 0 || corner.second < 0) continue;
      if (corner.first > h - 3 || corner.second > w - 3) continue;
      // if (h == 4) cerr << corner.first << " " << corner.second << endl;
      visited[corner] = true;
      rep(offset_x, 0, 3) rep(offset_y, 0, 3) {
        ll_ll pos{corner.first + offset_x, corner.second + offset_y};
        if (black[pos]) count++;
      }

      ans[count]++;
    }
  }
  ans[0] = 0;
  ans[0] = (h - 2) * (w - 2) - accumulate(all(ans), 0LL);

  rep(i, 0, 10) put(ans[i]);
  return 0;
}

