#include "bits/stdc++.h"

using namespace std;

int H, W, N;

int numBlackAround(int i, int j, const set<pair<int, int>>& blacks) {
    if (0 < i && i < H - 1 && 0 < j && j < W - 1) {
        return blacks.count(make_pair(i - 1, j - 1))
            + blacks.count(make_pair(i - 1, j))
            + blacks.count(make_pair(i - 1, j + 1))
            + blacks.count(make_pair(i, j - 1))
            + blacks.count(make_pair(i, j))
            + blacks.count(make_pair(i, j + 1))
            + blacks.count(make_pair(i + 1, j - 1))
            + blacks.count(make_pair(i + 1, j))
            + blacks.count(make_pair(i + 1, j + 1));
    }
    else {
        return 0;
    }
}

void reg(int i, int j, const set<pair<int, int>>& blacks, map<pair<int, int>, int>& hasBlack) {
    if (0 < i && i < H - 1 && 0 < j && j < W - 1) {
        pair<int, int> p = make_pair(i, j);
        if (hasBlack.count(p) == 0) {
            hasBlack.insert(make_pair(p, numBlackAround(i, j, blacks)));
        }
    }
}

void Main() {
    cin >> H >> W >> N;
    set<pair<int, int>> blacks;
    for (int i = 0; i < N; ++i) {
        int a, b;
        cin >> a >> b;
        --a;
        --b;
        blacks.insert(make_pair(a, b));
    }

    map<pair<int, int>, int> hasBlack;
    for (auto p : blacks) {
        int i = p.first;
        int j = p.second;
        reg(i - 1, j - 1, blacks, hasBlack);
        reg(i - 1, j, blacks, hasBlack);
        reg(i - 1, j + 1, blacks, hasBlack);
        reg(i, j - 1, blacks, hasBlack);
        reg(i, j, blacks, hasBlack);
        reg(i, j + 1, blacks, hasBlack);
        reg(i + 1, j - 1, blacks, hasBlack);
        reg(i + 1, j, blacks, hasBlack);
        reg(i + 1, j + 1, blacks, hasBlack);
    }

    map<int, long long> ans;
    for (int i = 1; i < 10; ++i) {
        ans.insert(make_pair(i, 0LL));
    }
    for (auto e : hasBlack) {
        ++ans[e.second];
    }

    long long zero = ((long long)H - 2) * ((long long)W - 2);
    for (auto p : ans) {
        zero -= p.second;
    }
    cout << zero << endl;
    for (int i = 1; i < 10; ++i) {
        cout << ans[i] << endl;
    }
}

int main() {
    std::cout << std::fixed << std::setprecision(15);
    Main();
    return 0;
}

