typedef unsigned long long int ulli;

struct Point
{
    ulli a, b;
    Point(ulli a, ulli b) : a(a), b(b) {}
    bool operator<(const Point &p) const
    {
        return (b == p.b) ? a < p.a : b < p.b;
    }
    bool operator==(const Point &p) const
    {
        return a == p.a && b == p.b;
    }
};

std::ostream& operator<<(std::ostream &os, const Point &p)
{
    os << "(" << p.a << ", " << p.b << ")";
    return os;
}

template<typename T>
std::ostream& operator<<(std::ostream &os, const std::set<T> &s)
{
    const std::string delim = ", ";
    auto itr = s.begin();
    while(itr != s.end())
    {
        os << *itr;
        if(++itr != s.end()) os << delim;
    }
    return os;
}

template<typename T>
std::ostream& operator<<(std::ostream &os, const std::multiset<T> &s)
{
    const std::string delim = ", ";
    auto itr = s.begin();
    while(itr != s.end())
    {
        os << *itr;
        if(++itr != s.end()) os << delim;
    }
    return os;
}

struct Count
{
    Point p;
    ulli c;
    Count(Point p, ulli c = 1) : p(p), c(c) {}

    bool operator<(const Count &cnt) const
    {
        return p < cnt.p;
    }

    bool operator==(const Count &cnt) const
    {
        return p == cnt.p;
    }
};

std::ostream& operator<<(std::ostream &os, const Count &c)
{
    os << "[" << c.p << " : " << c.c << "]";
    return os;
}

