// n以下の素数列挙
vector<lnt> Primes(const lnt n) {
  if (n < 2) {
    return vector<lnt>(0);
  }

  vector<lnt> vcPri, vcTab(n - 1);
  for (lnt i = 2; i < n + 1; i++) {
    vcTab[i - 2] = i;
  }

  const lnt nRoot = sqrt(n);
  while (vcTab[0] <= nRoot) {
    vcPri.push_back(vcTab[0]);
    vcTab.erase(vcTab.begin());
    vector<lnt> vcTab_fil;
    copy_if(vcTab.begin(), vcTab.end(), back_inserter(vcTab_fil),
            [&vcPri](lnt x) { return x % vcPri.back() != 0; });
    vcTab = vcTab_fil;
    if (vcTab.empty()) {
      break;
    }
  }

  vcPri.reserve(vcPri.size() + vcTab.size());
  vcPri.insert(vcPri.end(), vcTab.begin(), vcTab.end());
  return vcPri;
}

const vector<lnt> vcPRIMES1e6 = Primes(1e6);

// 素因数分解:PrimeDecomp(n)
// 2番目の引数にはPrimes(k) (kは十分大 >= floor(sqrt(n))) を入れる
MAP<lnt, lnt> PrimeDecomp(const lnt n,
                          const vector<lnt> &vcPrimesRoot_n = vcPRIMES1e6) {
  if (n < 2) {
    return MAP<lnt, lnt>();
  }

  MAP<lnt, lnt> PrimeDecomp;

  lnt m = n;
  for (lnt p : vcPrimesRoot_n) {
    while (m % p == 0) {
      m /= p;
      if (PrimeDecomp.count(p)) {
        PrimeDecomp[p]++;
      } else {
        PrimeDecomp.emplace(p, 1);
      }
    }
  }
  if (m != 1) {
    PrimeDecomp.emplace(m, 1);
  }

  return PrimeDecomp;
}

// 約数列挙:Divisors(n)
// 2番目の引数にはPrimes(k) (kは十分大 >= floor(sqrt(n))) を入れる
vector<lnt> Divisors(const lnt n,
                     const vector<lnt> &vcPrimesRoot_n = vcPRIMES1e6) {
  vector<lnt> vcDiv(1, 1), vcTable;
  auto mpPD = PrimeDecomp(n, vcPrimesRoot_n);
  for (auto itrPD = mpPD.begin(); itrPD != mpPD.end(); itrPD++) {
    lnt nPri = itrPD->first, nMulti = itrPD->second;
    vcTable.resize(vcDiv.size() * (nMulti + 1));
    for (lnt i = 0; i < nMulti + 1; i++) {
      transform(vcDiv.begin(), vcDiv.end(),
                vcTable.begin() + (i * vcDiv.size()),
                [nPri, i](lnt x) { return x * pow(nPri, i); });
    }
    vcDiv = vcTable;
  }
  sort(vcDiv.begin(), vcDiv.end());
  return vcDiv;
}

// mod2乘
lnt inline SQ(const lnt n, const lnt mod = MOD) {
  return ((n % mod) * (n % mod)) % mod;
}

// mod冪乗
lnt POW(const lnt x, const lnt y, const lnt mod = MOD) {
  if (x >= 0 and y >= 0) {
    if (y == 0) {
      return 1 % mod;
    }
    if (y == 1) {
      return x % mod;
    }
    if (y % 2 == 0) {
      return SQ(POW(x, y / 2, mod), mod);
    }
    return SQ(POW(x, y / 2, mod), mod) * (x % mod) % mod;
  }
  cout << "Warning!" << endl;
  return 0;
}

// mod 2の冪
lnt inline BIT(const lnt i) {
  if (i >= 0) {
    return POW(2, i);
  }
  cout << "Warning!" << endl;
  return 0;
}

// long long まで許すSQ
lnt inline LSQ(const lnt n) { return n * n; }

// long long まで許すPOW
lnt LPOW(const lnt x, const lnt y) {
  if (x >= 0 and y >= 0) {
    if (y == 0) {
      return 1;
    }
    if (y == 1) {
      return x;
    }
    if (y % 2 == 0) {
      return LSQ(LPOW(x, y / 2));
    }
    return LSQ(LPOW(x, y / 2)) * x;
  }
  cout << "Warning!" << endl;
  return 0;
}

// long longまで許すBIT
lnt inline LBIT(const lnt i) {
  if (i >= 0) {
    return LPOW(2, i);
  }
  cout << "Warning!" << endl;
  return 0;
}

// n以下の階乗/mod階乗のリストを生成　
vector<lnt> vcFACT(const lnt n, const lnt mod = MOD) {
  if (n >= 0) {
    vector<lnt> vcFact = {1 % mod};
    lnt fact = 1 % mod;
    FOR(k, 1, n + 1) {
      fact = (fact * (k % mod)) % mod;
      vcFact.PB(fact);
    }
    return vcFact;
  }
  cout << "Warning!" << endl;
  return vector<lnt>(0);
}

// n以下のmod階乗の逆元のリストを生成(mod:素数を想定)
vector<lnt> vcINVFACT(const lnt n, const lnt mod = MOD) {
  vector<lnt> vcInvFact;
  lnt invfact = POW(vcFACT(n, mod).at(n), mod - 2, mod);
  vcInvFact.PB(invfact);
  INVFOR(k, 1, n + 1) {
    invfact = invfact * (k % mod) % mod;
    vcInvFact.PB(invfact);
  }
  reverse(ALL(vcInvFact));
  return vcInvFact;
}

const vector<lnt> vcMODFACT1e6 = vcFACT(1e6, MOD);
const vector<lnt> vcMODINVFACT1e6 = vcINVFACT(1e6, MOD);

// 階乗
// mod > 0．3番目の引数には
// vcFACT(m, mod)を入れる
// (m >= n:十分大)
lnt inline FACT(const lnt n, const lnt mod = MOD,
                const vector<lnt> &vcModFact = vcMODFACT1e6) {
  return vcModFact.at(n);
}

// 順列の数
// mod:素数を想定．4, 5番目の引数には
// vcFACT(m1, mod)，vcINVFACT(m2, mod)を入れる
// (m1 >= n, m2 >= n-k :十分大)
lnt PERM(const lnt n, const lnt k, const lnt mod = MOD,
         const vector<lnt> &vcModFact = vcMODFACT1e6,
         const vector<lnt> &vcModInvFact = vcMODINVFACT1e6) {
  if (k >= 0) {
    return vcModFact.at(n) * vcModInvFact.at(n - k) % mod;
  }
  cout << "Warning!" << endl;
  cout << "Note that 4th, 5th argument : vcFact(m1, mod), vcFact(m2, mod)."
       << endl;
  return 0;
}

//二項係数
// mod:素数なら，4, 5番目の引数には
// vcFACT(m1, mod)，vcINVFACT(m2, mod)を入れる
// (m1 >= n, m2 >= n-k, k :十分大)
lnt inline COMB(const lnt n, const lnt k, const lnt mod = MOD,
                const vector<lnt> &vcModFact = vcMODFACT1e6,
                const vector<lnt> &vcModInvFact = vcMODINVFACT1e6) {
  return PERM(n, k, mod, vcModFact, vcModInvFact) * vcModInvFact.at(k) % mod;
}

//重複組み合わせの数
// mod:素数なら，4, 5番目の引数には
// vcFACT(m1, mod)，vcINVFACT(m2,mod)を入れる
// (m1 >= n+k-1, m2 >= n-1, k :十分大)
lnt inline HCOMB(const lnt n, const lnt k, const lnt mod = MOD,
                 const vector<lnt> &vcModFact = vcMODFACT1e6,
                 const vector<lnt> &vcModInvFact = vcMODINVFACT1e6) {
  return COMB(n + k - 1, k, mod, vcModFact, vcModInvFact);
}

