    map<pair<int, int>, int> m, m2;
    int a[100001], b[100001];
    for(int i = 0; i < n; i++){
        cin >> a[i] >> b[i];
        m[make_pair(a[i], b[i])] = 1;
        m2[make_pair(a[i], b[i])] = i;
    }
    bool ischecked[100001][3][3];
    for(int i = 0; i < n; i++){
        for(int j = 0; j < 3; j++){
            for(int k = 0; k < 3; k++){
                ischecked[i][j][k] = false;
            }
        }
    }
    long long int ans[100001] = {};
    long long int sum = 0;
    for(int i = 0; i < n; i++){
        for(int j = 0; j < 3; j++){
            for(int k = 0; k < 3; k++){
                if(ischecked[i][j][k]) continue;
                // i番目の黒マスが3*3の正方形のうち(j, k)にあるとする(左上が(0, 0), 右下が(2, 2))
                long long int result = 0;
                bool isinfield = true;
                for(int p = a[i] - j; p < a[i] - j + 3; p++){
                    if(p <= 0 || p > h){
                        isinfield = false;
                        continue;
                    }
                    for(int q = b[i] - k; q < b[i] - k + 3; q++){
                        if(q <= 0 || q > w){
                            isinfield = false;
                            continue;
                        }
                        if(m.find(make_pair(p, q)) != m.end()){
                            result++;
                            int tmp = m2[make_pair(p, q)];
                            // cout << "checked->" << tmp << " " << p - a[i] + j << " " << q - b[i] + k << endl;
                            if(ischecked[tmp][p - a[i] + j][q - b[i] + k]) isinfield = false;
                            ischecked[tmp][p - a[i] + j][q - b[i] + k] = true;
                        }
                    }
                }

                if(isinfield){
                    ans[result]++;
                    sum++;
                    // cout << i << " " << j << " " << k << " " << result << endl;
                }
                // cout << endl;
            }
        }
    }
    cout << (long long int)(w - 2) * (h - 2) - sum << endl;
    for(int i = 1; i < 10; i++){
        cout << ans[i] << endl;
    }
    return 0;
}

