typedef long long ll;
typedef vector <int> vi;
typedef pair <int, int> pii;

ll A[11];
int H, W;

pii add(pii r, pii p) {
    return { r.first + p.first, r.second + p.second };
}

int coll(pii r, set <pii>& box) {
    int rx = 0;

    for(int x = -1; x < 2; ++x)
        for(int y = -1; y < 2; ++y)
            rx += box.find(add(r, {x, y})) != box.end();

    return rx;
}

bool lt(pii r, pii p) {
    return r.first < p.first && r.second < p.second;
}

void col(pii r, set <pii>& box) {
    for(int x = -1; x < 2; ++x)
        for(int y = -1; y < 2; ++y) {
            pii d = add(r, {x, y});
            if(lt({1, 1}, d) && lt(d, {H, W}))
                A[coll(d, box)] += 1;
        }

    return ;
}

int main() {
    int n; cin >> H >> W >> n;
    ll mx = (H - 2LL) * (W - 2LL);
    int u, v;
    set <pii> box;

    while(n--) {
        cin >> u >> v;
        box.emplace(u, v);
    }

    for(pii r : box)
        col(r, box);

    ll rx = 0;
    for(int i = 1; i < 11; ++i)
        rx += (A[i] /= i);
    cout << mx - rx;
    for(int i = 1; i < 10; ++i)
        cout << '\n' << A[i];

    return 0;
}

