void add(ll x, ll y){
	if(!ok(x, y)) return;
	vector<pll> vals;
	ll cnt = 0;
	for(ll i = 0; i < 3; ++i){
		for(ll j = 0; j < 3; ++j){
			if(!ok(x + i, y + j)) return;
			vals.pb({x + i, y + j});
			if(b[{x + i, y + j}]) ++cnt;
