/* Counter Lib */
template <class T>
class Counter {
 public:
  Counter() = default;
  template <class U>
  Counter(const U& container) {
    for (auto x : container) {
      counter_[x]++;
    }
  }
  auto val(const T& key) const { return counter_.find(key)->second; }
  auto add(const T& key) { counter_[key]++; }
  auto get() { return counter_; }
  auto get() const { return counter_; }
  auto hist() const {
    map<int, int> hist_counter;
    for (auto kv : counter_) {
      hist_counter[kv.second]++;
    }
    return hist_counter;
  }

 private:
  map<T, int> counter_;
};
/* /Counter Lib */

