bool find_negative_roop(V<P<P<int,int>,int>> a,V<int> b){
  V<int> d(b.sz,1),e;
  fo(i,3*b.sz){
    fo(j,a.sz){
      P<P<int,int>,int> c=a[j];
      if(b[c.ff]!=inf&&b[c.fs]>b[c.ff]+c.se){
        b[c.fs]=b[c.ff]+c.se;
        if(i>=b.sz-1&&d[c.ff]){
          d[c.ff]=0;
          e.pb(c.ff);
        }
        if(i>=b.sz-1&&d[c.fs]){
          d[c.fs]=0;
          e.pb(c.fs);
        }
      }
    }
  }
