    if(a-2>=0&&b-1>=0&&a+1<=H&&b+2<=W){
      A.push(P(a-2,b-1));
    }
    if(a-1>=0&&b-3>=0&&a+2<=H&&b<=W){
      A.push(P(a-1,b-3));
    }
    if(a-1>=0&&b-2>=0&&a+2<=H&&b+1<=W){
