inline bool in_board(int H, int W, int x, int y) {
  return 2 <= x && x <= H - 1 && 2 <= y && y <= W - 1;
}

typedef pair<int, int> P;

struct hash_pair {
  template <class T1, class T2> size_t operator()(const pair<T1, T2> &p) const {
    auto hash1 = hash<T1>{}(p.first);
    auto hash2 = hash<T2>{}(p.second);
    return hash1 ^ (hash2 << 15);
  }
};

const ll dx[] = {-1, 0, 1};
const ll dy[] = {-1, 0, 1};

void solve() {
  inl(H, W, N);
  unordered_map<P, int, hash_pair> map;
  map.reserve(N);

  ll ret[] = {0LL, 0LL, 0LL, 0LL, 0LL, 0LL, 0LL, 0LL, 0LL, 0LL};
  ret[0] = (H - 2) * (W - 2);

  rep(i, N) {
    ini(a, b);
    for (auto i : dx) {
      for (auto j : dy) {
        if (in_board(H, W, a + i, b + j)) {
          if (map.find({a + i, b + j}) == map.end())
            map[P({a + i, b + j})] = 0;
          auto tmp = ++map[P({a + i, b + j})];
          ret[tmp - 1]--;
          ret[tmp]++;
        }
      }
    }
  }

  rep(i, 10) { out(ret[i]); }
}

