ll dx[9] = {0ll, -1ll, -2ll, 0ll, -1ll, -2ll, 0ll, -1ll, -2ll};
ll dy[9] = {0ll, 0ll, 0ll, -1ll, -1ll, -1ll, -2ll, -2ll, -2ll};

int compress(int n, vl &X, ll w) {
  vector<ll> xs;
  rep(i, 0, n) {
    for (ll d = -1ll; d <= 1ll; d++) {
      ll tx = X[i]+d;
      if (1ll <= tx && tx <= w) xs.pb(tx);
    }
  }

  sort(All(xs));
  xs.erase(unique(All(xs)), xs.end());
  rep(i, 0, n) {
    X[i] = lbidx(xs, X[i]);
  }

  return xs.size();
};

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  ll h, w;
  cin >> h >> w;
  int n;
  cin >> n;

  vl X(n), Y(n);
  rep(i, 0, n) {
    cin >> Y[i] >> X[i];
  }

  ll W = compress(n, X, w);
  ll H = compress(n, Y, h);

  map<PLL, int> mp;
  rep(i, 0, n) {
    mp[make_pair(Y[i], X[i])] = i;
  }

  vl ans(10, 0ll);
  set<PLL> s;
  rep(i, 0, n) {
    ll xi = X[i];
    ll yi = Y[i];
    rep(j, 0, 9) {
      ll ox = xi + dx[j];
      ll oy = yi + dy[j];
      if (0ll <= ox && ox < W-2ll && 0ll <= oy && oy < H-2ll) {
        s.insert(make_pair(oy, ox));
      }
    }
  }

  for (PLL pl: s) {
    ll y = pl.first;
    ll x = pl.second;
    int tmp = 0;
    for (int i = 0ll; i < 9ll; i++) {
      ll r = i / 3ll;
      ll c = i % 3ll;
      if (Find(mp, make_pair(y+r, x+c))) tmp++;
    }
    ans[tmp]++;
  };

  ans[0] = (h-2ll) * (w-2ll);
  rep(i, 1, 10) {
    ans[0] -= ans[i];
  }

  rep(i, 0, 10) {
    cout << ans[i] << endl;
  }

  return 0;
};

