          ll r = k / 3ll;
          ll c = k % 3ll;
          ll x = ox + c;
          ll y = oy + r;
          if (Find(mp, make_pair(y, x))) { // 黒い点である
            if (counted[mp[make_pair(y, x)]][k]) { // その位置としてカウントされた黒い点である
              flag = false;
              break;
            }
          }
        }
        if (flag) {
          int tmp = 0;
            rep(k, 0, 9) {
            ll r = k / 3ll;
            ll c = k % 3ll;
            ll x = ox + c;
            ll y = oy + r;
            if (Find(mp, make_pair(y, x))) { // 黒い点である
              counted[mp[make_pair(y, x)]][k] = true;
              tmp++;
