struct phash{
    inline size_t operator()(const pair<int,int> & p) const{
        const auto h1 = hash<int>()(p.first);
        const auto h2 = hash<int>()(p.second);
        return h1 ^ (h2 << 1);
    }
};

void solve() {
  i64 H, W, N;
  cin >> H >> W >> N;
  using P = pair<int, int>;
  vector<P> ab;
  unordered_set<P, phash> s;
  rep(i, N) {
    int a, b;
    cin >> a >> b;
    a--, b--;
    ab.emplace_back(a, b);
    s.emplace(a, b);
  }
  unordered_set<P, phash> ans[10];
  rep(i, N) {
    int a, b;
    tie(a, b) = ab[i];
    for (int j = -2; j <= 2; j++) {
      for (int k = -2; k <= 2; k++) {
        int x = a + j, y = b + k;
        if (x < 0 || y < 0 || x >= H - 2 || y >= W - 2) continue;
        int cnt = 0;
        for (int l = 0; l <= 2; l++) {
          for (int m = 0; m <= 2; m++) {
            if (s.count(P(x + l, y + m))) cnt++;
          }
        }
        ans[cnt].insert(P(x, y));
      }
    }
  }
  i64 zero = (H - 2) * (W - 2);
  reps(i, 9) zero -= ans[i].size();
  cout << zero << '\n';
  reps(i, 9) cout << ans[i].size() << '\n';
}

