int main() {
	long H, W, N;

	scanf("%ld %ld %ld", &H, &W, &N);

	int table[H][W];
	long ans[10];

	long i, j, n;

	memset(table, 0, sizeof(table));
	memset(ans, 0, sizeof(ans));

	while (N--) {
	    scanf("%ld %ld", &i, &j);

	    i--; j--;

	    table[i][j] = 1;
	}

	long len = H - 1;
	long jLen = W - 1;
	long x, y, counter;

	for (i = 1; i < len; i++) {
	    for (j = 1; j < jLen; j++) {
	        counter = 0;

	        for (n = 0; n < DIR_NUM; n++) {
	            y = i + DIRECTION[n][0];
	            x = j + DIRECTION[n][1];

	            if (table[y][x] == 1) counter++;
	        }

	        ans[counter]++;
	    }
	}

	for (i = 0; i < 10; i++) printf("%ld\n", ans[i]);

	return 0;
}

