                ss += binary_search(tmp, x + i, y + j, y + j + 2);
                ss += binary_search(tmp, x + i + 1, y + j, y + j + 2);
                ss += binary_search(tmp, x + i + 2, y + j, y + j + 2);
                ans[ss]++;
            }
        }
    }

