typedef pair<int, int> ii;
typedef vector<ii> vii;

map<ii, int> MAP, visited;
vi ans(10);
ll h, w;

void visit(ii v) {
    if (visited[v] || v.F <= 0 || v.S <= 0 || v.F > h-2 || v.S > w-2) return;
    visited[v] = 1;
    int cnt = 0;
    for (int i = 0; i <= 2; ++i) {
        for (int j = 0; j <= 2; ++j) {
            cnt += MAP[ii(i + v.F, j + v.S)];
        }
    }
    if (cnt) {
        ans[0]++;
        ans[cnt]++; 
    }
}

void process(ii v) {
    for (int i = 0; i <= 2; ++i) {
        for (int j = 0; j <= 2; ++j) {
            visit(ii(v.F - i, v.S - j));
        }
    }
}

