void solve(){
    // 解答アルゴリズム
    ans[0] = (N-2)*(M-2);
    for (int i = 0; i < K; ++i)
    {
        int a = A[i], b = B[i];
        int counts[9] = {};
        debug("black[%d]: (%d, %d)\n", i, a, b);
        for (int aa = a - 2; aa <= a; ++aa)
        {
            for (int bb = b - 2; bb <= b; ++bb)
            {
                if(aa < 1 || bb < 1 || aa + 2 > N || bb + 2 > M) continue;

                int count = 0;
                for(int aaa = aa; aaa < aa + 3; ++aaa)
                    for(int bbb = bb; bbb < bb + 3; ++bbb)
                        if(blacks[p(aaa,bbb)]){
                            count++;
                        }

                counts[count]++;
            }
        }
        for (int c = 0; c < 9; ++c)
        {
            ans[c] -= counts[c];
            ans[c+1] += counts[c];
            debug("counts[%d] = %d\n", c, counts[c]);
        }
        blacks[p(a, b)] = true;
    }
}
