using ll = long long;
map<int, vector<int>> recorder;

int h, w, n;

bool inside(int row, int col) {
    return 0 <= row && row < h && 0 <= col && col < w;
}

ll ans[10];

bool find_black(int row, int col) {
    auto& vec = recorder[row];
    auto it = lower_bound(vec.begin(), vec.end(), col);
    return it != vec.end() && *it == col;
}

int main() {
    cin >> h >> w >> n;

    for (int i = 0; i < n; i++) {
        int a, b;
        cin >> a >> b;
        recorder[a - 1].push_back(b - 1);
    }

    for (auto it = recorder.begin(); it != recorder.end(); it++) {
        auto& cols = it->second;
        sort(cols.begin(), cols.end());
    }

    for (auto row_it = recorder.begin(); row_it != recorder.end(); row_it++) {
        int row = row_it->first, col;
        for (auto& elt : row_it->second) {
            col = elt;

            for (int dtop = -2; dtop <= 0; dtop++) {
                for (int dleft = -2; dleft <= 0; dleft++) {
                    int ntop = row + dtop,
                        nbottom = row + dtop + 2,
                        nleft = col + dleft,
                        nright = col + dleft + 2;
                    if (!inside(ntop, nleft) || !inside(nbottom, nright)) continue;

                    // 今見ている領域内で辞書順で自分より小さいものが存在したらそこに任せる
                    int num = 0;
                    bool exists = false;
                    for (int r = ntop; r <= nbottom; r++) {
                        for (int c = nleft; c <= nright; c++) {
                            if (find_black(r, c)) {
                                // 辞書順で小さいのなら
                                if (make_pair(r, c) < make_pair(row, col)) {
                                    exists = true;
                                }
                                num++;
                            }
                        }
                    }
                    if (exists) continue;
                    ans[num]++;
                }
            }
        }
    }

    ans[0] = (ll)(h - 2) * (ll)(w - 2);
    for (int i = 1; i < 10; i++) ans[0] -= ans[i];

    for (int i = 0; i < 10; i++) {
        cout << ans[i] << endl;
    }

    return 0;
}

