    HOGE:;
    }
  };

  for (auto &p : B) {
    int i = p.first;
    for (auto &q : p.second) {
      int j = q.first;
      count(i, j, ans);
    }
  }

  for (int i = 0; i < (int)10; ++i) if (i) ans[i] /= i;
  ans[0] = (H - 2LL) * (W - 2LL) - accumulate(ans.begin() + 1, ans.end(), 0LL);
  for (int i = 0; i < (int)10; ++i) cout << ans[i] << endl;

  return 0;
}

