int main() {

	SINT64 H;	cin >> H;
	SINT64 W;	cin >> W;

	SINT64 N;	cin >> N;
	map<Pll,SINT64> mp;

	rep(i,0,N) {
		SINT64 a,b;
		cin >> a >> b;
		rep(j,0,3) {
			rep(k,0,3) {
				SINT64 c = a-j;
				SINT64 d = b-k;
				if (c <= 0) continue;
				if (d <= 0) continue;
				Pll buf;
				buf.F = c;
				buf.S = d;
				mp[buf]++;
			}
		}
	}
	vector<SINT64> ans(10);
