		if (it->F.F >= H-1) continue;
		if (it->F.S >= W-1) continue;
		SINT64 buf = it->second;
		ans[buf]++;
	}
	SINT64 ct = 0;
	rep(i,0,10) {
		ct += ans[i];
	}
	ans[0] = (H-2)*(W-2)-ct;

	rep(i,0,10) {
		put(ans[i]);
	}
	return 0;
}


