void check(int x,int y,int xx,int yy){
	if(used.count(P{x,y}))return;
	used.emplace(x,y);
	int cnt=0;
	if(x>=0&&xx<=h&&y>=0&&yy<=w);
	else return;
	REP(i,x,xx){
		REP(j,y,yy){
			if(st.count(P{i,j}))++cnt;
		}
	}
	ans[cnt]++;
}
void solve(){
	int n;
	cin>>h>>w>>n;
	vector<P>p(n);
	rep(i,n){
		cin>>p[i].first>>p[i].second;
		p[i].first--;p[i].second--;
		st.emplace(p[i].first,p[i].second);
	}
