    rep(i, 9) ans[i] = 0;
    rep(i, n) judge(xs[i], ys[i]);

    answer = (h - 2) * (w - 2);
    rep(i, 9) answer -= ans[i];
    prl(answer);
    rep(i, 9) prl(ans[i]);

