            carry = (h[i]*w[j]+carry)/10;
        }
    }
    carry = 0;
    for (i=0; i<20; i++){
        tmp[i] = (bignum[i] + carry) % 10;
        carry = (bignum[i]+carry)/10;
    }
    carry = 0;
    tmp[0] = tmp[0] - nonzero;
    for (i=0; i<20; i++){
        bignum[i] = mod(tmp[i]+carry, 10);
