int main(){
    int m, n, i, j, H, W, N, hashnum,
        a[MAX_N], b[MAX_N];
    long long result[10];

    scanf("%d %d %d", &H, &W, &N);
    for (n=0; n<N; n++) scanf("%*c%d %d", &a[n], &b[n]);

    hashnum = (int)(N*9*1.5);

    struct blockmodel{
        int count, center[2];
    } *block;
    block = calloc(hashnum, sizeof(struct blockmodel));

    result[0] = (long long)(H-2)*(W-2);

    for (n=0; n<N; n++){
        for (i=-1; i<=1; i++){
            if (a[n]-1+i<1 || H-2<a[n]-1+i) continue;
