                m = ((long long)(a[n]+b[n]-2+i+j)*128) % hashnum;
                while (block[m].count != 0) {
                    if (block[m].center[0] == a[n]-1+i
                        && block[m].center[1] == b[n]-1+j) break;
                    m = (m+1) % hashnum;
                }
                block[m].center[0] = a[n]-1+i;
                block[m].center[1] = b[n]-1+j;
                block[m].count++;
            }
        }
    }

    for (m=0; m<hashnum; m++){
