	min = 0;
	max = n;
	while (max - min > 1)
	{
		mid = (max + min) / 2;
		if (a[c[mid]] > x)
			max = mid;
		else if (a[c[mid]] < x)
			min = mid;
		else if (b[c[mid]] > y)
			max = mid;
		else
			min = mid;
	}
	if (a[c[min]] == x && b[c[min]] == y)
		return 1;
	else
		return 0;
}
