#define MAX_N   100000

long long result[10];

struct Node {
    int val, x, y, key;
    struct Node *lch, *rch;
};
typedef struct Node node;

node *modify (node *p, int new_x, int new_y, int new_key){
    if(p == NULL){
        node *q = (node*)malloc(sizeof(node));
        q->val = 1;
        q->x = new_x; q->y = new_y;
        q->key = new_key;
        q->lch = q->rch = NULL;
        return q;
    }
    else if (p->key == new_key){
        p->val++;
        return p;
    }
    else {
        if (new_key < p->key) p->lch = modify(p->lch, new_x, new_y, new_key);
        else p->rch = modify(p->rch, new_x, new_y, new_key);
        return p;
    }
}

void answer(node *p){
    if (p != NULL){
        answer(p->lch);
        result[p->val]++;
        result[0]--;
        answer(p->rch);
    }
}

void release(node *p){
    if (p != NULL){
        release(p->lch);
        free(p);
        release(p->rch);
    }
}

void display(node *p){
    if (p != NULL){
        display(p->lch);
        printf("%d  (%d, %d)  %d\n", p->val, p->x, p->y, p->key);
        display(p->rch);
    }
}

