typedef struct{
    int a;
    int b;
}data;

//昇順
int asc(const void* a, const void* b){
    data p=*(data*)a;
    data q=*(data*)b;
    if(p.a!=q.a) return p.a-q.a;
    else return p.b-q.b;
}

int main(void){
