int main(){
    int m, n, i, j, H, W, N, hashnum=(int)(MAX_N*9*1.5),
        a[MAX_N], b[MAX_N], nonzero=0, result[10]={},
        bignum[20], tmp[20], carry=0, h[10], w[10], order;

