    for (i=0; i<10; i++){
        for (j=0; j<10; j++){
            bignum[i+j] += (h[i]*w[j]+carry) % 10;
            carry = (h[i]*w[j]+carry)/10;
        }
    }
    carry = 0;
    for (i=0; i<20; i++){
        tmp[i] = (bignum[i] + carry) % 10;
        carry = (bignum[i]+carry)/10;
    }
    carry = 0;
    tmp[0] = tmp[0] - nonzero;
    for (i=0; i<20; i++){
        bignum[i] = mod(tmp[i]+carry, 10);
        carry = (tmp[i]+carry-9)/10;
    }

    for (order=19; order>=1; order--){
        if (bignum[order] != 0) break;
    }

    for (i=order; i>=0; i--){
        printf("%d", bignum[i]);
    }
    printf("\n");

    for (i=1; i<10; i++){
        printf("%d\n", result[i]);
    }

    free(block);

    return 0;
}

