} squr_t;

int sort(const void *a, const void *b){
    if ( ((squr_t*)a)->x - ((squr_t*)b)->x >0 ) {
        return 1;
    }
    if ( ((squr_t*)a)->x - ((squr_t*)b)->x <0 ) {
        return -1;
    }
    if ( ((squr_t*)a)->x - ((squr_t*)b)->x ==0 ) {
        if ( ((squr_t*)a)->y - ((squr_t*)b)->y >=0 ) {
            return 1;
        }
        if ( ((squr_t*)a)->y - ((squr_t*)b)->y <0 ) {
            return -1;
        }
    }
    return 0;
}

