        for (int j=-1; j<2; j++){
            if(a+j>=1 && a+j<h-1){
                for (int k=-1; k<2; k++){
                    if (b+k>=1 && b+k<w-1){
                        s[count].x=a+j;
                        s[count].y=b+k;
                        count++;
                    }
                }
            }
        }
    }
