import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.*;

public class Main {

    private static int H;
    private static int W;
    private static int N;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        H = sc.nextInt();
        W = sc.nextInt();
        N = sc.nextInt();

        long[] ans = solve(sc);
        for (int i = 0; i < 10; i++) {
            System.out.println( ans[i] );
        }
    }

    private static long[] solve(FastScanner sc) {
        Map<Cord, Integer> counts = new HashMap<>();
        for (int i = 0; i < N; i++) {
            int a = sc.nextInt();
            int b = sc.nextInt();
            count(new Cord(b, a), counts);
        }

        long[] ans = new long[10];
        ans[0] = (long)(W-2) * (H-2);

        counts.forEach( (c, cnt) -> {
            ans[cnt]++;
            ans[0]--;
        });

        return ans;
    }

    private static void count(Cord target, Map<Cord, Integer> counts) {
        for (int x = target.x - 1; x <= target.x + 1 ; x++) {
            for (int y = target.y - 1; y <= target.y+ 1 ; y++) {
                if( x - 1 < 1 || x + 1 > W || y - 1 < 1 || y + 1 > H) continue;

                Cord c = new Cord(x, y);

                if( counts.containsKey(c) ) {
                    int cnt = counts.get(c);
                    counts.put(c, cnt+1);
                } else {
                    counts.put(c, 1);
                }
            }
        }
    }

    private static class Cord {

        private final int x;
        private final int y;

        public Cord(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Cord cord = (Cord) o;
            return x == cord.x &&
                    y == cord.y;
        }

        @Override
        public int hashCode() {
            return Objects.hash(x, y);
        }

        public String toString() {
            return "(" +x + "," + y + ")";
        }
    }

    static class FastScanner {

        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        public String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }

            return tokenizer.nextToken("\n");
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

/**
 * https://abc045.contest.atcoder.jp/tasks/arc061_b
 */
public class Main {

	static Map<String,Point> map = new HashMap<>();
	static long H;
	static long W;
	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);
		H = Long.parseLong(sc.next());
		W = Long.parseLong(sc.next());
		int N = Integer.parseInt(sc.next());
		for(int i=0; i<N; i++){
			Point p = new Point(Integer.parseInt(sc.next()), Integer.parseInt(sc.next()));
			map.put(getKey(p.x,p.y), p);
		}
		sc.close();

		long[] ans = new long[10];
		for(Point p:map.values()){
			for(int x=0; x<=2; x++){
				for(int y=0; y<=2; y++){
					int count = count(p.x-x,p.y-y);
					if(count>0){
						ans[count]++;
					}
				}
			}
		}
		long sum = 0;
		for(int i=1; i<=9; i++){
			ans[i] = ans[i]/i;
			sum+=ans[i];
		}
		ans[0] = (H-2)*(W-2)-sum;
		for(long a:ans){
			System.out.println(a);
		}
	}

	static int count(int x, int y){
		int count = 0;
		if( x<=0 || y<=0 || x>W-2 || y>H-2 ) return -1;
		for(int i=0; i<=2; i++){
			for(int j=0; j<=2; j++){
				if(map.containsKey(getKey(x+i,y+j))){
					count++;
				}
			}
		}
		return count;
	}

	static String getKey(int x, int y){
		return x+"."+y;
	}

	static class Point{
		int x;
		int y;
		Point(int y, int x){
			this.x = x;
			this.y = y;
		}
	}

}

