		return OFFSET * x + y;
	}
	// 「10 の 6 乗　程度の int ２つを　long に変換する」の戻し
	int[] divideKey(long key) {
		int[] ans = new int[2];
		ans[0] = (int)(key / OFFSET);
		ans[1] = (int)(key - OFFSET * ans[0]);
		return ans;
	}

