		n = Integer.parseInt(arg[2]);
		int[] xi = new int[n];
		int[] yi = new int[n];
		for (int i = 0; i < n; i++) {
			arg = br.readLine().split(" ");
			yi[i] = Integer.parseInt(arg[0]) - 1;
			xi[i] = Integer.parseInt(arg[1]) - 1;
