class Solver {
	long[] solve(int[] xi, int[] yi, int w, int h) {
		Map<String, Integer> m = new HashMap<String, Integer>();
		for (int i = 0; i < xi.length; i++) {
			for (int k = 0; k <= 2; k++) {
				for (int kk = 0; kk <= 2; kk++) {

					if (xi[i] - k < 0 || yi[i] - kk < 0 || xi[i] - k > w - 2 || yi[i] - kk > h - 2)
						continue;
					String p = (xi[i] - k) + ":" + (yi[i] - kk);
					if (m.containsKey(p)) {
						m.replace(p, m.get(p) + 1);
					} else {
						m.put(p, 1);
					}
				}
			}

		}
		long[] ans = new long[10];
		ArrayList<Integer> vals = new ArrayList<Integer>(m.values());
		long sum = 0L;
		for (int i = 0; i < vals.size(); i++) {
			ans[vals.get(i)]++;
		}
		for (int i = 1; i < ans.length; i++) {
			sum += ans[i];
		}
		if (xi.length <= 0)
			ans[0] = (long) (w - 1) * (h - 1);
		else
			ans[0] = ((h - 1) * (w - 1) - sum) > 0 ? (h - 1) * (w - 1) - sum : 0;
		return ans;
	}
}

