			sb.append(arr[i]).append("\n");
		}
		System.out.print(sb);
	}

	static void set(int y, int x) {
		if (y < 1 || x < 1 || y >= h - 1 || x >= w - 1) {
			return;
		}
		Point p = new Point(x, y);
		Integer v = map.get(p);
		int val;
