public class Main {
  private static boolean debug = false;
  private static boolean elapsed = false;

  private static PrintWriter _err = new PrintWriter(System.err);

  private static class Point {
    int a;
    int b;
    public Point(int a, int b) {
      this.a = a;
      this.b = b;
    }
    public int hashCode() {
      int hashCode = 17;
      hashCode = hashCode * 31 + a;
      hashCode = hashCode * 31 + b;
      return hashCode;
    }
    public boolean equals(Object o) {
      if (o instanceof Point) {
        Point that = (Point)o;
        return this.a == that.a && this.b == that.b;
      }
      return false;
    }
    public String toString() {
      return "(" + a + ", " + b + ")";
    }
  }
  private static class Square3x3 {
    int a;
    int b;
    int cnt;
    public Square3x3(int a, int b) {
      this.a = a;
      this.b = b;
    }
    public boolean contains(Point that) {
      return (this.a - 1 <= that.a && that.a <= this.a + 1 && this.b - 1 <= that.b && that.b <= this.b + 1);
    }
    public int hashCode() {
      int hashCode = 17;
      hashCode = hashCode * 31 + a;
      hashCode = hashCode * 31 + b;
      return hashCode;
    }
    public boolean equals(Object o) {
      if (o instanceof Square3x3) {
        Square3x3 that = (Square3x3)o;
        return this.a == that.a && this.b == that.b;
      }
      return false;
    }
    public String toString() {
      return String.valueOf("(" + a + ", " + b + ", " + cnt + ")");
    }
  }
  private void solve(Scanner sc, PrintWriter out) {
    long H = sc.nextInt();
    long W = sc.nextInt();
    int N = sc.nextInt();

    int M = 10; // 0 <= j <= 9

    long[] count = new long[M];

    count[0] = (H - 2) * (W - 2);

    Map<Point, Square3x3> map = new HashMap<>();
    for (int i = 0; i < N; ++i) {
      int a = sc.nextInt();
      int b = sc.nextInt();

      Point p = new Point(a, b);
      for (int x = p.a - 1; x <= p.a + 1; ++x) {
        if (x < 2 || x > H - 1) {
          continue;
        }
        for (int y = p.b - 1; y <= p.b + 1; ++y) {
          if (y < 2 || y > W - 1) {
            continue;
          }
          Point q = new Point(x, y);
          Square3x3 sq = map.get(q);
          if (sq == null) {
            sq = new Square3x3(x, y);
            map.put(q, sq);
          }
          ++sq.cnt;
        }
      }
    }

    for (Square3x3 sq : map.values()) {
      --count[0];
      ++count[sq.cnt];
    }

    for (int i = 0; i < M; ++i) {
      out.println(count[i]);
    }
  }
  private long C(long n, long r) {
    long res = 1;
    for (long i = n; i > n - r; --i) {
      res *= i;
    }
    for (long i = r; i > 1; --i) {
      res /= i;
    }
    return res;
  }
  private long P(long n, long r) {
    long res = 1;
    for (long i = n; i > n - r; --i) {
      res *= i;
    }
    return res;
  }
  /*
   * 10^10 > Integer.MAX_VALUE = 2147483647 > 10^9
   * 10^19 > Long.MAX_VALUE = 9223372036854775807L > 10^18
   */
  public static void main(String[] args) {
    long S = System.currentTimeMillis();

    Scanner sc = new Scanner(System.in);
    PrintWriter out = new PrintWriter(System.out);
    new Main().solve(sc, out);
    out.flush();

    long G = System.currentTimeMillis();
    if (elapsed) {
      _err.println((G - S) + "ms");
    }
    _err.flush();
  }
}

import java.io.*;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.StringTokenizer;

public class Main {

    static class Task {

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int rowCnt = in.nextInt();
            int colCnt = in.nextInt();
            int n = in.nextInt();
            Map<Long, Integer> countMap = new HashMap<>();
            while ((n--) > 0) {
                int row = in.nextInt() - 1;
                int col = in.nextInt() - 1;
                // (row, col)图成黑色
                // 以当前方块为中心，让周围包含当前黑方块的9个3x3正方形的黑色方块数+1
                for (int i = Math.max(0, row - 2); i <= row; i++) {
                    if (i >= rowCnt - 2) {
                        break;
                    }

                    for (int j = Math.max(0, col - 2); j <= col; j++) {
                        // （i， j）是3x3方阵的左上角坐标
                        if (j >= colCnt - 2) {
                            continue;
                        }

                        long key = i * colCnt + j;
                        countMap.put(key, countMap.getOrDefault(key, 0) + 1);
                    }
                }
            }

            long[] countArr = new long[10];
            for (Long key : countMap.keySet()) {
                countArr[countMap.get(key)]++;
            }

            long zeroCount = (rowCnt - 2L) * (colCnt - 2) - countMap.keySet().size();
            out.println(zeroCount);
            for (int i = 1; i <= 9; i++) {
                out.println(countArr[i]);
            }
        }
    }

    private static void sort(double[] arr) {
        Double[] objArr = Arrays.stream(arr).boxed().toArray(Double[]::new);
        Arrays.sort(objArr);
        for (int i = 0; i < arr.length; i++) {
            arr[i] = objArr[i];
        }
    }

    private static void sort(int[] arr) {
        Integer[] objArr = Arrays.stream(arr).boxed().toArray(Integer[]::new);
        Arrays.sort(objArr);
        for (int i = 0; i < arr.length; i++) {
            arr[i] = objArr[i];
        }
    }

    private static void sort(long[] arr) {
        Long[] objArr = Arrays.stream(arr).boxed().toArray(Long[]::new);
        Arrays.sort(objArr);
        for (int i = 0; i < arr.length; i++) {
            arr[i] = objArr[i];
        }
    }

    private static void solve() {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        Task task = new Task();
        task.solve(1, in, out);
        out.close();
    }

    public static void main(String[] args) {
        new Thread(null, () -> solve(), "1", 1 << 26).start();
    }

    static class InputReader {

        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

    }

