		int N = ni();
		int a, b;
		for (int i = 0; i < N; i++) {
			a = ni() - 1;
			b = ni() - 1;
			for (int j = 0; j < 3; j++) {
				for (int j2 = 0; j2 < 3; j2++) {
					if(a < j || b < j2)		continue;
					map.merge(new PPKEY(a-j, b-j2), 1, Integer::sum);
				}
			}
		}
		int[] ans = new int[9];
