		for(PPKEY pp : map.keySet()) {
			if(pp.key >= H-2 || pp.val >= W-2)	continue;
			cnt = map.get(pp);
			ans[cnt-1]++;
			total++;
		}
		long max = ((long)H-2)*(W-2);
		out.println(max - total);
		for (int i = 0; i < 9; i++) {
			out.println(ans[i]);
		}
