        a.add(1);
        a.add(H-2);
        b.add(1);
        b.add(W-2);
        if(H>=4){
            a.add(2);
            a.add(H-3);
        }
        if(W>=4){
            b.add(2);
            b.add(W-3);
        }

        int[][] Block = new int[N][2];
        for(int i=0;i<N;i++){
            int x = sc.nextInt();
            int y = sc.nextInt();
            Block[i][0] = x;
            Block[i][1] = y;
            if(x>=3&&x<=H-2){
                for(int j=x-2;j<=x;j++){
                    a.add(j);
                }
            }
            if(y>=3&&y<=W-2){
                for(int j=y-2;j<=y;j++){
                    b.add(j);
                }
            }
        }
        Set<Integer> set1 = new HashSet<>(a);
        Set<Integer> set2 = new HashSet<>(b);
