		BufferedReader reader;
		private StringTokenizer st;

		public FastScanner() {
			st = null;
			reader = new BufferedReader(new InputStreamReader(System.in));
		}

		public String next() throws IOException {
			if (st == null || !st.hasMoreElements()) {
				st = new StringTokenizer(reader.readLine());
			}
			return st.nextToken();
		}

		public String nextLine() throws IOException {
			st = null;
			String readLine = null;
			readLine = reader.readLine();
			return readLine;
		}

		public int nextInt() throws NumberFormatException, IOException {
			return Integer.parseInt(next());
		}

		public long nextLong() throws NumberFormatException, IOException {
			return Long.parseLong(next());
		}

		public int[] nextIntArr(int n) throws NumberFormatException, IOException {
			int[] retArr = new int[n];
			for (int i = 0; i < n; i++) {
				retArr[i] = nextInt();
			}
			return retArr;
		}

		public long[] nextLongArr(int n) throws NumberFormatException, IOException {
			long[] retArr = new long[n];
			for (int i = 0; i < n; i++) {
				retArr[i] = nextLong();
			}
			return retArr;
		}

		public void close() throws IOException {
			reader.close();
		}
	}


}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.NoSuchElementException;
import java.util.Set;
import java.util.TreeSet;

public class Main {
	int H,W,N;
	int[] a,b;
	Set<P> color,point;
	long[] cnt;

	private class P implements Comparable<P>{
		int x,y;
		public P(int y,int x){
			this.x = x;
			this.y = y;
		}

		public int compareTo(P p){
			if(this.x == p.x && this.y == p.y)return 0;

			if(this.y < p.y)return -1;
			if(this.y > p.y)return 1;

			if(this.x < p.x)return -1;
			else return 1;
		}
	}

	public void solve() {
		H = nextInt();
		W = nextInt();
		N = nextInt();

		color = new TreeSet<P>();
		point = new TreeSet<P>();

		a = new int[N];
		b = new int[N];
		cnt = new long[10];
		cnt[0] = (long)(H - 2)* (W - 2);
		for(int k = 0;k < N;k++){
			a[k] = nextInt() - 1;
			b[k] = nextInt() - 1;

			color.add(new P(a[k],b[k]));

			for (int i = -2; i <= 0; i++) {
				for (int j = -2; j <= 0; j++) {
					if (a[k] + i >= 0 && b[k] + j >= 0 && a[k] + i + 3 <= H && b[k] + j + 3 <= W) {
						point.add(new P(a[k] + i, b[k] + j));
					}
				}
			}
		}

		for(P p : point){
			int c = 0;
			for(int i = 0;i < 3;i++){
				for(int j = 0;j < 3;j++){
					if(color.contains(new P(p.y + i,p.x + j))){
						c++;
					}
				}
			}
			cnt[c]++;
		}

		for(int i = 1;i <= 9;i++){
			cnt[0] -= cnt[i];
		}

		for(int i = 0;i < 10;i++){
			out.println(cnt[i]);
		}

	}

	public static void main(String[] args) {
		out.flush();
		new Main().solve();
		out.close();
	}

	/* Input */
	private static final InputStream in = System.in;
	private static final PrintWriter out = new PrintWriter(System.out);
	private final byte[] buffer = new byte[2048];
	private int p = 0;
	private int buflen = 0;

	private boolean hasNextByte() {
		if (p < buflen)
			return true;
		p = 0;
		try {
			buflen = in.read(buffer);
		} catch (IOException e) {
			e.printStackTrace();
		}
		if (buflen <= 0)
			return false;
		return true;
	}

	public boolean hasNext() {
		while (hasNextByte() && !isPrint(buffer[p])) {
			p++;
		}
		return hasNextByte();
	}

	private boolean isPrint(int ch) {
		if (ch >= '!' && ch <= '~')
			return true;
		return false;
	}

	private int nextByte() {
		if (!hasNextByte())
			return -1;
		return buffer[p++];
	}

	public String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = -1;
		while (isPrint((b = nextByte()))) {
			sb.appendCodePoint(b);
		}
		return sb.toString();
	}

	public int nextInt() {
		return Integer.parseInt(next());
	}

	public long nextLong() {
		return Long.parseLong(next());
	}

	public double nextDouble() {
		return Double.parseDouble(next());
	}
}

import java.util.Arrays;
import java.util.HashMap;
import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int h = sc.nextInt();
    int w = sc.nextInt();
    int n = sc.nextInt();
    int[] arrA = new int[n];
    int[] arrB = new int[n];
    for (int i = 0; i < n; i++) {
      arrA[i] = sc.nextInt();
      arrB[i] = sc.nextInt();
    }
    sc.close();

    HashMap<String, Integer> result = new HashMap<>();
    for (int i = 0; i < n; i++) {
      int a = arrA[i];
      int b = arrB[i];
      putBlack(result, a, b, h, w);
    }
    long[] count = new long[10];
    Arrays.fill(count, 0);
    count[0] = (long) (h - 2) * (long) (w - 2);
    for (int val : result.values()) {
      count[val] += 1;
      count[0] -= 1;
    }
    for (int i = 0; i <= 9; i++) {
      System.out.println(count[i]);
    }
  }

  private static void putBlack(HashMap<String, Integer> result, int a, int b, int h, int w) {
    for (int x = a - 2; x <= a; x++) {
      if (x < 1 || x > h - 2) {
        continue;
      }
      for (int y = b - 2; y <= b; y++) {
        if (y < 1 || y > w - 2) {
          continue;
        }
        String point = x + " " + y;
        if (!result.containsKey(point)) {
          result.put(point, Integer.valueOf(1));
        } else {
          int count = result.get(point);
          result.put(point, count + 1);
        }
      }
    }
  }
}

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.Scanner;

/**
 * 解説通り実装したソースコード
 */
public class Main {

	public static void main(String[] args) {
		try (Scanner scanner = new Scanner(System.in)) {
			int h = scanner.nextInt(), w = scanner.nextInt(), n = scanner.nextInt();
			Map<Dimesion, Integer> map = new HashMap<>();
			for (int i = 0; i < n; i++) {
				int a = scanner.nextInt(), b = scanner.nextInt();
				for (int j = 0; j <= 2; j++) {
					if ((a - j > 0) && (a - j <= h - 2)) {
						for (int k = 0; k <= 2; k++) {
							if ((b - k > 0) && (b - k <= w - 2)) {
								Dimesion key = new Dimesion(a - j, b - k);
								map.put(key, map.getOrDefault(key, 0) + 1);
							}
						}
					}
				}
			}
			long[] results = new long[10];
			map.values().forEach(value -> results[value]++);
			results[0] = (h - 2L) * (w - 2L) - map.size();
			Arrays.stream(results).forEach(System.out::println);
		}
	}

	/**
	 * Mapのキーとなるクラス
	 */
	private static class Dimesion {
		int x;
		int y;

		Dimesion(int x, int y) {
			super();
			this.x = x;
			this.y = y;
		}

		@Override
		public int hashCode() {
			return Objects.hash(x, y);
		}

		@Override
		public boolean equals(Object obj) {
			if (obj instanceof Dimesion) {
				Dimesion dimesion = (Dimesion) obj;
				return (x == dimesion.x) && (y == dimesion.y);
			}
			return false;
		}
	}
}

