		long h=sc.nextInt();
		long w=sc.nextInt();
		int n=sc.nextInt();
		HashSet<Long> hs1=new HashSet<>();
		HashSet<Long> hs2=new HashSet<>();
		for(int i=0;i<n;i++){
			long a=sc.nextInt()-1;
			long b=sc.nextInt()-1;
			hs1.add(a*w+b);
		}
