	static int[] mw9 = { -1, 0, 1, -1, 1, -1, 0, 1, 0 };

	static class TaskX {

		public void solve(int testNumber, InputReader in, PrintWriter out) {

			long h = in.nextLong(), w = in.nextLong();
			int n = in.nextInt();
			int[] a = new int[n];
			int[] b = new int[n];

			for (int i = 0; i < n; i++) {
