public class Main {

	public static void main(String[] args) throws IOException {
		Scanner sc = new Scanner(System.in);
		int H = sc.nextInt();
		int W = sc.nextInt();
		int N = sc.nextInt();
		Set<Long> fills = new HashSet<>();
		for (int i = 0; i < N; i++) {
			long y = sc.nextLong() - 1;
			long x = sc.nextLong() - 1;
			fills.add(y << 32 | x);
		}

		Set<Long> boards = new HashSet<>();
		for (Long fill : fills) {
			for (int y = -2; y <= 0; y++) {
				for (int x = -2; x <= 0; x++) {
					long yy = (fill >>> 32) + y;
					long xx = (fill & 0xFFFF) + x;
					if ((yy >= 0 && xx >= 0) && (yy < H - 2 && xx < W - 2)) {
						boards.add(yy << 32 | xx);
					}
				}
			}
		}

		long[] group = new long[10];
		for (Long board : boards) {
			int count = 0;
			for (long y = 0; y <= 2; y++) {
				for (long x = 0; x <= 2; x++) {
					if (fills.contains(board + (y << 32) + x)) {
						count++;
					}
				}
			}
			group[count]++;
		}

		long zero = ((long) (H - 2) * (W - 2)) - LongStream.of(group).sum();
		System.out.println(zero);
		for (int i = 1; i < group.length; i++) {
			System.out.println(group[i]);
		}
	}

	private static class Box {
		public int y;
		public int x;

		public Box(int y, int x) {
			super();
			this.y = y;
			this.x = x;
		}

		public int getY() {
			return y;
		}

		public int getX() {
			return x;
		}

		@Override
		public int hashCode() {
			final int prime = 31;
			int result = 1;
			result = prime * result + x;
			result = prime * result + y;
			return result;
		}

		@Override
		public boolean equals(Object obj) {
			if (this == obj)
				return true;
			if (obj == null)
				return false;
			if (getClass() != obj.getClass())
				return false;
			Box other = (Box) obj;
			if (x != other.x)
				return false;
			if (y != other.y)
				return false;
			return true;
		}

		@Override
		public String toString() {
			return "Box [y=" + y + ", x=" + x + "]";
		}
	}

