class Info{
  int a = 0;
  int b = 0;
  int black = 1;
  boolean isExist = false;

  public Info(int a_in, int b_in, int H, int W){
    a = a_in;
    b = b_in;
    if((2<=a && a<=H-1) && (2<=b && b<=W-1)){
      isExist = true;
    }
  }

  public boolean isEqual(Info info){
    if(a==info.getA() && b==info.getB()){
      return true;
    }else{
      return false;
    }
  }

  public int getA(){
    return a;
  }

  public int getB(){
    return b;
  }

  public int getBlack(){
    return black;
  }

  public boolean isExist(){
    return isExist;
  }

  public void addBlack(){
    black ++;
  }
}

