    static void Solve()
    {
        var H = sc.ReadInt();
        var W = sc.ReadInt();
        var N = sc.ReadInt();
        var Hs = new int[N];
        var Ws = new int[N];
        var cxy = new Compress2D();
        for (int i = 0; i < N; i++)
        {
            var a = sc.ReadInt();
            var b = sc.ReadInt();
            Hs[i] = a;
            Ws[i] = b;
            for (int d = -2; d < 3; d++)
            {
                if (1 <= Hs[i] + d && Hs[i] + d <= H && 
                    1 <= Ws[i] + d && Ws[i] + d <= W)
                    cxy.Add(Hs[i] + d, Ws[i] + d);
            }
        }
        cxy.Build();
        var countedFlag = new bool[cxy.MaxX - 2, cxy.MaxY - 2];
        var blacksFlag = new bool[cxy.MaxX - 2, cxy.MaxY - 2];
        for (int i = 0; i < N; i++)
        {
            var t = cxy.Get(Hs[i], Ws[i]);
            var h = t.Item1;
            var w = t.Item2;
            blacksFlag[h, w] = true;
        }
        var ans = new long[10];
        for (int i = 0; i < N; i++)
        {
            var t = cxy.Get(Hs[i], Ws[i]);
            var h = t.Item1;
            var w = t.Item2;
            var dhw = new int[] { -2, -1, 0 };
            foreach (var dh in dhw)
            {
                foreach (var dw in dhw)
                {
                    var nh = h + dh;
                    var nw = w + dw;
                    if (0 <= nh && nh < cxy.MaxX - 2 && 0 <= nw && nw < cxy.MaxY - 2)
                    {
                        if (countedFlag[nh, nw]) continue;
                        var count = 0;
                        for (int j = 0; j < 3; j++)
                        {
                            for (int k = 0; k < 3; k++)
                            {
                                var nowH = nh + j;
                                var nowW = nw + k;
                                if (blacksFlag[nowH, nowW]) count++;
                            }
                        }
                        countedFlag[nh, nw] = true;
                        ans[count]++;
                    }
                }
            }
        }
        var tot = (long)(H - 2) * (W - 2);
        ans[0] = tot - ans.Sum();
        foreach (var item in ans)
        {
            Console.WriteLine(item);
        }
    }
    class Compress2D
    {
        public Compress<int> CX = new Compress<int>();
        public Compress<int> CY = new Compress<int>();
        public void Add(int x, int y) { CX.Add(x); CY.Add(y); }
        public void Build()
        {
            CX.Build(); CY.Build();
        }
        public Tuple<int, int> Get(int x, int y)
        {
            return Tuple.Create(CX.Get(x), CY.Get(y));
        }
        public Tuple<int, int> this[int i, int j]
        {
            get { return Tuple.Create(this.CX[i], this.CY[j]); }
        }
        public int MaxX { get { return this.CX.Compressed.Length; } }
        public int MaxY { get { return this.CY.Compressed.Length; } }
    }
    class Compress<T> where T : IComparable<T>
    {
        public List<T> A = new List<T>();
        public T[] Compressed;
        public void Add(T x) { this.A.Add(x); }
        public void Add(IEnumerable<T> x) { this.A.AddRange(x); }
        public T[] Build()
        {
            // TLEする ... this.Compressed = this.A.Distinct().OrderBy(a => a).ToArray();
            this.Compressed = this.A.Distinct().ToArray();
            Array.Sort(this.Compressed);
            return this.Compressed;
        }
        public int Get(T x)
        {
            if (this.Compressed == null) this.Build();
            var l = -1;
            var r = Compressed.Length;
            while (r - l > 1)
            {
                var mid = l + (r - l) / 2;
                var v = Compressed[mid];
                if (x.CompareTo(v) <= 0) r = mid;
                else l = mid;
            }
            return r;
        }
        public T this[int i] { get { return this.Compressed[i]; } }
    }
