class Solver
{
    public void Solve(Scanner sc)
    {
        int H, W, N;
        sc.Make(out H, out W, out N);
        var d = new Dictionary<int, Dictionary<int, int>>();
        for (int i = 0; i < N; i++)
        {
            int a, b;
            sc.Make(out a, out b);
            a--;b--;
            for (var j = 0; j < 3; j++)
                for (var k = 0; k < 3; k++)
                {
                    int h = j + a, w = k + b;
                    if (!Inside(h, w, H, W)||!Inside(h-2,w-2,H,W)) continue;
                    if (!d.ContainsKey(h)) d[h] = new Dictionary<int, int>();
                    if (!d[h].ContainsKey(w)) d[h][w] = 0;
                    d[h][w]++;
                }
        }
        var res = new long[10];
        foreach (var di in d.Values)
            foreach (var c in di.Values)
                res[c]++;
        res[0] = (H - 2L) * (W - 2) - res.Sum();
        Console.WriteLine(string.Join("\n", res));
    }
    int[] gh = new[] { 0, 0, 1, -1 }, gw = new[] { 1, -1, 0, 0 };
    public static bool Inside(int h, int w, int H, int W)
        => 0 <= h && h < H && 0 <= w && w < W;
}

