                this.y = y;
            }
        }
        static void Solve()
        {
            var o = ReadAndParseLongArr();
            var h = o[0];
            var w = o[1];
            var n = o[2];
            var list = new List<Square>();
            for(int i=0;i<n;++i)
            {
                o = ReadAndParseLongArr();
                var a = o[0]-1;
                var b = o[1]-1;
                for(int k=0;k<=2;++k)
                {
                    for(int l=0;l<=2;++l)
                    {
                        var x = b - k;
                        var y = a - l;
                        if(0<=x && x < w-2 && 0<= y && y < h-2)
                        {
                            var key = new Square(x, y);
                            list.Add(key);
                        }
                    }
                }
            }
            list.Sort(Compare);

            var ans = new long[10];
            if (list.Count >= 1)
            {
                var cnt = 1;
                var curS = list[0];
                for (int i = 1; i < list.Count; ++i)
                {
                    if (list[i].x != curS.x || list[i].y != curS.y)
                    {
                        ans[cnt]++;
                        cnt = 1;
                        curS = list[i];
                    }
                    else
