namespace Program
{
    #region Solver
    public class Solver
    {
        static IO.StreamScanner
        sc = new IO.StreamScanner(Console.OpenStandardInput());

        Dictionary<center, int> map;

        int H;
        int W;
        int N;

        int[] a;
        int[] b;

        int[] ans;

        #region center
        public class center
        {
            public int x { get; set; }
            public int y { get; set; }
        }
        #endregion

        #region
        public class centerComparer : IEqualityComparer<center>
        {
            public bool Equals(center a, center b)
            {
                return a.x == b.x && b.y == b.y;
            }

            public int GetHashCode(center c)
            {
                return c.x.GetHashCode() + c.y.GetHashCode();
            }
        }
        #endregion

        #region Solver
        public Solver()
        {
            H = sc.Integer();
            W = sc.Integer();
            N = sc.Integer();

            a = new int[N];
            b = new int[N];

            ans = new int[9];

            for (int i = 0; i < N; i++)
            {
                a[i] = sc.Integer();
                b[i] = sc.Integer();
            }

            for (int i = 0; i < ans.Length; i++) ans[i] = 0;
        }
        #endregion

        #region Solve
        public void Solve()
        {
            map = new Dictionary<center, int>(new centerComparer());

            for (int i = 0; i < N; i++)
            {
                for (int j = -1; j < 2; j++)
                {
                    for (int k = -1; k < 2; k++)
                    {
                        int x = b[i] + k - 1;
                        int y = a[i] + j - 1;

                        if (inside(x, y))
                        {
                            center ctr = new center();
                            ctr.x = x;
                            ctr.y = y;

                            int c;
                            if (map.TryGetValue(ctr, out c)) map[ctr]++;
                            else map.Add(ctr, 1);
                        }
                    }
                }
            }

            foreach (var m in map) ans[m.Value - 1]++;

            Console.WriteLine(
                (long)(H - 2) * (long)(W - 2) - (long)map.Count);

            for (int i = 0; i < ans.Length; i++)
                Console.WriteLine(ans[i]);
        }
        #endregion

        #region inside
        public bool inside(int x, int y)
        {
            return 0 < x && x < W - 1 && 0 < y && y < H - 1;
        }
        #endregion
    }
    #endregion
}
