namespace AtCoder
{
    class Program
    {
        static void Main()
        {
            var HWN = Utility.ReadIntArray();
            var H = HWN[0];
            var W = HWN[1];
            var N = HWN[2];
            var ab = new Point[N];
            var ans = new long[10];
            for (int i = 0; i < N; i++)
            {
                var temp = Utility.ReadIntArray();
                ab[i] = new Point(temp[0] - 1, temp[1] - 1);
            }
            var dic = new Dictionary<long,int>();
            for (int i = 0; i < ab.Length; i++)
            {
                for (var baseX = Math.Max(0, ab[i].X - 2); baseX <= Math.Min(H - 3, ab[i].X); baseX++)
                {
                    for (var baseY = Math.Max(0, ab[i].Y - 2); baseY <= Math.Min(W - 3, ab[i].Y); baseY++)
                    {
                        var key = ((long)baseX << 32) + baseY;
                        if (!dic.ContainsKey(key))
                        {
                            dic.Add(key, 0);
                        }
                        dic[key]++;
                    }
                }

            }
            foreach(var p in dic)
            {
                ans[p.Value]++;
            }

            ans[0] = ((long)H - 2) * (W - 2) - ans.Skip(1).Sum();
            foreach (var an in ans)
            {
                Console.WriteLine(an);
            }
        }
        struct Point
        {
            public readonly int X;
            public readonly int Y;
            public Point(int x, int y)
            {
                X = x;
                Y = y;
            }
        }
