        public static int[] ReadIntArray() => ReadStringArray().ParseInt().ToArray();
        public static IEnumerable<int> ParseInt(this IEnumerable<string> source) => source.Select(v => int.Parse(v));

        public static IEnumerable<int> EnumerateDigits(int value)
        {
            while (value > 0)
            {
                yield return value % 10;
                value /= 10;
            }
        }

    }

    public class Factorial
    {
        public static long Number(long term)
        {
            return term > 1 ? Number(term - 1) * term : 1;
        }

        public static long[] Cache(long term)
        {
            var cache = new long[term + 1];
            cache[0] = 1;
            for (int i = 1; i < cache.Length; i++)
            {
                cache[i] = cache[i - 1] * i;
            }
            return cache;
        }

        public static long[] CacheMod(long term, long mod)
        {
            var cache = new long[term + 1];
            cache[0] = 1;
            for (int i = 1; i < cache.Length; i++)
            {
                cache[i] = cache[i - 1] * i % mod;
            }
            return cache;
        }
    }
}

