using System;
using System.Collections.Generic;

public class Program
{

    public static void Main()
    {
        new Program().Solver();
    }

    private long H;
    private long W;
    private long N;

    void Solver()
    {
        String[] input = Console.ReadLine().Split(' ');
        H = long.Parse(input[0]);
        W = long.Parse(input[1]);
        N = long.Parse(input[2]);
        Dictionary<long, Dictionary<long, int>> dic = new Dictionary<long, Dictionary<long, int>>();

        for (int n = 0; n < N; n++)
        {
            input = Console.ReadLine().Split(' ');
            long h = int.Parse(input[0]) - 1;
            long w = int.Parse(input[1]) - 1;
            for (int i = 0; i >= -2; i--)
            {
                long hh = h + i;
                if (hh < 0) continue;
                if (hh >= H - 2) continue;

                for (int j = 0; j >= -2; j--)
                {
                    long ww = w + j;
                    if (ww < 0) continue;
                    if (ww >= W - 2) continue;

                    if (!dic.ContainsKey(hh))
                    {
                        dic.Add(hh, new Dictionary<long, int>());
                    }

                    if (!dic[hh].ContainsKey(ww))
                    {
                        dic[hh].Add(ww, 1);
                    }
                    else
                    {
                        dic[hh][ww]++;
                    }
                }
            }
        }

        long[] res = new long[10];
        for (int i = 0; i < 10; i++) res[i] = 0;
        res[0] = (H - 2) * (W - 2);
        foreach (var wdic in dic.Values)
        {
            foreach (var index in wdic.Values)
            {
                res[0]--;
                res[index]++;
            }
        }

        for (int i = 0; i < 10; i++)
        {
            Console.WriteLine(res[i]);
        }
    }
}

