namespace ABC045_D_SnukesColoring
{
    class ABC045_D
    {
        static void Main(string[] args)
        {
            string[] first = Console.ReadLine().Split(' ');
            int H = int.Parse(first[0]);
            int W = int.Parse(first[1]);
            int N = int.Parse(first[2]);

            var blackPoints = new List<KeyValuePair<int, int>>();
            for (int i = 0; i < N; i++)
            {
                string[] split = Console.ReadLine().Split(' ');
                blackPoints.Add(new KeyValuePair<int, int>(int.Parse(split[0]) - 1, int.Parse(split[1]) - 1));
            }

            // 黒いマスを作る
            int[,] board = new int[H, W];
            for (int i = 0; i < N; i++)
            {
                board[blackPoints[i].Key, blackPoints[i].Value]++;
            }

            int[] counts = new int[10];

            for (int y = 0; y < H - 2; y++)
            {
                for (int x = 0; x < W - 2; x++)
                {
                    counts[Sum3x3(board, y, x)]++;
                }
            }

            for (int i = 0; i < counts.Length; i++)
            {
                Console.WriteLine(counts[i]);
            }
        }

        static int Sum3x3(int[,] board, int top, int left)
        {
            int sum = 0;
            for (int y = 0; y < 3; y++)
            {
                for (int x = 0; x < 3; x++)
                {
                    sum += board[top + y, left + x];
                }
            }

            return sum;
        }
    }
}

