            var yStart = Math.Max(0, 2 - y);
            var xEnd = Math.Min(3, W - x);
            var yEnd = Math.Min(3, H - y);

            for (int i = xStart; i < xEnd; i++)
                for (int j = yStart; j < yEnd; j++)
                {
                    var sum = sumsHorisontal[i, j] + sumsHorisontal[i + 1, j] + sumsHorisontal[i + 2, j];
                    res[sum]--;
                    res[sum + 1]++;
                }
