        {
            var hwn = ReadInts().ToArray();
            var lst = new List<Tuple<int, int>>();
            foreach (var i in Enumerable.Range(0, hwn[2]))
            {
                var ab = ReadInts().ToArray();
                for (var j = 0; j <= 2; ++j)
                {
                    for (var k = 0; k <= 2; ++k)
                    {
                        var a = ab[0] - j;
                        var b = ab[1] - k;
                        if (a - j < 1 || b - k < 1 || a > hwn[0] - 2 || b > hwn[1] - 2) continue;
                        lst.Add(Tuple.Create(ab[0] - j, ab[1] - k));
                    }
                }
            }
            var res = lst.GroupBy(p => p)
                .Select(g => g.Count())
                .OrderBy(i => i)
                .GroupBy(i => i)
                .ToDictionary(g => g.Key, g => g.LongCount());
            res.Add(0, (long)(hwn[0] - 2) * (long)(hwn[1] - 2) - res.Select(t => t.Value).Sum());
            foreach (var i in Enumerable.Range(0, 10))
