            for (long LoopX = b - 2; LoopX <= b; LoopX++) {
                if (LoopX < 1) continue;
                if (LoopX + 2 > W) continue;

                for (long LoopY = a - 2; LoopY <= a; LoopY++) {
                    if (LoopY < 1) continue;
                    if (LoopY + 2 > H) continue;

                    long Hash = GetHash(LoopX, LoopY);
                    if (CntDict.ContainsKey(Hash))
                        CntDict[Hash]++;
                    else CntDict[Hash] = 1;
                }
            }
        }

