    class Program
    {
        static void Main()
        {
            var HWN = Utility.ReadIntArray();
            var H = HWN[0];
            var W = HWN[1];
            var N = HWN[2];
            var ab = new Point[N];
            var ans = new long[10];
            for (int i = 0; i < N; i++)
            {
                var temp = Utility.ReadIntArray();
                ab[i] = new Point(temp[0] - 1, temp[1] - 1);
            }
            var list = new List<long>();
            for (int i = 0; i < ab.Length; i++)
            {
                for (var baseX = Math.Max(0, ab[i].X - 2); baseX <= Math.Min(H - 3, ab[i].X); baseX++)
                {
                    for (var baseY = Math.Max(0, ab[i].Y - 2); baseY <= Math.Min(W - 3, ab[i].Y); baseY++)
                    {
                        if (!list.Contains(((long)baseX << 32) + baseY))
                        {
                            list.Add(((long)baseX << 32) + baseY);

                            var count = ab.Count(v => baseX <= v.X && v.X < baseX + 3 && baseY <= v.Y && v.Y < baseY + 3);
                            ans[count]++;
                        }
                    }
                }

            }
            ans[0] = ((long)H - 2) * (W - 2) - ans.Skip(1).Sum();
            foreach (var an in ans)
            {
                Console.WriteLine(an);
            }
        }
