	public class Program
	{
		static void Main(string[] args)
		{
			var cin = new Scanner2();
			long h = cin.Long();
			long w = cin.Long();
			int n = cin.Int();

			var ans = new long[10];
			ans[0] = (h - 2) * (w - 2);

			var dirs = new XY[] {
				new XY(0, 0),
				new XY(1, 0),
				new XY(-1, 0),
				new XY(0, 1),
				new XY(1, 1),
				new XY(-1, 1),
				new XY(0, -1),
				new XY(1, -1),
				new XY(-1, -1),
			};

			var dic = new Dictionary<XY, int>(n * 9);
			for (int i = 0; i < n; i++) {
				int a = cin.Int() - 1;
				int b = cin.Int() - 1;
				foreach (var dir in dirs) {
					int y = a + dir.Y;
					int x = b + dir.X;
					if (y >= 1 && y < h - 1 && x >= 1 && x < w - 1) {
						XY value = new XY(x, y);
						if (dic.ContainsKey(value)) {
							int num = dic[value];
							ans[num]--;
							ans[num + 1]++;
							dic[value] = num + 1;
						} else {
							ans[0]--;
							ans[1]++;
							dic[value] = 1;
						}
					}
				}
			}

			for (int i = 0; i < 10; i++) {
				Console.WriteLine(ans[i]);
			}
		}
	}

	public class XY
	{
		public int X { get; set; }
		public int Y { get; set; }

		public XY(int x, int y)
		{
			X = x;
			Y = y;
		}

		public override bool Equals(object obj)
		{
			return obj is XY xY &&
				   X == xY.X &&
				   Y == xY.Y;
		}

		public override int GetHashCode()
		{
			var hashCode = 1861411795;
			hashCode = hashCode * -1521134295 + X.GetHashCode();
			hashCode = hashCode * -1521134295 + Y.GetHashCode();
			return hashCode;
		}
	}

	public class Scanner2
	{
		private readonly char[] delimiter_ = new char[] { ' ' };
		private readonly string filePath_;
		private string[] buf_;
		private int index_;
		Func<string> reader_;

		public Scanner2(string file = "")
		{
			if (string.IsNullOrWhiteSpace(file)) {
				reader_ = Console.ReadLine;
			} else {
				filePath_ = file;
				var fs = new StreamReader(file);
				reader_ = fs.ReadLine;
			}
			buf_ = new string[0];
			index_ = 0;
		}

		public string Next()
		{
			if (index_ < buf_.Length) {
				return buf_[index_++];
			}

			string st = reader_();
			while (st == "") {
				st = reader_();
			}

			buf_ = st.Split(delimiter_, StringSplitOptions.RemoveEmptyEntries);
			if (buf_.Length == 0) {
				return Next();
			}

			index_ = 0;
			return buf_[index_++];
		}

		public int Int() => int.Parse(Next());
		public long Long() => long.Parse(Next());
		public double Double() => double.Parse(Next());

		public int[] ArrayInt(int N, int add = 0)
		{
			int[] Array = new int[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Int() + add;
			}
			return Array;
		}

		public long[] ArrayLong(int N, long add = 0)
		{
			long[] Array = new long[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Long() + add;
			}
			return Array;
		}

		public double[] ArrayDouble(int N, double add = 0)
		{
			double[] Array = new double[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Double() + add;
			}
			return Array;
		}

		public void Save(string text)
		{
			if (string.IsNullOrWhiteSpace(filePath_)) {
				return;
			}

			File.WriteAllText(filePath_ + "_output.txt", text);
		}
	}
}

