namespace atcoder
{
    class Program
    {
        static void Main(string[] args)
        {
            string[] s = Console.ReadLine().Split();
            long h = long.Parse(s[0]);
            long w = long.Parse(s[1]);
            int n = int.Parse(s[2]);
            List<Tuple<int, int>> black = new List<Tuple<int, int>>();
            for (int i = 0; i < n; i++)
            {
                string[] ab = Console.ReadLine().Split();
                black.Add(new Tuple<int, int>(int.Parse(ab[0]), int.Parse(ab[1])));
            }
            long[] cnt = new long[10];
            List<Tuple<int, int>> board = new List<Tuple<int, int>>();
            foreach (var item in black)
            {
                var search = black.Where(f => f.Item1 >= item.Item1 - 2 && f.Item1 <= item.Item1 + 2 && f.Item2 >= item.Item2 - 2 && f.Item2 <= item.Item2 + 2);
                for (int i = item.Item1 - 1; i <= item.Item1 + 1; i++)
                {
                    for (int j = item.Item2 - 1; j <= item.Item2 + 1; j++)
                    {
                        if (i > 1 && i < h && j > 1 && j < w)
                        {
                            var masu = new Tuple<int, int>(i, j);
                            if (board.Contains(masu) == false)
                            {
                                board.Add(masu);
                                cnt[search.Where(f => f.Item1 >= masu.Item1 - 1 && f.Item1 <= masu.Item1 + 1 && f.Item2 >= masu.Item2 - 1 && f.Item2 <= masu.Item2 + 1).Count()]++;
                            }
                        }
                    }
                }
            }

            cnt[0] = (h - 2) * (w - 2) - cnt.Sum();
