                    var cnt = 0;
                    for (var ix = x - 1; ix <= x + 1; ix++)
                    {
                        for (var iy = y - 1; iy <= y + 1; iy++)
                        {
                            if (blacks.Contains(iy << 32 | ix)) cnt++;
                        }
                    }
                    if (cnt == j) ret += 1;
                }
