namespace CompetitiveProgramming
{

  class Solve
  {
    const int INF = (int)(1e9) + 10;

    private void Main()
    {
      long[] HWN = Console.ReadLine().Split().Select(long.Parse).ToArray();
      long H = HWN[0], W = HWN[1], N = HWN[2];

      long[] count = new long[10];
      long sum = 0;
      long[,] nums = new long[H, W];

      for (long i = 0; i < N; i++)
      {
        long[] ab = Console.ReadLine().Split().Select(long.Parse).ToArray();
        long a = ab[0] - 1, b = ab[1] - 1;

        for (long j = -2; j <= 0; j++)
        {
          for (long k = -2; k <= 0; k++)
          {
            long t = a + j;
            long u = b + k;
            if (t >= 0 && t + 2 < H && u >= 0 && u + 2 < W)
            {
              long tmp = ++nums[t, u];
              if (tmp - 1 == 0)
              {
                sum++;
              }
              else
              {
                --count[tmp - 1];
              }
              ++count[tmp];
            }
          }
        }
      }
      count[0] = (H - 2) * (W - 2) - sum;
      for (int i = 0; i < 10; i++)
      {
        Console.WriteLine(count[i]);
      }
    }

    public Solve()
    {
      Console.SetOut(new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false });
      Main();
      Console.Out.Flush();
    }
  }

  class Program
  {
    static void Main(string[] args)
    {
      new Solve();
    }
  }
}

