            for(int i=0; i < N; i++)
            {
                long a, b, n;
                for(int y=0; y < 3; y++)
                {
                    for(int x=0; x < 3; x++)
                    {
                        a = ab[i, 0] - y;
                        b = ab[i, 1] - x;
                        if (a < 1 || a > H - 2 || b < 1 || b > W - 2)
