namespace AtCoder
{
    class Program
    {
        static public long[] Sarray() { return ReadLine().Split().Select(long.Parse).ToArray(); }
        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }
        static long Mod = (long)1e9 + 7;
        static void Main(string[] args)
        {
            SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
            Solve();
            Out.Flush();
            Read();
        }
        static void Solve()
        {
            var HWN = Sarray();
            var H = HWN[0];
            var W = HWN[1];
            var N = HWN[2];
            var bMasu = new HashSet<(long h, long w)>();
            for (var i = 0; i < N; ++i)
            {
                var ab = Sarray();
                bMasu.Add((ab[0], ab[1]));
            }
            var used = new HashSet<(long h, long w)>();
            var zah = new long[] { -1, 0, 1, -1, 0, 1, -1, 0, 1 };
            var zaw = new long[] { -1, -1, -1, 0, 0, 0, 1, 1, 1 };

            var nums = new long[10];
            foreach (var b in bMasu)
            {
                for (var i = 0; i < 9; ++i)//中心
                {
                    var ch = b.h + zah[i];
                    var cw = b.w + zaw[i];
                    if (1 < ch && ch < H && 1 < cw && cw < W && !used.Contains((ch, cw)))
                    {
                        var cnt = 0;
                        for (var j = 0; j < 9; ++j)//フィルタ
                        {
                            var h = ch + zah[j];
                            var w = cw + zaw[j];
                            if (bMasu.Contains((h, w))) ++cnt;
                        }
                        ++nums[cnt];
                    }
                    used.Add((ch, cw));
                }
            }
            var square = (H - 2) * (W - 2);
            nums[0] = square - nums.Skip(1).Sum();
            foreach (var n in nums)
                WriteLine(n);
        }
    }
}

