class Program
{
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
    }
    static void Solve()
    {
        var H = sc.ReadInt();
        var W = sc.ReadInt();
        var N = sc.ReadInt();
        var counted = new HashSet<Tuple<int, int>>();
        var blacks = new HashSet<Tuple<int, int>>();
        for (int i = 0; i < N; i++)
        {
            var a = sc.ReadInt();
            var b = sc.ReadInt();
            blacks.Add(Tuple.Create(a, b));
        }
        var ans = new long[10];
        foreach (var t in blacks)
        {
            var h = t.Item1;
            var w = t.Item2;
            var dhw = new int[] { -2, -1, 0 };
            foreach (var dh in dhw)
            {
                foreach (var dw in dhw)
                {
                    var nh = h + dh;
                    var nw = w + dw;
                    if (1 <= nh && nh <= H - 2 && 1 <= nw && nw <= W - 2)
                    {
                        var key = Tuple.Create(nh, nw);
                        if (counted.Contains(key)) continue;
                        var count = 0;
                        for (int i = 0; i < 3; i++)
                        {
                            for (int j = 0; j < 3; j++)
                            {
                                var nowH = nh + i;
                                var nowW = nw + j;
                                if (blacks.Contains(Tuple.Create(nowH, nowW))) count++;
                            }
                        }
                        counted.Add(key);
                        ans[count]++;
                    }
                }
            }
        }
        var tot = (long)(H - 2) * (W - 2);
        ans[0] = tot - ans.Sum();
        foreach (var item in ans)
        {
            Console.WriteLine(item);
        }
    }
