	class Program
	{
		static void Main(string[] args)
		{
			var firstLine = Console.ReadLine().Split(' ').Select(value => long.Parse(value)).ToList();
			var h = firstLine[0];
			var w = firstLine[1];
			var n = firstLine[2];

			var points = new List<Point>();

			for(long i = 0; i < n; i++)
			{
				var tmpList = Console.ReadLine().Split(' ').Select(value => long.Parse(value)).ToList();
				var point = new Point() { A = tmpList[0], B = tmpList[1] };
				points.Add(point);
			}

			var rectangleDictionary = new Dictionary<long, int>();

			foreach(var point in points)
			{
				var tmpA = point.A - 1;
				var tmpB = point.B - 1;
				if (tmpA > 1 && tmpB > 1)
				{
					AddIfEmptyOrIncrement(rectangleDictionary, tmpA * (h + 1) + tmpB);
				}
				tmpB++;
				if (tmpA > 1 && tmpB > 1 && tmpB < w)
				{
					AddIfEmptyOrIncrement(rectangleDictionary, tmpA * (h + 1) + tmpB);
				}
				tmpB++;
				if (tmpA > 1 && tmpB < w)
				{
					AddIfEmptyOrIncrement(rectangleDictionary, tmpA * (h + 1) + tmpB);
				}
				tmpA++;
				tmpB -= 2;
				if (tmpA > 1 && tmpA < h && tmpB > 1)
				{
					AddIfEmptyOrIncrement(rectangleDictionary, tmpA * (h + 1) + tmpB);
				}
				tmpB++;
				if (tmpA > 1 && tmpA < h && tmpB > 1 && tmpB < w)
				{
					AddIfEmptyOrIncrement(rectangleDictionary, tmpA * (h + 1) + tmpB);
				}
				tmpB++;
				if (tmpA > 1 && tmpA < h &&  tmpB < w)
				{
					AddIfEmptyOrIncrement(rectangleDictionary, tmpA * (h + 1) + tmpB);
				}
				tmpA++;
				tmpB -= 2;
				if (tmpA < h && tmpB > 1)
				{
					AddIfEmptyOrIncrement(rectangleDictionary, tmpA * (h + 1) + tmpB);
				}
				tmpB++;
				if (tmpA < h && tmpB > 1 && tmpB < w)
				{
					AddIfEmptyOrIncrement(rectangleDictionary, tmpA * (h + 1) + tmpB);
				}
				tmpB++;
				if (tmpA < h && tmpB < w)
				{
					AddIfEmptyOrIncrement(rectangleDictionary, tmpA * (h + 1) + tmpB);
				}
			}

			var countDictionary = new Dictionary<int, long>();
			for(int i = 0; i < 10; i++)
			{
				countDictionary.Add(i, 0);
			}

			foreach(var value in rectangleDictionary.Values)
			{
				countDictionary[value]++;
			}

			countDictionary[0] = (h - 2) * (w - 2) - countDictionary.Values.Sum();

			foreach(var i in countDictionary.Values)
			{
				Console.WriteLine(i);
			}
		}

		private static void AddIfEmptyOrIncrement(Dictionary<long, int> dictionary, long hash)
		{
			if(dictionary.ContainsKey(hash))
			{
				dictionary[hash]++;
			}
			else
			{
				dictionary.Add(hash, 1);
			}
		}

