class Program
{
    public void Proc()
    {
        Reader.IsDebug = false;
        long[] inpt = Reader.ReadLine().Split(' ').Select(a => long.Parse(a)).ToArray();
        this.H = inpt[0];
        this.W = inpt[1];

        int queryCount = (int)inpt[2];

        Dictionary<long, Dictionary<long, int>> map = new Dictionary<long, Dictionary<long, int>>();

        for (int i = 0; i < queryCount; i++)
        {
            Pos p = new Pos(Reader.ReadLine());

            list.Add(p);

            for (long j = p.H - 2; j <= p.H; j++)
            {
                if (j < 0)
                {
                    continue;
                }
                if (j + 2 >= this.H)
                {
                    break;
                }
                if (!map.ContainsKey(j))
                {
                    map.Add(j, new Dictionary<long, int>());
                }
                for (long k = p.W - 2; k <= p.W; k++)
                {
                    if (k < 0)
                    {
                        continue;
                    }
                    if (k + 2 >= this.W)
                    {
                        break;
                    }
                    if (map[j].ContainsKey(k))
                    {
                        map[j][k]++;
                    }
                    else
                    {
                        map[j].Add(k, 1);
                    }
                }
            }
        }



        long[] ans = new long[10];
        ans[0] = ((this.H - 2) * (this.W - 2)) - map.Sum(a=>a.Value.Count());
        foreach (long key in map.Keys)
        {
            foreach (long k2 in map[key].Keys)
            {
                int num = map[key][k2];
                ans[num]++;
            }
        }

        for (int i = 0; i <= 9; i++)
        {
            Console.WriteLine(ans[i]);
        }

    }

