class Program
{
    public static void Main()
    {
	var tmp = ReadIntArray();
	long h = tmp[0], w = tmp[1], n = tmp[2];

	var d = new Dictionary<long, int>();

	int[] dx = {-2, -1,  0, -2, -1, 0, -2, -1, 0};
	int[] dy = {-2, -2, -2, -1, -1, -1, 0,  0, 0};


	for (int i = 0; i < n; i++)
	{
	    tmp = ReadIntArray();
	    int a = tmp[0], b = tmp[1];
	    for (int j = 0; j < 9; j++)
	    {
		int x = a + dx[j], y = b + dy[j];
		if (x < 1 || x > h - 2 || y < 1 || y > w - 2) continue;
		long key = (((long) x) << 32) + y;
		if (d.ContainsKey(key)) d[key]++;
		else d.Add(key, 1);
	    }
	}

