	class Problem : IDisposable
	{
		bool IsGCJ;
		int Repeat;
		Scanner sc;
		Printer pr;
		public Problem(bool isGCJ, Scanner scanner, Printer printer)
		{
			sc = scanner;
			pr = printer;
			IsGCJ = isGCJ;
			if (isGCJ) Repeat = sc.Get<int>();
			else Read();
		}
		public Problem(bool isGCJ) : this(isGCJ, new Scanner(), new Printer())
		{
		}
		public Problem(bool isGCJ, Scanner scanner) : this(isGCJ, scanner, new Printer())
		{
		}
		public Problem(bool isGCJ, Printer printer) : this(isGCJ, new Scanner(), printer)
		{
		}
		public void Solve()
		{
			if (IsGCJ) for (var i = 0; i < Repeat; i++)
				{
					Read();
					pr.Write("Case #" + (i + 1) + ": ");
					SolveOne();
				}
			else SolveOne();
		}
		public void Dispose()
		{
			sc.Dispose();
			pr.Dispose();
		}
		public int Size { get { return 1; } }
		public const uint Mod = 1000000007;
		RandomSFMT rand = Program.rand;
		int Y, X, N;
		Tuple<int,int>[] ps;
		void Read()
		{
			sc.Read(out Y, out X, out N);
			ps = sc.ReadManyLines<int,int>(N);
		}
		SortedDictionary<Tuple<int,int>,long> bs;
		void Add(int x, int y)
		{
			var k = new Tuple<int,int>(x, y);
			if (bs.ContainsKey(k)) bs[k]++;
			else bs.Add(k, 1);
		}
		void SolveOne()
		{
			bs = new SortedDictionary<Tuple<int,int>,long>(new Comp());
			foreach (var p in ps)
			{
				int x = p.Item2-1, y = p.Item1-1;
				for (var dx = -1; dx <= 1; dx++)
					for (var dy = -1; dy <= 1; dy++)
					{
						int a = x + dx, b = y + dy;
						if (a >= 0 && a < X && b >= 0 && b < Y) Add(a, b);
					}
			}
			var ans = new long[10];
			foreach (var t in bs)
			{
				int x = t.Key.Item1, y = t.Key.Item2;
				if (x >= 1 && x < X - 1 && y >= 1 && y < Y - 1) ans[t.Value]++;
			}
			ans[0] = (X - 2L) * (Y - 2L) - ans.Sum();
			for (var i = 0; i < 10; i++) pr.WriteLine(ans[i]);
		}
	}
}
class Comp : IComparer<Tuple<int,int>>
{
	public int Compare(Tuple<int, int> x, Tuple<int, int> y)
	{
		var c = x.Item1.CompareTo(y.Item1);
		return c == 0 ? x.Item2.CompareTo(y.Item2) : c;
	}
}
