class SkewHeap<T> : IEnumerable<T>
{
	class Node : IEnumerable<T>
	{
		public Node l, r;
		public T val;
		public Node(T x)
		{
			l = r = null;
			val = x;
		}
		public IEnumerator<T> GetEnumerator()
		{
			if (l != null) foreach (var x in l) yield return x;
			yield return val;
			if (r != null) foreach (var x in r) yield return x;
		}
		IEnumerator IEnumerable.GetEnumerator()
		{
			return (IEnumerator)GetEnumerator();
		}
	}
	public int Count { get; private set; }
	Node head;
	Comparison<T> comp;
	public bool IsEmpty { get { return head != null; } }
	public SkewHeap(Comparison<T> c)
	{
		comp = c;
		Count = 0;
	}
	public SkewHeap() : this(Func.DefaultComparison<T>())
	{
	}
	public SkewHeap(IComparer<T> c) : this(Func.ToComparison(c))
	{
	}
	private SkewHeap(Comparison<T> c, Node h) : this(c)
	{
		head = h;
	}
	public void Push(T x)
	{
		var n = new Node(x);
		head = Meld(head, n);
		Count++;
	}
	public T Peek()
	{
		return head.val;
	}
	public T Pop()
	{
		var x = head.val;
		head = Meld(head.l, head.r);
		Count--;
		return x;
	}
	// a.comp must be equivalent to b.comp
	// a, b will be destroyed
	public static SkewHeap<T> Meld(SkewHeap<T> a, SkewHeap<T> b)
	{
		return new SkewHeap<T>(a.comp, a.Meld(a.head, b.head));
	}
	public void MeldWith(SkewHeap<T> a)
	{
		head = Meld(head, a.head);
	}
	Node Meld(Node a, Node b)
	{
		if (a == null) return b;
		else if (b == null) return a;
		if (comp(a.val, b.val) > 0) Func.Swap(ref a, ref b);
		a.r = Meld(a.r, b);
		Func.Swap(ref a.l, ref a.r);
		return a;
	}
	public IEnumerator<T> GetEnumerator()
	{
		return head.GetEnumerator();
	}
	IEnumerator IEnumerable.GetEnumerator()
	{
		return (IEnumerator)GetEnumerator();
	}
}
