		: this(array.GetLength(0), array.GetLength(1))
	{
		for (var x = 0; x < X; x++) for (var y = 0; y < Y; y++) Add(x, y, array[x, y]);
	}
	public void Add(int x, int y, int value)
	{
		for (var i = x + 1; i <= X; i += i & (-i)) for (var j = y + 1; j <= Y; j += j & (-j)) bit[i, j] += value;
	}
	public int Sum(int x0, int y0, int x1, int y1)
	{
		return Sum(x0, y0) + Sum(x1, y1) - Sum(x0, y1) - Sum(x1, y0);
	}
	int Sum(int x, int y)
	{
		var sum = 0;
		for (var i = x; i > 0; i -= i & (-i)) for (var j = y; j > 0; j -= j & (-j)) sum += bit[i, j];
		return sum;
	}
}
class BinaryIndexedTree
{
	public int Size { get; private set; }
	int[] bit;
	public BinaryIndexedTree(int size)
	{
		Size = size;
		bit = new int[size + 1];
	}
	public BinaryIndexedTree(int[] array) : this(array.Length)
	{
		for (var i = 0; i < Size; i++) bit[i + 1] = array[i];
		for (var i = 1; i < Size; i++) if (i + (i & (-i)) <= Size) bit[i + (i & (-i))] += bit[i];
	}
	// index is 0-indexed
	public void Add(int index, int value)
	{
		for (var i = index + 1; i <= Size; i += i & (-i)) bit[i] += value;
	}
	// from, to is 0-indexed
	// from is inclusive, to is exclusive
	public int Sum(int from, int to)
	{
		return Sum(to) - Sum(from);
	}
	int Sum(int to)
	{
		var sum = 0;
		for (var i = to; i > 0; i -= i & (-i)) sum += bit[i];
		return sum;
	}
}
class Amoeba
{
	public const int Dimension = 2;
	public const double Alpha = 1;
	// reflection
	public const double Beta = 1 + 2.0 / Dimension;
	// expansion
	public const double Gamma = 0.75 - 0.5 / Dimension;
	// contraction
	public const double Delta = 1 - 1.0 / Dimension;
	// shrink
	public Pair<AmoebaState, double>[] a;
	public AmoebaState m;
	public void Initiate()
	{
		Array.Sort(a, (x, y) => x.Second.CompareTo(y.Second));
		m = new AmoebaState();
		for (var i = 0; i < Dimension; i++) m.Add(a[i].First);
		m.Multiply(1.0 / Dimension);
	}
	void PartialSort(int i, int j)
	{
		if (a[i].Second > a[j].Second) a.Swap(i, j);
	}
	void Accept(AmoebaState point, double value)
	{
		var tmp = Func.FirstBinary(0, Dimension, x => a[x].Second >= value);
		if (tmp != Dimension) m.Add((point - a[Dimension - 1].First) / Dimension);
		for (var i = Dimension; i > tmp; i--) a[i] = a[i - 1];
		a[tmp].First = point;
		a[tmp].Second = value;
	}
	public void Search()
	{
		var r = m + Alpha * (m - a[Dimension].First);
		var fr = r.Func();
		if (a[0].Second <= fr && fr < a[Dimension - 1].Second)
		{
			Accept(r, fr);
			return;
		}
		var diff = r - m;
		if (fr < a[0].Second)
		{
			var e = m + Beta * diff;
			var fe = e.Func();
			if (fe < fr) Accept(e, fe);
			else Accept(r, fr);
		}
		else
		{
			var tmp = Gamma * diff;
			var o = m + tmp;
			var fo = o.Func();
			var i = m - tmp;
			var fi = i.Func();
			if (fi < fo)
			{
				o = i;
				fo = fi;
			}
			if (fo < a[Dimension - 1].Second) Accept(o, fo);
			else Shrink();
		}
	}
	void Shrink()
	{
		var tmp = (1 - Delta) * a[0].First;
		for (var i = 1; i <= Dimension; i++)
		{
			a[i].First.Multiply(Delta);
			a[i].First.Add(tmp);
			a[i].Second = a[i].First.Func();
		}
		Initiate();
	}
}
class AmoebaState
{
	public static int Dimension = 2;
	public double[] vec;
	public AmoebaState()
	{
		vec = new double[Dimension];
	}
	public AmoebaState(params double[] elements) : this()
	{
		elements.CopyTo(vec, 0);
	}
	public double this[int n] { get { return vec[n]; } set { vec[n] = value; } }
	public void Multiply(double r)
	{
		for (var i = 0; i < Dimension; i++) vec[i] *= r;
	}
	public void Add(AmoebaState v)
	{
		for (var i = 0; i < Dimension; i++) vec[i] += v.vec[i];
	}
	public static AmoebaState operator +(AmoebaState p)
	{
		return new AmoebaState(p.vec);
	}
	public static AmoebaState operator -(AmoebaState p)
	{
		var tmp = new AmoebaState(p.vec);
		tmp.Multiply(-1);
		return tmp;
	}
	public static AmoebaState operator /(AmoebaState p, double r)
	{
		var tmp = new AmoebaState(p.vec);
		tmp.Multiply(1 / r);
		return tmp;
	}
	public static AmoebaState operator *(double r, AmoebaState p)
	{
		var tmp = new AmoebaState(p.vec);
		tmp.Multiply(r);
		return tmp;
	}
	public static AmoebaState operator *(AmoebaState p, double r)
	{
		return r * p;
	}
	public static AmoebaState operator +(AmoebaState p, AmoebaState q)
	{
		var tmp = +p;
