		foreach (var v in nodes) sb.Append("\tv" + v.Code + " [label = \"" + vertex(v.Information) + "\"];\n");
		foreach (var e in edges) sb.Append("\tv" + e.From + " -> v" + e.To + " [label=\"" + edge(e.Information) + "\"];\n");
		sb.Append("}");
		return sb.ToString();
	}
	public override string ToString()
	{
		return ToString(v => v.ToString(), e => e.ToString());
	}
}
class UnionFindTree
{
	int N;
	int[] parent, rank, size;
	public UnionFindTree(int capacity)
	{
		N = capacity;
		parent = new int[N];
		rank = new int[N];
		size = new int[N];
		for (var i = 0; i < N; i++)
		{
			parent[i] = i;
			size[i] = 1;
		}
	}
	public int GetSize(int x)
	{
		return size[GetRootOf(x)];
	}
	public int GetRootOf(int x)
	{
		return parent[x] == x ? x : parent[x] = GetRootOf(parent[x]);
	}
	public void UniteCategory(int x, int y)
	{
		if ((x = GetRootOf(x)) == (y = GetRootOf(y))) return;
		if (rank[x] < rank[y])
		{
			parent[x] = y;
			size[y] += size[x];
		}
		else
		{
			parent[y] = x;
			size[x] += size[y];
			if (rank[x] == rank[y]) rank[x]++;
		}
	}
	public bool IsSameCategory(int x, int y)
	{
		return GetRootOf(x) == GetRootOf(y);
	}
}
