	}
	bool UpperBound(Predicate<T> pred, AVLNode node, out AVLNode res)
	{
		if (node == sentinel)
		{
			res = null;
			return false;
		}
		if (pred(node.Item))
		{
			if (!UpperBound(pred, node.Right, out res)) res = node;
			return true;
		}
		else return UpperBound(pred, node.Left, out res);
	}
	bool LowerBound(Predicate<T> pred, AVLNode node, out AVLNode res)
	{
		if (node == sentinel)
		{
			res = null;
			return false;
		}
		if (pred(node.Item))
		{
			if (!LowerBound(pred, node.Left, out res)) res = node;
			return true;
		}
		else return LowerBound(pred, node.Right, out res);
	}
