	public static long GCD(long a, long b)
	{
		var n = (ulong)Math.Abs(a);
		var m = (ulong)Math.Abs(b);
		if (n == 0) return (long)m;
		if (m == 0) return (long)n;
		int zm = 0, zn = 0;
		while ((n & 1) == 0)
		{
			n >>= 1;
			zn++;
		}
		while ((m & 1) == 0)
		{
			m >>= 1;
			zm++;
		}
		while (m != n)
		{
			if (m > n)
			{
				m -= n;
				while ((m & 1) == 0) m >>= 1;
			}
			else
			{
				n -= m;
				while ((n & 1) == 0) n >>= 1;
			}
		}
		return (long)n << Math.Min(zm, zn);
	}
