    public string Result() { var obj = Calc(); if (obj is bool) return (bool)obj ? "Yes" : "No"; if (obj is double) return ((double)obj).ToString("0.####################"); return obj.ToString(); }
    private object Calc()
    {
        H = cr.Int;
        W = cr.Int;
        var N = cr.Int;
        res[0] = (long)(H - 2) * (W - 2);
        for (int i = 0; i < N; i++)
            Update(cr.Int0, cr.Int0);

        return AllLines(res);
    }

    void Update(int h, int w)
    {
        var cnts = NewArray(5, 5, 0);
        for (int i = 0; i < 5; i++)
            for (int j = 0; j < 5; j++)
                if (points.Contains(new Point(h - 2 + i, w - 2 + j)))
                    cnts[i][j] = 1;
        var sums = new Sums2D(cnts);
        for (int i = -1; i <= 1; i++)
            for (int j = -1; j <= 1; j++)
            {
                var hh = h + i;
                var ww = w + j;
                if (0 < hh && hh < H - 1 && 0 < ww && ww < W - 1)
                {
                    var old = sums[1 + i, 4 + i, 1 + j, 4 + j];
                    res[old]--;
                    res[old + 1]++;
                }
            }
        points.Add(new Point(h, w));
    }
    int H; int W;
    HashSet<Point> points = new HashSet<Point>();
    long[] res = new long[10];
