        HashSet<Tuple> candidateCenter = new HashSet<Tuple>();
        HashSet<Tuple> black = new HashSet<Tuple>();
        for (int iterate = 0; iterate < hwn[2]; iterate++)
        {
            var ab = Console.ReadLine().Split().Select(int.Parse).ToArray();
            for (int i = -1; i <= 1; i++)
            {
                for (int j = -1; j <= 1; j++)
                {
                    Tuple point = new Tuple(ab[0] + i, ab[1] + j);
                    if (point.Item1 <= 1 || hwn[0] - 1 < point.Item1 || point.Item2 <= 1 || hwn[1] - 1 < point.Item2)
                        continue;
                    candidateCenter.Add(point);
                }
            }
            black.Add(new Tuple(ab[0], ab[1]));
        }
        var res = new long[10];
        res[0] = (long)(hwn[0] - 2) * (hwn[1] - 2);
