    static void Solve()
    {
        var H = sc.ReadInt();
        var W = sc.ReadInt();
        var N = sc.ReadInt();
        var Hs = new int[N];
        var Ws = new int[N];
        var cxy = new Compress2D();
        for (int i = 0; i < N; i++)
        {
            var a = sc.ReadInt();
            var b = sc.ReadInt();
            Hs[i] = a;
            Ws[i] = b;
            for (int d = -2; d < 3; d++)
            {
                if (1 <= Hs[i] + d && Hs[i] + d <= H && 1 <= Ws[i] + d && Ws[i] + d <= W)
                    cxy.Add(Hs[i] + d, Ws[i] + d);
            }
        }
        cxy.Build();
        var countedFlag = new bool[cxy.MaxX, cxy.MaxY];
        var blacksFlag = new bool[cxy.MaxX, cxy.MaxY];
        for (int i = 0; i < N; i++)
        {
            var t = cxy.Get(Hs[i], Ws[i]);
            var h = t.Item1;
            var w = t.Item2;
            blacksFlag[h, w] = true;
        }
        var ans = new long[10];
        for (int i = 0; i < N; i++)
        {
            var t = cxy.Get(Hs[i], Ws[i]);
            var h = t.Item1;
            var w = t.Item2;
            var dhw = new int[] { -2, -1, 0 };
            foreach (var dh in dhw)
            {
                foreach (var dw in dhw)
                {
                    var nh = h + dh;
                    var nw = w + dw;
                    if (0 <= nh && nh < cxy.MaxX - 2 && 0 <= nw && nw < cxy.MaxY - 2)
                    {
                        if (countedFlag[nh, nw]) continue;
                        var count = 0;
                        for (int j = 0; j < 3; j++)
                        {
                            for (int k = 0; k < 3; k++)
                            {
                                var nowH = nh + j;
                                var nowW = nw + k;
                                if (blacksFlag[nowH, nowW]) count++;
                            }
                        }
                        countedFlag[nh, nw] = true;
                        ans[count]++;
                    }
                }
            }
        }
        var tot = (long)(H - 2) * (W - 2);
        ans[0] = tot - ans.Sum();
        foreach (var item in ans)
        {
            Console.WriteLine(item);
        }
    }
    class HashMap<K, V> : Dictionary<K, V> where V : new()
    {
        private V DefaltValue = new V();
        public HashMap() { }
        public HashMap(V defaultValue)
        {
            this.DefaltValue = new V();
        }
        new public V this[K i]
        {
            get
