    class Compress2D
    {
        public Compress<long> CX = new Compress<long>();
        public Compress<long> CY = new Compress<long>();
        public void Add(long x, long y) { CX.Add(x); CY.Add(y); }
        public void Build()
        {
            CX.Build(); CY.Build();
        }
        public Tuple<int, int> Get(long x, long y)
        {
            return Tuple.Create(CX.Get(x), CY.Get(y));
        }
        public Tuple<long, long> this[int i, int j]
        {
            get { return Tuple.Create(this.CX[i], this.CY[j]); }
        }
        public int MaxX { get { return this.CX.Compressed.Length; } }
        public int MaxY { get { return this.CY.Compressed.Length; } }
    }
    class Compress<T> where T : IComparable<T>
    {
        public List<T> A = new List<T>();
        public T[] Compressed;
        public void Add(T x) { this.A.Add(x); }
        public void Add(IEnumerable<T> x) { this.A.AddRange(x); }
        public T[] Build()
        {
            // TLEする ... this.Compressed = this.A.Distinct().OrderBy(a => a).ToArray();
            this.Compressed = this.A.Distinct().ToArray();
            Array.Sort(this.Compressed);
            return this.Compressed;
        }
        public int Get(T x)
        {
            if (this.Compressed == null) this.Build();
            var l = -1;
            var r = Compressed.Length;
            while (r - l > 1)
            {
                var mid = l + (r - l) / 2;
                var v = Compressed[mid];
                if (x.CompareTo(v) <= 0) r = mid;
                else l = mid;
            }
            return r;
        }
        public T this[int i] { get { return this.Compressed[i]; } }
    }
