				{
					AddIfEmptyOrIncrement(rectangleDictionary, new Point() { A = tmpA, B = tmpB });
				}
				tmpB++;
				if (tmpA > 1 && tmpB < w)
				{
					AddIfEmptyOrIncrement(rectangleDictionary, new Point() { A = tmpA, B = tmpB });
				}
				tmpA++;
				tmpB -= 2;
				if (tmpA > 1 && tmpA < h && tmpB > 1)
				{
					AddIfEmptyOrIncrement(rectangleDictionary, new Point() { A = tmpA, B = tmpB });
				}
				tmpB++;
				if (tmpA > 1 && tmpA < h && tmpB > 1 && tmpB < w)
				{
					AddIfEmptyOrIncrement(rectangleDictionary, new Point() { A = tmpA, B = tmpB });
				}
				tmpB++;
				if (tmpA > 1 && tmpA < h &&  tmpB < w)
				{
					AddIfEmptyOrIncrement(rectangleDictionary, new Point() { A = tmpA, B = tmpB });
				}
				tmpA++;
				tmpB -= 2;
				if (tmpA < h && tmpB > 1)
				{
					AddIfEmptyOrIncrement(rectangleDictionary, new Point() { A = tmpA, B = tmpB });
				}
				tmpB++;
				if (tmpA < h && tmpB > 1 && tmpB < w)
				{
					AddIfEmptyOrIncrement(rectangleDictionary, new Point() { A = tmpA, B = tmpB });
				}
				tmpB++;
				if (tmpA < h && tmpB < w)
				{
					AddIfEmptyOrIncrement(rectangleDictionary, new Point() { A = tmpA, B = tmpB });
				}
			}

			var countList = new List<long>();
			countList.Add(0);

			for(int i = 1; i < 10; i++)
			{
				countList.Add(rectangleDictionary.Count(keyValuePair => keyValuePair.Value == i));
			}

			countList[0] = (h - 2) * (w - 2) - countList.Sum();

			foreach(var i in countList)
			{
				Console.WriteLine(i);
			}
		}

		private static void AddIfEmptyOrIncrement(Dictionary<Point, int> dictionary, Point point)
		{
			if(dictionary.ContainsKey(point))
			{
				dictionary[point]++;
			}
			else
			{
				dictionary.Add(point, 1);
			}
		}

