#region Program
namespace Program
{
    #region Solver
    public class Solver
    {
        static IO.StreamScanner
        sc = new IO.StreamScanner(Console.OpenStandardInput());

        static readonly long offset = (long)1e10;

        Dictionary<long, int> map;

        int H;
        int W;
        int N;

        int[] a;
        int[] b;

        int[] ans;

        #region Solver
        public Solver()
        {
            H = sc.Integer();
            W = sc.Integer();
            N = sc.Integer();

            a = new int[N];
            b = new int[N];

            ans = new int[9];

            for (int i = 0; i < N; i++)
            {
                a[i] = sc.Integer();
                b[i] = sc.Integer();
            }

            for (int i = 0; i < ans.Length; i++) ans[i] = 0;
        }
        #endregion

        #region Solve
        public void Solve()
        {
            map = new Dictionary<long, int>();

            for (int i = 0; i < N; i++)
            {
                for (int j = -1; j < 2; j++)
                {
                    for (int k = -1; k < 2; k++)
                    {
                        int x = b[i] + k - 1;
                        int y = a[i] + j - 1;

                        if (inside(x, y))
                        {
                            int c;
                            long center = x * offset + y;
                            if (map.TryGetValue(center, out c)) map[center]++;
                            else map.Add(center, 1);
                        }
                    }
                }
            }

            foreach (var m in map) ans[m.Value - 1]++;

            Console.WriteLine(
                (long)(H - 2) * (long)(W - 2) - (long)map.Count);

            for (int i = 0; i < ans.Length; i++)
                Console.WriteLine(ans[i]);
        }
        #endregion

        #region inside
        public bool inside(int x, int y)
        {
            return 0 < x && x < W - 1 && 0 < y && y < H - 1;
        }
        #endregion
    }
    #endregion
}
