		{
			var cin = new Scanner2();
			long h = cin.Long();
			long w = cin.Long();
			int n = cin.Int();

			var ans = new long[10];
			ans[0] = (h - 2) * (w - 2);

			var dirs = new Tuple<int, int>[] {
				new Tuple<int, int>(0, 0),
				new Tuple<int, int>(1, 0),
				new Tuple<int, int>(-1, 0),
				new Tuple<int, int>(0, 1),
				new Tuple<int, int>(1, 1),
				new Tuple<int, int>(-1, 1),
				new Tuple<int, int>(0, -1),
				new Tuple<int, int>(1, -1),
				new Tuple<int, int>(-1, -1),
			};

