        {
            //SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
            Solve();
            //Out.Flush();
            Read();
        }
        static void Solve()
        {
            (long H, long W, long N) = Slice3<long>();
            var blacks = new HashSet<(long h, long w)>((int)N);
            for (var i = 0; i < N; ++i)
            {
                (long a, long b) = Slice2<long>();
                blacks.Add((a - 1, b - 1));
            }
            var used = new HashSet<(long h, long w)>((int)(N * 9));
            var dh = new long[] { -1, 0, 1, -1, 0, 1, -1, 0, 1 };
            var dw = new long[] { -1, -1, -1, 0, 0, 0, 1, 1, 1 };
            var ans = Enumerable.Repeat(0L, 10).ToArray();
            foreach(var b in blacks)
            {
                for (var i = 0; i < 9; ++i)
                {
                    var ch = b.h + dh[i];
                    var cw = b.w + dw[i];
                    if (ch <= 0 || H - 1 <= ch || cw <= 0 || W - 1 <= cw)
                        continue;
                    if (used.Contains((ch, cw)))
                        continue;
                    var cnt = 0L;
                    for (var j = 0; j < 9; ++j)
                    {
                        var sh = ch + dh[j];
                        var sw = cw + dw[j];
                        if (blacks.Contains((sh, sw)))
                            ++cnt;
                    }
                    used.Add((ch, cw));
                    ++ans[cnt];
                }
            }
            ans[0] = 0;
            ans[0] = (H - 2) * (W - 2) - ans.Sum();
            foreach (var a in ans)
                WriteLine(a);
        }
    }
}

