            int H = int.Parse(first[0]);
            int W = int.Parse(first[1]);
            int N = int.Parse(first[2]);

            // (y, x) -> count
            var pointToCount = new Dictionary<KeyValuePair<int, int>, int>();

            for (int i = 0; i < N; i++)
            {
                string[] split = Reader.ReadLine().Split(' ');
                int y = int.Parse(split[0]) - 1;
                int x = int.Parse(split[1]) - 1;

                for (int n = -2; n <= 0; n++)
                {
                    for (int m = -2; m <= 0; m++)
                    {
                        // 3x3の個数が数えられるのは[0, 0]～[H - 2, W - 2]の範囲内
                        if (y + n < 0 || H - 2 < y + n ||
                            x + m < 0 || W - 2 < x + m)
                        {
                            continue;
                        }

                        var p = new KeyValuePair<int, int>(y + n, x + m);
                        if (!pointToCount.ContainsKey(p))
                        {
                            pointToCount.Add(p, 0);
                        }

                        pointToCount[p]++;
                    }
                }
            }

            ulong[] counts = new ulong[10];
            foreach (var p in pointToCount)
            {
                if (p.Key.Key < H - 2 && p.Key.Value < W - 2)
                {
                    counts[p.Value]++;
                }
            }

            // 0のマスは(H - 2) * (W - 2) - （1以上のマスの数）
            counts[0] = ((ulong)H - 2) * ((ulong)W - 2);
            for (int i = 1; i < counts.Length; i++)
            {
                counts[0] -= counts[i];
            }

            for (int i = 0; i < counts.Length; i++)
            {
                Console.WriteLine(counts[i]);
            }

            Console.ReadKey();
        }
