// Snippet: IntParser
class IntParser {
    public string S;
    int Position;

    public int Next() {
        while (S[Position] == ' ') ++Position;
        var absoluteValue = 0;
        var negative = false;
        if (S[Position] == '-') {
            negative = true;
            ++Position;
        }
        while (Position != S.Length && char.IsDigit(S[Position]))
            absoluteValue = absoluteValue * 10 + (S[Position++] - '0');
        return negative ? -absoluteValue : absoluteValue;
    }
}

class D {
