        for (int i = 0; i < n; ++i) {
            var parser = new IntParser{S = Console.ReadLine()};
            black.Add(new Tuple<int, int>(
                parser.Next() - 1,
                parser.Next() - 1));
        }
        var nonZero = new HashSet<Tuple<int, int>>();
        foreach (var i in black)
            for (int j1 = i.Item1 - 2; j1 <= i.Item1; ++j1)
                if (0 <= j1 && j1 + 2 < h)
                    for (int j2 = i.Item2 - 2; j2 <= i.Item2; ++j2)
