                    var x = p[0] + dx[i] - 1;
                    var y = p[1] + dy[i] - 1;
                    if(isInside(x, y)){
                        area.Add(hash(x, y));
                    }
                }
            }

            var res = new int[10];
            foreach(var ag in area.GroupBy(x => x)){
                Console.WriteLine($"x = {ag.Key / 1000000}, y = {ag.Key % 1000000}, cnt = {ag.Count()}");
