class Program
{
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
    }
    static void Solve()
    {
        var H = sc.ReadInt();
        var W = sc.ReadInt();
        var N = sc.ReadInt();
        var Hs = new int[N];
        var Ws = new int[N];
        for (int i = 0; i < N; i++)
        {
            Hs[i] = sc.ReadInt();
            Ws[i] = sc.ReadInt();
        }
        var map = new HashMap<long, int>();
        var ans = new long[10];
        for (int k = 0; k < N; k++)
        {
            var h = Hs[k];
            var w = Ws[k];
            for (int i = 0; i < 3; i++)
            {
                for (int j = 0; j < 3; j++)
                {
                    var nh = h - i;
                    var nw = w - j;
                    if (1 <= nh && nh <= H - 2 && 1 <= nw && nw <= W - 2)
                    {
                        var key = nh * 1000000000L + nw;
                        map[key]++;
                    }
                }
            }
        }
        foreach (var p in map)
        {
            ans[p.Value]++;
        }
        ans[0] = (long)(H - 2) * (W - 2) - ans.Sum();
        foreach (var a in ans)
        {
            Console.WriteLine(a);
        }
    }
    class HashMap<K, V> : Dictionary<K, V> where V : new()
    {
        private V DefaltValue = new V();
        public HashMap() { }
        public HashMap(V defaultValue)
        {
            this.DefaltValue = new V();
        }
        new public V this[K i]
        {
            get
            {
                V v;
                return TryGetValue(i, out v) ? v : base[i] = this.DefaltValue;
            }
            set { base[i] = value; }
        }
    }
    static Scanner sc = new Scanner();
}
