    class Program
    {
        static public long[] Sarray() { return ReadLine().Split().Select(long.Parse).ToArray(); }
        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }
        static long Mod = (long)1e9 + 7;
        static void Main(string[] args)
        {
            SetOut(new StreamWriter(OpenStandardOutput()) { AutoFlush = false });
            Solve();
            Out.Flush();
            Read();
        }
        static long p2l(long h, long w) => h * W + w;//0index
        static (long, long) l2p(long l) => (l / W, l % W);
        static long W;
        static void Solve()
        {
            var HWN = Sarray();
            var H = HWN[0];
            W = HWN[1];
            var N = HWN[2];
            var bMasu = new HashSet<long>();
            for (var i = 0; i < N; ++i)
            {
                var ab = Sarray();
                bMasu.Add(p2l(ab[0] - 1, ab[1] - 1));
            }
            var used = new HashSet<long>();
            var zah = new long[] { -1, 0, 1, -1, 0, 1, -1, 0, 1 };
            var zaw = new long[] { -1, -1, -1, 0, 0, 0, 1, 1, 1 };

            var nums = new long[10];
            foreach (var b in bMasu)
            {
                var (h, w) = l2p(b);
                for (var i = 0; i < 9; ++i)//中心
                {
                    var ch = h + zah[i];
                    var cw = w + zaw[i];
                    if (0 < ch && ch < H - 1 && 0 < cw && cw < W - 1 && !used.Contains(p2l(ch, cw)))
                    {
                        var cnt = 0;
                        for (var j = 0; j < 9; ++j)//フィルタ
                        {
                            var hh = ch + zah[j];
                            var ww = cw + zaw[j];
                            if (bMasu.Contains(p2l(hh, ww))) ++cnt;
                        }
                        ++nums[cnt];
                    }
                    used.Add(p2l(ch, cw));
                }
            }
            var square = (H - 2) * (W - 2);
            nums[0] = square - nums.Skip(1).Sum();
            foreach (var n in nums)
                WriteLine(n);
        }
    }
}

