public class Hello
{
    public static void Main()
    {
        var d = new Dictionary<ulong, int>();
        string[] line = Console.ReadLine().Trim().Split(' ');
        var h = int.Parse(line[0]);
        var w = int.Parse(line[1]);
        var n = int.Parse(line[2]);
        for (int i = 0; i < n; i++)
        {
            line = Console.ReadLine().Trim().Split(' ');
            var a = int.Parse(line[0]) - 1;
            var b = int.Parse(line[1]) - 1;
            putDict(d, h, w, a, b);
        }
        var ret = new long[10];
        var rsum = 0;
        foreach (var x in d)
        {
            ret[x.Value]++;
            rsum++;
        }
        ret[0] = (long)(w - 2) * (h - 2) - rsum;
        foreach (var x in ret) Console.WriteLine(x);
    }
    public static void putDict(Dictionary<ulong, int> d, int h, int w, int a, int b)
    {
        if (a - 2 >= 0)
        {
            if (b - 2 >= 0) putDict2(d, a - 2, b - 2);
            if (b - 1 >= 0 && b + 1 < w) putDict2(d, a - 2, b - 1);
            if (b + 2 < w) putDict2(d, a - 2, b);
        }
        if (a - 1 >= 0 && a + 1 < h)
        {
            if (b - 2 >= 0) putDict2(d, a - 1, b - 2);
            if (b - 1 >= 0 && b + 1 < w) putDict2(d, a - 1, b - 1);
            if (b + 2 < w) putDict2(d, a - 1, b);
        }
        if (a + 2 < h)
        {
            if (b - 2 >= 0) putDict2(d, a, b - 2);
            if (b - 1 >= 0 && b + 1 < w) putDict2(d, a, b - 1);
            if (b + 2 < w) putDict2(d, a, b);
        }
    }
    public static void putDict2(Dictionary<ulong, int> d, int a, int b)
    {
        var nk = (ulong)a * 100000000000 + (ulong)b;
        if (d.ContainsKey(nk)) d[nk]++;
        else d[nk] = 1;
    }
}

