        long[] cnt = new long[10];
        Points = new xy[N];
        for(int i = 0; i < N; i++)
        {
            s = Console.ReadLine().Split(' ');
            Points[i] = new xy(int.Parse(s[0]), int.Parse(s[1]));
        }
        int[] q = new int[] { -2, -1, 0, -2, -1, 0, -2, -1, 0 };
        int[] w = new int[] { -2, -2, -2, -1, -1, -1, 0, 0, 0 };
        for(int i = 0; i < N; i++)
        {
            for(int j = 0; j < 9; j++)
