	b int
}

// Datas :
type Datas []Data

func (p Datas) Len() int {
	return len(p)
}

func (p Datas) Swap(i, j int) {
	p[i], p[j] = p[j], p[i]
}

func (p Datas) Less(i, j int) bool {
	if p[i].a == p[j].a {
		return p[i].b < p[j].b
	}
	return p[i].a < p[j].a
}

func main() {
	sc.Split(bufio.ScanWords)
	h := getInt()
	w := getInt()
	n := getInt()
	P := make(Datas, n*9)
	for i := 0; i < n; i++ {
		P[i].b = getInt() - 1
		P[i].a = getInt() - 1
	}

	x := [8]int{-1, 0, 1, -1, 1, -1, 0, 1}
	y := [8]int{-1, -1, -1, 0, 0, 1, 1, 1}
	idx := n
	for i := 0; i < n; i++ {
		for j := 0; j < 8; j++ {
