			i++
			continue
		}
		xx = P[i].a
		yy = P[i].b
		cnt = 0
		for ; ; i++ {
			if i >= len(P) {
				break
			}
			if (xx == P[i].a) && (yy == P[i].b) {
				cnt++
			} else {
				break
			}
		}
		ans[cnt]++
	}

