func solve() {
	H, W, N := nextInt64(), nextInt64(), nextInt()
	a, b := make([]int64, N), make([]int64, N)
	for i := 0; i < N; i++ {
		a[i], b[i] = nextInt64(), nextInt64()
	}
	_, _ = H, W
	ans := make([]int64, 10)
	ans[0] = (H - 2) * (W - 2)
	B := make(map[point]struct{})
	for i := 0; i < N; i++ {
		for dh := int64(-2); dh <= 0; dh++ {
			for dw := int64(-2); dw <= 0; dw++ {
				sh := a[i] + dh
				sw := b[i] + dw
				if 1 <= sh && sh <= H-2 && 1 <= sw && sw <= W-2 {
					nb := 0
					for ddh := int64(0); ddh < 3; ddh++ {
						for ddw := int64(0); ddw < 3; ddw++ {
							h := sh + ddh
							w := sw + ddw
							if _, ok := B[point{h, w}]; ok {
								nb++
							}
						}
					}
					ans[nb]--
					ans[nb+1]++
				}
			}
		}
		B[point{a[i], b[i]}] = struct{}{}
	}
	for _, n := range ans {
		out(n)
	}
}

