func calc(W int, A []int, p [][]int) {
	w := 0
	v := 0
	q := []int{0, 0, 0}
	for w = 0; w < 2; w++ {
		for i := 0; i < 3; i++ {
			if len(p[i]) > 0 && w == p[i][0] {
				q[w+1]++
				p[i] = p[i][1:]
			}
		}
	}
	for {
		q[0], q[1], q[2] = q[1], q[2], 0
		if q[0]+q[1]+q[2] == 0 {
			w = W
			for i := 0; i < 3; i++ {
				if len(p[i]) > 0 && p[i][0] < w {
					w = p[i][0]
				}
			}
		}
		if w >= W {
			break
		}
		for i := 0; i < 3; i++ {
			if len(p[i]) > 0 && w == p[i][0] {
				q[2]++
				p[i] = p[i][1:]
			}
		}
		A[q[0]+q[1]+q[2]]++
		w++
		v++
	}
	A[0] += w - 2 - v
}

