auto parse( Range )( Range input )
if( isInputRange!Range && is( ElementType!Range == string ) )
{
	auto hwn = input.front.split.to!( long[] );
	auto abs = new long[ 2 ][ hwn[ 2 ] ];
	foreach( ref ab; abs )
	{
		input.popFront;
		ab = input.front.split.to!( long[] );
	}
	return tuple( hwn[ 0 ], hwn[ 1 ], abs );
}

auto solve( long h, long w, long[ 2 ][] abs )
{
	auto cs = new long[ 2 ][ abs.length * 9 ];
	auto ci = 0L;
	foreach( ab; abs )
	{
		auto ym = min( h - 2, ab[ 0 ] );
		auto xm = min( w - 2, ab[ 1 ] );
		for( auto y = max( 1L, ab[ 0 ] - 2 ); y <= ym; y++ )
		{
			for( auto x = max( 1L, ab[ 1 ] - 2 ); x <= xm; x++ )
			{
				cs[ ci ] = [ y, x ];
				ci++;
			}
		}
	}
	cs.length = ci;
	cs.sort();

	auto anss = new long[ 10 ];
	anss[ 0 ] = ( h - 2 ) * ( w - 2 );
	foreach( g; cs.group )
	{
		anss[ 0 ]--;
		anss[ g[ 1 ] ]++; 
	}
	return anss.to!( string[] ).join( "\n" );
}

