		scanf ("%lld%lld", &x, &y);
		add (x, y);
	}
	ans[0] = (h - 2) * (w - 2);
	for (map <LL, LL>::iterator it = mp.begin(); it != mp.end(); ++it)
		++ans[it -> second], --ans[0];
	for (int i = 0; i <= 9; ++i)
		printf ("%lld\n", ans[i]);
	return 0;
}

