import sys
from sys import stdin
from collections import defaultdict
from copy import copy
input = stdin.readline


def solve(H, W, N, points):
    ans = [0] * 10              #  3x3のうちマスがi個だけ黒いパタンの数
    checked = set()
    ccc = copy(points)

    for k, v in points.items():
        for x, y in v:
            for xx in [-2, -1, 0]:
                for yy in [-2, -1, 0]:
                    lbx = x + xx
                    lby = y + yy
                    if (lbx, lby) not in checked:
                        checked.add((lbx, lby))
                        if 1 <= lbx and lbx+2 <= W and 1 <= lby and lby+2 <= H:
                            res = 0
                            for ddx in [0, 1, 2]:
                                t = ccc[lbx + ddx]
                                if (lbx + ddx, lby) in t:
                                    res += 1
                                if (lbx + ddx, lby + 1) in t:
                                    res += 1
                                if (lbx + ddx, lby + 2) in t:
                                    res += 1
                            ans[res] += 1

    total = (W-2) * (H-2)         #  3x3の正方形の全パタン
    ans[0] = total - sum(ans[1:]) #  1マスも塗られていないのは、全パタン数-一つでも塗ってあるパタン数
    return ans


def main(args):
    points = defaultdict(set)

    H, W, N = map(int, input().split())
    for _ in range(N):
        y, x = map(int, input().split())
        points[x].add((x, y))

    ans = solve(H, W, N, points)
    print(*ans, sep='\n')


