from collections import deque
import numpy as np


def solve():
    H, W, N = map(int, input().split())
    # print("H, W", H, W)
    # print("N", N)

    blacks = deque()
    for _ in range(N):
        blacks.append(tuple(map(int, input().split())))

    TABLE = deque()
    for _ in range(H + 1):
        TABLE.append(0)

    dx = W
    for pos in blacks:
        x = dx - pos[1]
        y = pos[0]
        # print(y, x)
        TABLE[y] = TABLE[y] | 2**x

    RES_TABLE = [0 for _ in range(10)]
    fLAG_DICT = {0: 0, 1: 1, 2: 1, 3: 2, 4: 1, 5: 2, 6: 2, 7: 3}
    for y in range(1, H + 1, 1):
        if y + 2 > H:
            break

        lis = []
        top_middle_bottom = []
        for y2 in range(y, y + 3):
            line = TABLE[y2]
            lines = []
            for head in range(W - 1, -1, -1):
                tail = (head - 2)
                if tail >= 0:
                    key = line >> tail & 0b111
                    lines.append(fLAG_DICT[key])
            top_middle_bottom.append(np.array(lines))

        total = sum(top_middle_bottom)
        for t in total:
            RES_TABLE[t] += 1

    return RES_TABLE


if __name__ == '__main__':
    res = solve()
    for lis in res:
        print(lis)

