import sys
from sys import stdin
from bisect import bisect_left, bisect_right
from operator import itemgetter
from collections import defaultdict
input = stdin.readline


def solve(H, W, N, points, x_lut):
    ans = [0] * 10              #  3x3のうちマスがi個だけ黒いパタンの数
    checked = set()

    dx = [-2, -1, 0]
    dy = [-2, -1, 0]

    for x, y in points:
        for xx in dx:
            for yy in dy:
                lbx = x + xx
                lby = y + yy
                if (lbx, lby) not in checked:
                    checked.add((lbx, lby))
                    if 1 <= lbx <= W and lbx+2 <= W and 1 <= lby <= H and lby+2 <= H:
                        res = 0
                        if (lbx, lby) in x_lut[lbx]:
                            res += 1
                        if (lbx, lby + 1) in x_lut[lbx]:
                            res += 1
                        if (lbx, lby + 2) in x_lut[lbx]:
                            res += 1
                        if (lbx + 1, lby) in x_lut[lbx + 1]:
                            res += 1
                        if (lbx + 1, lby + 1) in x_lut[lbx + 1]:
                            res += 1
                        if (lbx + 1, lby + 2) in x_lut[lbx + 1]:
                            res += 1
                        if (lbx + 2, lby) in x_lut[lbx + 2]:
                            res += 1
                        if (lbx + 2, lby + 1) in x_lut[lbx + 2]:
                            res += 1
                        if (lbx + 2, lby + 2) in x_lut[lbx + 2]:
                            res += 1
                        ans[res] += 1

    total = (W-2) * (H-2)         #  3x3の正方形の全パタン
    ans[0] = total - sum(ans[1:]) #  1マスも塗られていないのは、全パタン数-一つでも塗ってあるパタン数
    return ans


def main(args):
    points = []
    x_lut = defaultdict(set)

    H, W, N = map(int, input().split())
    for _ in range(N):
        y, x = map(int, input().split())
        points.append((x, y))
        x_lut[x].add((x, y))

    # points.sort()
    ans = solve(H, W, N, points, x_lut)
    print(*ans, sep='\n')


if __name__ == '__main__':
    main(sys.argv[1:])

