import numpy as np

def solve(h,w,n,black_list):
  count = []
  for idx, (a,b) in enumerate(black_list):
    left = max(0, b-3)
    top = max(0, a-3)
    right = min(w, b+3)
    bottom = min(h, a+3)
    for row in range(top, a):
      if row+2 >= h:
        continue
      for col in range(left, b):
        if col+2 >= w:
          continue
        count.append(row*h+col)

  set_count = set(count)
  count = np.array(count)
  ans = np.zeros(len(set_count))
  for idx,i in enumerate(set_count):
    ans[idx] = np.count_nonzero(count==i)

  ret = [(h-2)*(w-2)-len(set_count)]
  for i in range(1, 10):
    ret.append(np.count_nonzero(ans==i))
  return ret

