import sys
from sys import stdin
input = stdin.readline


def solve(H, W, N, points):
    ans = [0] * 10              #  3x3のうちマスがi個だけ黒いパタンの数
    checked = set()

    dx = [-2, -1, 0]
    dy = [-2, -1, 0]

    for x, y in points:
        for xx in dx:
            for yy in dy:
                lbx = x + xx
                lby = y + yy
                if (lbx, lby) not in checked:
                    checked.add((lbx, lby))
                    if 1 <= lbx <= W and lbx+2 <= W and 1 <= lby <= H and lby+2 <= H:
                        res = 0
                        for ddx in [0, 1, 2]:
                            t = points[lbx + ddx]
                            if (lbx + ddx, lby) in t:
                                res += 1
                            if (lbx + ddx, lby + 1) in t:
                                res += 1
                            if (lbx + ddx, lby + 2) in t:
                                res += 1
                        ans[res] += 1

    total = (W-2) * (H-2)         #  3x3の正方形の全パタン
    ans[0] = total - sum(ans[1:]) #  1マスも塗られていないのは、全パタン数-一つでも塗ってあるパタン数
    return ans


def main(args):
    points = dict()

    H, W, N = map(int, input().split())
    for _ in range(N):
        y, x = map(int, input().split())
        points[x].add((x, y))

    ans = solve(H, W, N, points)
    print(*ans, sep='\n')


