    class TwoDimNode:
        def __init__(self, x=None, y=None, parent=None, left=None, right=None):
            self.x = x
            self.y = y
            self.parent = parent
            self.left = left
            self.right = right
            self.flag = True

    class TwoDimTree:
        def __init__(self):
            self.nil = TwoDimNode()
            self.nil.parent = self.nil
            self.nil.left = self.nil
            self.nil.right = self.nil
            self.root = self.nil

        def insert(self, x, y):
            trailer = self.nil
            pos = self.root
            depth = 0
            while pos != self.nil:
                trailer = pos
                if depth % 2 == 0:
                    k, pos_k = x, pos.x
                else:
                    k, pos_k = y, pos.y
                if k < pos_k:
                    pos = pos.left
                elif pos_k < k:
                    pos = pos.right
                else:
                    pos.flag ^= pos.flag
                    pos = pos.left if pos.flag else pos.right
                depth += 1
            inserted_node = TwoDimNode(x, y, trailer, self.nil, self.nil)
            # trailer の depth
            depth -= 1
            if depth % 2 == 0:
                k, trailer_k = x, trailer.x
            else:
                k, trailer_k = y, trailer.y
            # tree is empty
            if trailer == self.nil:
                self.root = inserted_node
            elif k < trailer_k or (k == trailer_k and trailer.flag):
                trailer.left = inserted_node
            else:
                trailer.right = inserted_node

