#!/usr/bin/env pypy3

import collections
import itertools


MAX_J = 9
SQUARE_SIZE = 3


class Board(object):

    def __init__(self, height, width):
        self.height = height
        self.width = width
        self.squares = collections.Counter()

    def inside_board(self, r, c):
        return 0 <= r < self.height - 2 and 0 <= c < self.width - 2

    def paint_cell(self, r, c):
        for k, l in itertools.product(range(SQUARE_SIZE), repeat=2):
            sr, sc = r - k, c - l
            if self.inside_board(sr, sc):
                self.squares[(sr, sc)] += 1

    def summarize(self):
        ans = [0 for _ in range(MAX_J + 1)]
        for v in self.squares.values():
            if 1 <= v <= MAX_J:
                ans[v] += 1
        ans[0] = (self.height - 2) * (self.width - 2) - sum(ans[1:])
        return ans


def main():
    h, w, n = map(int, input().split())
    board = Board(h, w)
    for _ in range(n):
        a, b = map(lambda x: int(x) - 1, input().split())
        board.paint_cell(a, b)
    ans = board.summarize()
    print(*ans, sep="\n")


if __name__ == '__main__':
    main()

