    class TwoDimNode:
        def __init__(self, x=None, y=None, parent=None, left=None, right=None):
            self.x = x
            self.y = y
            self.parent = parent
            self.left = left
            self.right = right
            self.flag = True

    class TwoDimTree:
        def __init__(self):
            self.nil = TwoDimNode()
            self.nil.parent = self.nil
            self.nil.left = self.nil
            self.nil.right = self.nil
            self.root = self.nil

        def preorder_traverse(self, node=None):
            if node is None:
                node = self.root
            if node != self.nil:
                print(f"({node.x},{node.y})", end=' ')
                self.preorder_traverse(node=node.left)
                self.preorder_traverse(node=node.right)

        def post_order_traverse(self, node=None):
            if node is None:
                node = self.root
            if node != self.nil:
                self.post_order_traverse(node=node.left)
                self.post_order_traverse(node=node.right)
                print(f"({node.x},{node.y})", end=' ')

        def insert(self, x, y):
            trailer = self.nil
            pos = self.root
            depth = 0
            while pos != self.nil:
                trailer = pos
                if depth % 2 == 0:
                    k, pos_k = x, pos.x
                else:
                    k, pos_k = y, pos.y
                if k < pos_k:
                    pos = pos.left
                elif pos_k < k:
                    pos = pos.right
                else:
                    pos.flag ^= pos.flag
                    pos = pos.left if pos.flag else pos.right
                depth += 1
            inserted_node = TwoDimNode(x, y, trailer, self.nil, self.nil)
            # trailer の depth
            depth -= 1
            if depth % 2 == 0:
                k, trailer_k = x, trailer.x
            else:
                k, trailer_k = y, trailer.y
            # tree is empty
            if trailer == self.nil:
                self.root = inserted_node
            elif k < trailer_k or (k == trailer_k and trailer.flag):
                trailer.left = inserted_node
            else:
                trailer.right = inserted_node

        def two_dim_search(self, sx, tx, sy, ty, node=None, depth=0):
            buf = []
            if node is None:
                node = self.root
            # print(f"{node.x} {node.y}")
            if depth % 2 == 0:
                if node.left != self.nil and sx <= node.x:
                    buf += self.two_dim_search(sx, tx, sy, ty, node.left, depth+1)
                if sx <= node.x <= tx and sy <= node.y <= ty:
                    buf.append((node.x, node.y))
                if node.right != self.nil and tx >= node.x:
                    buf += self.two_dim_search(sx, tx, sy, ty, node.right, depth+1)
            else:
                if node.left != self.nil and sy <= node.y:
                    buf += self.two_dim_search(sx, tx, sy, ty, node.left, depth+1)
                if sx <= node.x <= tx and sy <= node.y <= ty:
                    buf.append((node.x, node.y))
                if node.right != self.nil and ty >= node.y:
                    buf += self.two_dim_search(sx, tx, sy, ty, node.right, depth+1)
            return buf

