fn main() {
    let mut scanner = Scanner::new(stdin());
    let (h, w, n) = scanner.read_three::<i64>().unwrap();
    let mut grid_counts = HashMap::new();
    for _ in 0..n {
        let (a, b) = scanner.read_two::<i64, i64>().unwrap();
        update(a, b, &mut grid_counts, h, w);
    }
    let mut counts = vec![0; 10];
    let mut sum = 0;
    for c in grid_counts.values() {
        counts[*c] += 1;
