    for i in 0..10 {
        println!("{}", counts[i]);
    }
}

fn update(x: i64, y: i64, grid_counts: &mut HashMap<(i64, i64), usize>, h: i64, w: i64) {
    for i in 0..3 {
        for j in 0..3 {
            let x_new = x - i;
            let y_new = y - j;
            if x_new <= 0 || x_new > h - 2 || y_new <= 0 || y_new > w - 2 {
                continue;
            }
            let key = (x_new, y_new);
            if grid_counts.contains_key(&key) {
                *grid_counts.get_mut(&key).unwrap() += 1;
            } else {
                grid_counts.insert(key, 1);
            }
        }
    }
}

pub struct Scanner<R> {
    reader: BufReader<R>,
    buffer: String,
}
impl<R> Scanner<R>
where
    R: Read,
{
    pub fn new(inner: R) -> Scanner<R> {
        let reader = BufReader::new(inner);
        let buffer = String::new();
        Scanner {
            reader: reader,
            buffer: buffer,
        }
    }
    pub fn with_capacity(capacity: usize, inner: R) -> Scanner<R> {
        let reader = BufReader::with_capacity(capacity, inner);
        let buffer = String::new();
        Scanner {
            reader: reader,
            buffer: buffer,
        }
    }
    pub fn read_line(&mut self) -> BoxResult<String> {
        self.reader.read_line(&mut self.buffer)?;
        let cloned = self.buffer.trim().to_string();
        self.buffer.clear();
        Ok(cloned)
    }
    pub fn read<T>(&mut self) -> BoxResult<T>
    where
        T: FromStr,
        T::Err: std::fmt::Debug,
        T::Err: std::error::Error,
        T::Err: 'static,
    {
        self.reader.read_line(&mut self.buffer)?;
        let parsed = self.buffer.trim().parse()?;
        self.buffer.clear();
        Ok(parsed)
    }
    pub fn read_two<T, U>(&mut self) -> BoxResult<(T, U)>
    where
        T: FromStr,
        T: Copy,
        T::Err: std::fmt::Debug,
        T::Err: std::error::Error,
        T::Err: 'static,
        U: FromStr,
        U: Copy,
        U::Err: std::fmt::Debug,
        U::Err: std::error::Error,
        U::Err: 'static,
    {
        self.reader.read_line(&mut self.buffer)?;
        let (a, b) = {
            let params = self.buffer.trim().split_whitespace().collect::<Vec<_>>();
            let a = params[0].parse()?;
            let b = params[1].parse()?;
            (a, b)
        };
        self.buffer.clear();
        Ok((a, b))
    }
    pub fn read_three<T>(&mut self) -> BoxResult<(T, T, T)>
    where
        T: FromStr,
        T: Copy,
        T::Err: std::fmt::Debug,
        T::Err: std::error::Error,
        T::Err: 'static,
    {
        let nums = self.read_vector()?;
        Ok((nums[0], nums[1], nums[2]))
    }
    pub fn read_vector<T>(&mut self) -> BoxResult<Vec<T>>
    where
        T: FromStr,
        T::Err: std::fmt::Debug,
        T::Err: std::error::Error,
        T::Err: 'static,
    {
        self.reader.read_line(&mut self.buffer)?;
        let parsed_vec = self
            .buffer
            .trim()
            .split_whitespace()
            .map(|s| s.parse())
            .collect::<Result<Vec<_>, _>>()?;
        self.buffer.clear();
        Ok(parsed_vec)
    }
    pub fn read_matrix<T>(&mut self, lines: u64) -> BoxResult<Vec<Vec<T>>>
    where
        T: FromStr,
        T::Err: std::fmt::Debug,
        T::Err: std::error::Error,
        T::Err: 'static,
    {
        let mut parsed_matrix = vec![];
        for _ in 0..lines {
            self.reader.read_line(&mut self.buffer)?;
            parsed_matrix.push(
                self.buffer
                    .trim()
                    .split_whitespace()
                    .map(|s| s.parse())
                    .collect::<Result<Vec<_>, _>>()?,
            );
            self.buffer.clear();
        }
        Ok(parsed_matrix)
    }
    pub fn read_chars(&mut self) -> BoxResult<Vec<char>> {
        self.reader.read_line(&mut self.buffer)?;
        let chars = self.buffer.trim().chars().collect::<Vec<_>>();
        self.buffer.clear();
        Ok(chars)
    }
}

use std::io::prelude::*;

fn input<T>() -> T
where
    T: std::str::FromStr,
{
    let stdin = std::io::stdin();
    let token: String = stdin
        .lock()
        .bytes()
        .map(|c| c.unwrap() as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().unwrap()
}

fn main() {
    let h: i64 = input();
    let w: i64 = input();
    let n: usize = input();
    let ab: Vec<(i64, i64)> = (0..n)
        .map(|_| {
            let a = input();
            let b = input();
            (a, b)
        })
        .collect();

    let mut m = std::collections::HashMap::new();
    for (a, b) in ab {
        for i in 0..3 {
            for j in 0..3 {
                let (p, q) = (a - i, b - j);
                if p > 0 && q > 0 && p + 2 <= h && q + 2 <= w {
                    let e = m.entry((p, q)).or_insert(0);
                    *e += 1;
                }
            }
        }
    }

    let mut u = vec![0; 10];
    for (_, v) in m {
        u[v] += 1;
    }
    let sum: i64 = u.iter().sum();
    u[0] = (h - 2) * (w - 2) - sum;

    for i in u {
        println!("{}", i);
    }
}

use std::io::*;

fn main() {
    let mut s: String = String::new();
    std::io::stdin().read_to_string(&mut s).ok();
    let mut itr = s.trim().split_whitespace();
    let h: usize = itr.next().unwrap().parse().unwrap();
    let w: usize = itr.next().unwrap().parse().unwrap();
    let n: usize = itr.next().unwrap().parse().unwrap();

    let dx: Vec<isize> = [0, 0, -1, 0, 1, -1, 1, -1, 1].to_vec();
    let dy: Vec<isize> = [0, 1, 0, -1, 0, -1, 1, 1, -1].to_vec();
    let mut pos = std::collections::HashMap::new();

    for _ in 0..n {
        let b: usize = itr.next().unwrap().parse::<usize>().unwrap() - 1;
        let a: usize = itr.next().unwrap().parse::<usize>().unwrap() - 1;
        for i in 0..9 {
            let nx = a as isize + dx[i];
            let ny = b as isize + dy[i];
            if 0 < nx && nx < w as isize - 1 && 0 < ny && ny < h as isize - 1 {
                let p = pos.entry((ny, nx)).or_insert(0);
                *p += 1;
            }
        }
    }

    let mut ans = vec![0; 10];
    let mut sum = (h - 2) * (w - 2);
    for (_, v) in pos {
        ans[v] += 1;
        sum -= 1;
    }
    ans[0] = sum;
    let mut out = Vec::new();
    for i in 0..10 {
        writeln!(out, "{}", ans[i]).ok();
    }
    stdout().write_all(&out).unwrap();
}

