fn main(){
    input!{
        H: usize,
        W: usize,
        N: usize,
        AB: [(usize, usize); N],
    }
    // それぞれの黒マスを含む3x3全てについてmapを用いて集計
    let mut map = BTreeMap::new();
    for i in 0..N{
        let (a,b) = AB[i];
        for dh in 0..3{
            for dw in 0..3{
                // if 0<a-dh && a-dh<=H-2 && 0<b-dw && b-dw<=W-2{
                if a>dh && a<=H-2+dh && b>dw && b<=W-2+dw{
                    *map.entry((a-dh,b-dw)).or_insert(0) += 1;
                }
            }
        }
    }
    // 黒をいくつ含むか、0〜9まで集計
    let mut ans = [0 as u64; 10];
    let mut total = 0;
    for m in map{
        let ((_a,_b),v) = m;
        ans[v] += 1;
        total += 1;
    }
    // 0個は、全体 - 1つでも含むものの合計
    ans[0] = (H as u64 -2)*(W as u64 -2) - total;

    for i in 0..10{
        println!("{}", ans[i]);
    }
}

