        for i in 0..3 {
            for j in 0..3 {
                if a < i || b < j || a-i+2 > h-1 || b-j+2 > w-1 {
                    continue;
                }
                let mut count = 0;
                for k in 0..3 {
                    for l in 0..3 {
                        let x = a+k-i;
                        let y = b+l-j;
                        if set.contains(&(x,y)) {
                            count += 1;
                        }
                    }
                }
                vec[count] += 1;
            }
        }
    }
    for i in 1..10 {
        vec[i] /= i;
    }
    let sum = vec.iter().sum::<usize>();
    println!("{}", (h-2)*(w-2)-sum);
    for i in 1..10 {
        println!("{}", vec[i]);
    }
}

