use std::collections::{HashMap, VecDeque};
fn corners_around(h: i64, w: i64, n: &(i64, i64)) -> Vec<(i64, i64)> {
    let mut res = Vec::new();
    let (c_y, c_x) = n;
    for diff_x in -3..0 {
        for diff_y in -3..0 {
            let sx = c_x + diff_x;
            let sy = c_y + diff_y;
            let ex = sx + 3;
            let ey = sy + 3;
            if sx >= 0 && ex <= w && sy >= 0 && ey <= h {
                res.push((sy, sx));
            }
        }
    }
    res
}

fn solve(h: i64, w: i64, ns: &[(i64, i64)]) -> VecDeque<u64> {
    let mut res_map = HashMap::new();
    for n in ns {
        let corners = corners_around(h, w, n);
        for c in corners {
            res_map.entry(c).and_modify(|c| *c += 1).or_insert(1);
        }
    }

    let mut res = VecDeque::new();
    for i in 1..10 {
        let n = res_map
            .values()
            .fold(0, |acc, x| if *x == i { acc + 1 } else { acc });

        res.push_back(n as u64)
    }
    let total_rect = (h - 2) * (w - 2);
    let remain = total_rect - res.iter().fold(0, |acc, n| acc + n) as i64;
    res.push_front(remain as u64);
    res
}

fn main() {
    input! {h: i64, w: i64, n:usize, ns: [(i64, i64); n]};
    let result = solve(h, w, &ns);
    for i in result {
        println!("{}", i);
    }
}

