fn main() {
    let (r, w, e) = (std::io::stdin(), std::io::stdout(), std::io::stderr());
    let mut io = IO::new(r.lock(), w.lock(), e.lock());

    let (h, w, n) = (io.read::<i64>(), io.read::<i64>(), io.read::<usize>());

    let mut mp = HashMap::new();
    for _ in 0..n {
        let (a, b) = (io.read::<i64>(), io.read::<i64>());
        let d: Vec<(i64, i64)> = vec![
            (-1, -1),
            (-1, 0),
            (-1, 1),
            (0, -1),
            (0, 0),
            (0, 1),
            (1, -1),
            (1, 0),
            (1, 1),
        ];

        for &dd in d.iter() {
            let na = a + dd.0;
            let nb = b + dd.1;
            if 1 < na && 1 < nb && na < h && nb < w {
                *mp.entry((na, nb)).or_insert(0) += 1;
            }
        }
    }
    let mut anss = vec![0; 10];
    for (k, &v) in mp.iter() {
        anss[v] += 1;
    }
    anss[0] = (h - 2) * (w - 2) - anss.iter().fold(0, |sum, x| sum + x);
    for &a in anss.iter() {
        io.writeln(a);
    }
}

