    ans[0] = (h - 2) * (w - 2);
    for d in &data {
        let y = d.0;
        let x = d.1;
        for offset_x in -1..2 {
            for offset_y in -1..2 {
                if x + offset_x - 1 <= 0
                    || y + offset_y - 1 <= 0
                    || x + offset_x + 1 > w as isize
                    || y + offset_y + 1 > h as isize
