#![allow(non_snake_case)]
#![allow(unused_variables)]
#![allow(dead_code)]

fn main() {
    let (H, W, N): (i64, i64, usize) = {
        let mut line: String = String::new();
        std::io::stdin().read_line(&mut line).unwrap();
        let mut iter = line.split_whitespace();
        (
            iter.next().unwrap().parse().unwrap(),
            iter.next().unwrap().parse().unwrap(),
            iter.next().unwrap().parse().unwrap(),
        )
    };
    let (a, b): (Vec<i64>, Vec<i64>) = {
        let (mut a, mut b) = (vec![], vec![]);
        for _ in 0..N {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            let mut iter = line.split_whitespace();
            a.push(iter.next().unwrap().parse().unwrap());
            b.push(iter.next().unwrap().parse().unwrap());
        }
        (a, b)
    };

    let p = (0..N)
        .map(|i| (a[i], b[i]))
        .collect::<std::collections::HashSet<_>>();
    let mut dp = vec![0; 10];
    for k in 0..N {
        let (y, x) = (a[k], b[k]);
        for u in std::cmp::max(1, y - 2)..(std::cmp::min(H - 2, y) + 1) {
            for l in std::cmp::max(1, x - 2)..(std::cmp::min(W - 2, x) + 1) {
                dp[(u..(u + 3))
                    .map(|i| (l..(l + 3)).filter(|&j| p.contains(&(i, j))).count())
                    .sum::<usize>()] += 1;
            }
        }
    }
    for i in 1..10 {
        dp[i] /= i as i64;
    }
    let ans = (0..10)
        .map(|i| {
            if i == 0 {
                ((H - 2) * (W - 2) - dp.iter().sum::<i64>()).to_string()
            } else {
                dp[i].to_string()
            }
        })
        .collect::<Vec<_>>()
        .join("\n");

    println!("{}", ans);
}

use std::collections::HashMap;

#[allow(unused_macros)]
macro_rules! scan {
    () => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.trim().to_string()
        }
    };
    (;;) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.trim().split_whitespace().map(|s| s.to_string()).collect::<Vec<String>>()
        }
    };
    (;;$n:expr) => {
        {
            (0..$n).map(|_| scan!()).collect::<Vec<_>>()
        }
    };
    ($t:ty) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.trim().parse::<$t>().unwrap()
        }
    };
    ($($t:ty),*) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            let mut iter = line.split_whitespace();
            (
                $(iter.next().unwrap().parse::<$t>().unwrap(),)*
            )
        }
    };
    ($t:ty;;) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.split_whitespace()
                .map(|t| t.parse::<$t>().unwrap())
                .collect::<Vec<_>>()
        }
    };
    ($t:ty;;$n:expr) => {
        (0..$n).map(|_| scan!($t;;)).collect::<Vec<_>>()
    };
    ($t:ty; $n:expr) => {
        (0..$n).map(|_|
                    scan!($t)
        ).collect::<Vec<_>>()
    };
    ($($t:ty),*; $n:expr) => {
        (0..$n).map(|_|
                    scan!($($t),*)
        ).collect::<Vec<_>>()
    };
}

fn main() {
    let (h, w, n) = scan!(usize, usize, usize);
    let mut m: HashMap<_, _> = [(0, (h - 3 + 1) * (w - 3 + 1))].iter().cloned().collect();
    let mut m1: HashMap<(usize, usize), bool> = HashMap::new();

    for _ in 0..n {
        let (mut x, mut y) = scan!(usize, usize);
        x -= 1;
        y -= 1;
        for i in 0..3 {
            for j in 0..3 {
                if x >= i && x < h + i && y >= j && y < w + j {
                    let (s, t) = (x - i, y - j);
                    if s + 2 < h && t + 2 < w {
                        let mut num = 0;
                        for u in 0..3 {
                            for v in 0..3 {
                                if let Some(_) = m1.get(&(s + u, t + v)) {
                                    num += 1;
                                }
                            }
                        }
                        {
                            let v = m.entry(num).or_insert(0);
                            *v -= 1;
                        }
                        {
                            let v = m.entry(num + 1).or_insert(0);
                            *v += 1;
                        }
                    }
                }
            }
        }
        m1.entry((x, y)).or_insert(true);
    }

    for i in 0..10 {
        let v = m.entry(i).or_insert(0);
        println!("{}", v)
    }
}

use proconio::input;
use proconio::marker::*;
use std::collections::HashMap;

pub const ALL_DIRS: [(isize, isize); 8] = [
    // 時計回り
    (-1, 0),  // 上
    (-1, 1),  // 右上
    (0, 1),   // 右
    (1, 1),   // 右下
    (1, 0),   // 下
    (1, -1),  // 左下
    (0, -1),  // 左
    (-1, -1), // 左上
];

fn main() {
    input! {
        h: usize, w: usize, n: usize,
        abv: [(Usize1, Usize1); n]
    };

    let is_ok = |i: usize, j: usize| -> bool { i > 0 && i < h - 1 && j > 0 && j < w - 1 };
    let mut table = HashMap::new();
    for (a, b) in abv {
        let i = a;
        let j = b;
        if is_ok(i, j) {
            *table.entry((i, j)).or_insert(0) += 1;
        }
        for &(di, dj) in &ALL_DIRS {
            let new_i = i as isize + di;
            let new_j = j as isize + dj;
            if new_i < 0 || new_i >= h as isize || new_j < 0 || new_j >= w as isize {
                continue;
            }
            let new_i = new_i as usize;
            let new_j = new_j as usize;
            if is_ok(new_i, new_j) {
                *table.entry((new_i, new_j)).or_insert(0) += 1;
            }
        }
    }
    let all_count = (w - 3 + 1) * (h - 3 + 1);
    let mut counts = vec![0; 10];
    for (_, c) in table {
        counts[c] += 1;
    }
    let zero_count = all_count - counts.iter().skip(1).sum::<usize>();
    counts[0] = zero_count;
    for c in counts {
        println!("{}", c);
    }
}

