    let mut cand = HashSet::new();

    for i in 0..n {
        let (a, b) = ab[i];
        for j in 0..3 {
            if a + j < 2 || a + j >= h + 2 { continue; }
            let py = a + j - 2;
            for k in 0..3 {
                if b + k < 2 || b + k >= w + 2 { continue; }
                let px = b + k - 2;
                if py + 2 < h && px + 2 < w {
                    cand.insert((py, px));
                }
            }
        }
    }

    for &(py, px) in cand.iter() {
        let mut sum = 0;
        for l in 0..3 {
            let qy = py + l;
            for m in 0..3 {
                let qx = px + m;
                match dy.get(&qy) {
                    Some(&ry) => {
                        match dx.get(&qx) {
                            Some(&rx) => { sum += t[ry][rx]; }
                            _ => { sum += 0; }
                        }
                    }
                    _ => { sum += 0; }
                }
            }
        }
        ans[sum] += 1;
    }
    let zero = (h - 2) * (w - 2) - ans.iter().sum::<usize>();
    let mut a = zero.to_string() + "\n";
    for i in 1..10 {
        a = a + &(ans[i].to_string()) + "\n";
    }
    print!("{}", a);
}

