fn main(){
    input!{
        h:usize,
        w:usize,
        n:usize,
        ab:[(usize, usize);n],
    }
    let mut d = vec![0;10];
    let mut used:HashSet<(usize, usize)> = HashSet::new();
    let mut b:HashSet<(usize, usize)> = HashSet::new();
    for i in 0..n{
        b.insert((ab[i].0, ab[i].1));
    }
    let dx = vec![-1, 0, 1];
    let dy = vec![-1, 0, 1];
    for i in 0..n{
        for j in 0..3{
            for k in 0..3{
                let cx = ab[i].0 as i64 + dx[j];
                let cy = ab[i].1 as i64 + dy[k];
                if 1<cx && (cx as i64)<(h as i64) && 1<cy && (cy as i64)<(w as i64){
                    let cx = cx as usize;
                    let cy = cy as usize;

                    if used.contains(&(cx, cy)){
                        continue;
                    }
                    let mut num = 0;
                    for l in 0..3{
                        for m in 0..3{
                            let c1 = cx as i64 + dx[l];
                            let c2 = cy as i64 + dy[m];
                            let c1 = c1 as usize;
                            let c2 = c2 as usize;
                            if b.contains(&(c1, c2)){
                                num += 1;
                            }
                        }
                    }
                    d[num] += 1;
                    used.insert( (cx, cy));
                }
            }
        }
    }
    let mut sum = 0;
    for i in 0..10{
        sum += d[i];
    }
    d[0] = (h-2)*(w-2)-sum;
    for i in 0..d.len(){
        println!("{}", d[i]);
    }





}

use std::collections::HashMap;

#[allow(unused_macros)]
macro_rules! scan {
    () => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.trim().to_string()
        }
    };
    (;;) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.trim().split_whitespace().map(|s| s.to_string()).collect::<Vec<String>>()
        }
    };
    (;;$n:expr) => {
        {
            (0..$n).map(|_| scan!()).collect::<Vec<_>>()
        }
    };
    ($t:ty) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.trim().parse::<$t>().unwrap()
        }
    };
    ($($t:ty),*) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            let mut iter = line.split_whitespace();
            (
                $(iter.next().unwrap().parse::<$t>().unwrap(),)*
            )
        }
    };
    ($t:ty;;) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.split_whitespace()
                .map(|t| t.parse::<$t>().unwrap())
                .collect::<Vec<_>>()
        }
    };
    ($t:ty;;$n:expr) => {
        (0..$n).map(|_| scan!($t;;)).collect::<Vec<_>>()
    };
    ($t:ty; $n:expr) => {
        (0..$n).map(|_|
                    scan!($t)
        ).collect::<Vec<_>>()
    };
    ($($t:ty),*; $n:expr) => {
        (0..$n).map(|_|
                    scan!($($t),*)
        ).collect::<Vec<_>>()
    };
}

fn main() {
    let (h, w, n) = scan!(usize, usize, usize);
    let mut m: HashMap<_, _> = [(0, (h - 3 + 1) * (w - 3 + 1))].iter().cloned().collect();
    let mut m1: HashMap<(usize, usize), bool> = HashMap::new();

    for _ in 0..n {
        let (mut x, mut y) = scan!(usize, usize);
        x -= 1;
        y -= 1;
        for i in 0..3 {
            for j in 0..3 {
                if x >= i && x < h + i && y >= j && y < w + j {
                    let (s, t) = (x - i, y - j);
                    if s + 2 < h && t + 2 < w {
                        let mut num = 0;
                        for u in 0..3 {
                            for v in 0..3 {
                                if let Some(_) = m1.get(&(s + u, t + v)) {
                                    num += 1;
                                }
                            }
                        }
                        let v = m.entry(num).or_insert(0);
                        *v -= 1;
                        let v = m.entry(num + 1).or_insert(0);
                        *v += 1;
                    }
                }
            }
        }
        m1.entry((x, y)).or_insert(true);
    }

    for i in 0..10 {
        let v = m.entry(i).or_insert(0);
        println!("{}", v)
    }
}
